/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220117-6","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"区民委員会","time":"午後 １時００分～午後 ４時４９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"聴取の順番を変更し、先に(5)「品川区オリンピック・パラリンピック特設サイト」および各種ＳＮＳによる情報発信の終了","agenda":"聴取の順番を変更し、先に(5)「品川区オリンピック・パラリンピック特設サイト」および各種ＳＮＳによる情報発信の終了","exchanges":[{"speaker":"くにば委員","kind":"意見","question":"情報発信の役目を終えたからといって、基本的にインターネットというメディアは、アーカイブして情報を後からでもたどって見られるということが非常に大きなレガシーの１つという部分もありますし、例えば特設サイトについては、ドメインの維持管理に継続的に経費が必要だからというような理由で、品川区のホームページの中にマージして閉鎖するというのは、ある程度、一定理解はできるのですけれども。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区全体の方針として、ツイッター、インスタグラムに関しては、区全体の公式のものがあります。","id":"exchange-001"},{"speaker":"くにば委員","kind":"質問","question":"これ以上更新をしないのでツイッターのアカウントは、もう要らないよねということにはならないかなと思います。特にツイッターのアカウントは、経費がかからないのであれば、情報発信をしないからもう要らないよねということにはならないと思うのですが、そこに関しての相違、認識を埋められればなと思うのですけれども、もう一度、閉鎖をする必要があるかどうか見解をお伺いしたいです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"インスタグラムが、情報発信の役割を終えた後もそのままアカウントを持っておく必要があるのではというご質問かと思うのですが、そのまま持っている必要性もないと考えておりましたので、こちらは閉鎖することといたしました。","id":"exchange-002"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今そうなっているのだというのが正直なところなのですけれども、ちょっと伺いたいのですが、１７地区のスポレク推進委員会が４地区に発展的に統合して、面的なつながりを強めていったということで、横の連携を取ることはとても大事だと思っています。一方で、今までのそれぞれのスポレク推進委員会の利用調整というのはどういう形で残っているのか、そこを伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"それとは別に、学校の放課後の時間、夜の６時ぐらいまでの間は学校の主体的な意思で貸出しをされておりますので、そこのところはまた予算的にも全然別の扱いとなってまいります。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"まだ経過を今見ている状況なのかなとは思いますけれども、地域ごとのカラーもしっかりと活かしながら、横の取組を強めていければなと思います。それは意見です。同時に聞いてしまいます。あわせて、７ページ目、「スポーツの力による交流やにぎわいの創出」ということでありますけれども、ずばり、スポーツの名の下に再開発事業を広げていくという考えがあるのかないのか、そこを伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"確かに施設のいろいろな、学校の体育館の条件とかでなかなかできない種目もありますが、例えば歴史が古いのは、荏原Ｂ地域スポーツクラブでやっております、旗の台地区が入ってございまして、心身障害者福祉会館等あります関係で。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区スポーツ推進計画は施設の計画ではないということでしたけれども、一言意見だけ。一方で、障害があるがゆえに、なかなかスポーツに参加できない、ハードルがどうしても高く感じてしまう。現役を引退された方でも、日々の生活のためにパートをしなければならないという方も含めて、定年退職後も誰もが気軽にスポーツに参加できるように、そうした環境整備を強く求めていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"西村委員","kind":"質問・要望","question":"こういったプロスポーツチームの取組をぜひ強化していただきたいなと思っておりまして、今後の活動予定のところで、令和４年度についても調整を区とクラブで進めていくと書いていらっしゃる部分で、どれぐらい年間の開催が計画されているのかということと、あと、プロスポーツの連携事業で、学校数が多いので全てにとはいかないと思うのですが。","respondent":"中元スポーツ推進課長","answer":"バスケットボールは、今度の３月に初めてやる予定です。こちらはまだ皆さんにもご案内できる段階に至っていなくて、もう１か月ぐらいしたら、来月の区民委員会ではご案内できるかなと思うのですが、その辺の状況を見まして、何試合というところも出てくるのかなと。","id":"exchange-006"},{"speaker":"くにば委員","kind":"質問","question":"伺いたい部分、まず１点目が、各スポーツクラブに属している団体、例えば大井八潮地域スポーツクラブＴＯＹＳですと１５４団体、荏原Ｂ地域スポーツクラブですと１８２団体、それぞれ非常に多くの団体の方々が参加されているのですけれども、個別にどのような団体が所属されているのか。例えばスポクラ・しながわは、ホームページが４つのクラブで唯一あります。","respondent":"中元スポーツ推進課長","answer":"あくまで紙ベースの情報が主体となっていて、それを自分のエリアの区の施設に置いていらっしゃるような形になっています。","id":"exchange-007"},{"speaker":"くにば委員","kind":"意見","question":"そこで、例えば広報しながわで、それぞれのスポーツクラブの中で紹介してほしいサークルを募って、例えば年に１回、スポーツ特集号を広報しながわで発行して、そこで各地域のスポーツ、直接各サークル、こういったサークルがありますよというのをご紹介するような形で、多くの区民の方に届けることが例えばひとつできるかなと思うのですけれども、もしくは、転入される際に窓口で。","respondent":"中元スポーツ推進課長","answer":"広報しながわでは、今、やはりコロナの影響で、そういう情報に注力されているところもあって、なかなか難しいのですが、その前の時期、私が異動してきたすぐのとき、４年ぐらい前に、スポーツ推進委員や地域スポーツクラブの紹介を一面とかでやりました。","id":"exchange-008"},{"speaker":"くにば委員","kind":"意見","question":"各地域スポーツクラブの皆様は、頑張ってスポーツの普及という部分に関しても努力されていることだと思いますので、ぜひとも区の努力という部分で、皆さんの情報を区民の方々にお伝えできる方法を考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"幾つか伺ってまいります。品川区スポーツ推進計画の部分なのですけれども、概要版の３ページの数値目標のところで現状値５７.６％とあるのですが、昨年なのですけれども、概要版ではなく全体版の部分のところも拝見させていただいた上での確認なのですけれども、定期的に実施している層の方が、現状値、令和元年度は５７.６％ということでよろしいのでしょうか。","respondent":"中元スポーツ推進課長","answer":"成人の週１回以上のスポーツの実施率、こちらは国のほうでも何％以上にしましょうというのが示されておりまして、その目標値は、国がたしか６５％で、東京都が７０％なのです。","id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらの計画については、そのような形で理解いたしました。ただ、今後というところに関してなのですけれども、国と都の目標値ですとか計画はそのようになっているのですが、やはり不定期実施層であったり非実施層の方、こちらに向けた施策も考えていかなければいけないのかなと思っておりまして、その辺りのお考えについてありましたら、お聞かせいただきたいなと思っています。","respondent":"中元スポーツ推進課長","answer":"そこで出てきたのがこの地域スポーツクラブという考え方ということで、国のほうでも説明をされております。ですので、委員おっしゃったように、今後、教育委員会とも情報提供の部分で連携できるところについて話をしながら取り組んでいきたいなと考えています。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほどの前段のほうの質問なのですけれども、不定期実施層や非実施層の方々に対する部分で、現在の区の考え方だったりが何かありましたらお聞かせいただきたいというのをもう一度確認させていただけたらと思います。計画の中にも運動を楽しむというようなキーワードが幾つか出てきたかなと思います。その辺りについて、区のお考えを教えてほしいなと思います。","respondent":"中元スポーツ推進課長","answer":"区のほうでも、コロナで毎回諦めているのですが、ジュニアスポーツフェスタといいまして、ちょうど小学校に上がるぐらいのお子さんを対象に、区内にある少年少女スポーツの団体の４種目、サッカー、野球、バレーボール、バスケットボールの体験コーナーがあって。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"女性は割とそういう健康に関しても、３０代、４０代の方、感度が高い方が多いかなと思うのですが、特に男性でお一人暮らしの方はなかなかそういう機会がないというのが私はすごく課題に思っていまして、その辺りもまた今回の流れとは別のところでぜひ検討していっていただきたいなと考えていますので、こちらは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"品川区地域スポーツクラブが４つあるということで、それぞれどういう方たちが運営主体になっているのか。例えば専門家といいますか、先ほど障害者施設で教えていらっしゃる方もいるとおっしゃっていましたが、どういうお立場の方がいらっしゃるのか、また、専門的な資格を何か持っていらっしゃる方、そういう方も各ブロックにいらっしゃるのかなど、そういうお立場的なところを一つお伺いしたいと思います。","respondent":"中元スポーツ推進課長","answer":"やはりいろいろなご質問とかがあったときに、地域の方同士ですとなかなか難しいときには、スポーツ推進委員が経験とか知識を活かしてご対応してくださったりしている状態で、そのような形でサポートしている形になります。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ありがとうございました。特に好成績を残された方の情報は、ご本人の意向もあるということが一番大きいというお話ですが、できる場をつくっていただいて、ぜひ顕彰していただきたいなと思いますし、また、それが励みになっていくとチームとしてもいいのかなと思いますので、ぜひそういう顕彰の場はご検討いただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"スポーツ大使退任式について伺いたいのですけれども、こちら、予算は１１８万円余ということで、会場として第三庁舎を使うという中で、この予算、１１８万円の内訳を教えていただきたいです。これは例えばギャラが発生するのであるかとか、記念品に予算がかかるであるとか、内訳に関してお教えください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"退任式の予算の内訳です。委員おっしゃるとおり、まずギャラです。報償費と、業者の進行台本の作成、振り返りのＶＴＲ作成、それから当日スタッフの運営経費、花束等が含まれているところです。","id":"exchange-016"},{"speaker":"くにば委員","kind":"確認","question":"退任式については承知いたしました。これに関しては、基本的に東京都が全て施設管理者や指定管理者に支払うと思うのですけれども、確認ですが、これは品川区に、今後一切、この赤字に関して負担が発生しないのかどうか、確認だけさせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大井ホッケー競技場の赤字のお話ですが、品川区にその負担はございません。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"区にどの程度、東京都のほうから施設利用に関して、例えば勧奨してほしいであるとか、施設利用に関して推進する何か施策をしてほしいだとか、そういった東京都からの連携であるとかアプローチというのはあるのでしょうか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"大井ホッケー競技場ですが、ホッケー協会を中心とした大きな大会が開かれたりですとか、もちろん区のほうにも、区で利用する場合にはぜひということでお話は頂いておりまして、優先的に利用させていただけるようにはなっております。","id":"exchange-018"},{"speaker":"くにば委員","kind":"意見","question":"八潮の大井ホッケー競技場ということで、可能な限り、せっかくの施設ですので、品川区としてもこの施設を有効利用して、今後、八潮地域の何か観光資源に寄与していっていただければと思いますので、その点、ぜひともホッケー以外の競技でも活用していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"新妻副委員長","kind":"質問","question":"スポーツ大使の退任式について、この３人の方に大使を務めていただいて、今回、退任されるということなのですが、今後、何かスポーツというところで、東京２０２０大会のレガシーとして、この３人の方が活躍される場が区として何かあるのかというところだけ、１点お伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"３人の方の今後ということなのですが、特に今から予算化してということはないのですけれども、区内在住であったり、品川区をホームとするチームにいる方ですので、ぜひまたそういう機会があったときにはお願いしたいと考えています。","id":"exchange-020"}]},{"id":"topic-04","title":"(1)令和３年度町会・自治会活動活性化促進調査の報告書","agenda":"(1)令和３年度町会・自治会活動活性化促進調査の報告書","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"順次伺っていきます。ここの中で、今後に関しても可能な限り町会・自治会の負担を減らすように、様々な調整をしていくと、そのような必要性が書いてあったのですけれども、今回、軽減ができた実際の事例というか、どのようなことを町会・自治会に協力依頼するのをやめたから、負担が減ったのか、具体的な取組であるとか内容についてお伺いしたいです。","respondent":"川島地域活動課長","answer":"そういったことを繰り返し行ってきた結果、今回のアンケート結果の負担軽減というお答えをしていただけることが多くなったというところにつながったと考えているところです。","id":"exchange-021"},{"speaker":"くにば委員","kind":"意見","question":"幾つか具体的な事例、例えば今、ざっくり言うと、チラシの配布であるとか、そういった手間を減らしたであるとか、その点のみ分かったのですけれども、何かこういったことをやめれば実際に減ったという、もう少し具体的な事例を幾つかご紹介いただければと思うのですが。","respondent":"川島地域活動課長","answer":"代理出席ができないとかという話もあったものですけれども、代理出席を認めてくださいという話、それから出られないものは出られないのだというようなところも、本当に真面目な町会長は、万難を排してというのでしょうか。","id":"exchange-022"},{"speaker":"くにば委員","kind":"意見","question":"めくって、４.町会・自治会の現状と課題というところの2)地域全体でメリットを感じられるようなというところの右側、現状と課題の部分、ここで、それぞれ補助金に関して、この後も出てくるのですけれども、補助金が町会・自治会のニーズと合っていないといった意見もあったとありますが、具体的にこれは、こんな補助金のメニューがあるけれども、実際こんなのは使われないよとか。","respondent":"川島地域活動課長","answer":"その辺は、毎年、町会長会議で私ども補助制度の説明をしておりまして、生の声ででも直接聞いておりますので、今回の調査結果も含めて、しっかり反映してやっていきたいと考えています。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問","question":"そのような中で、なぜＳＮＳ、このツイッター、フェイスブックが不特定多数の方が閲覧可能であって不向きという意見になっているのかというのがちょっと腑に落ちなかったので、それについて何かお聞きになられている内容があればお知らせください。","respondent":"川島地域活動課長","answer":"多分この抜き取り方もあるのですが、たしかに鍵アカにすればというのもあるのですけれども、町会の役員ですとか、それから活動の連絡とかに使うというところでいうと、ＬＩＮＥのほうが使いやすいという、そういったようなニュアンスだったと記憶しているのですが。","id":"exchange-024"},{"speaker":"くにば委員","kind":"意見","question":"これの上から４点目、増加するマンションをいかに巻き込んでいくかは課題としてあるというところで、若い人がいないのではなく、若い人と接点がないのが課題という部分、若い人との接点をどのように作るか、これに関して区からどのようなアドバイスをしているのか、どのような施策が若い人との接点を作るという部分に寄与する解決策になるのか、そこについてのお考えをお聞かせください。","respondent":"川島地域活動課長","answer":"なかなかこちらも非常に難しくて、どうすればしっかりそのような形につながっていくのかというのは難しいのですけれども、１つ例として挙げられるのが、子どもの参加するイベントというようなところで、子どもが参加すれば親もセットで。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問・要望","question":"ですので、そこに関して、もちろんこの町会の幹部の方々のお考えもあると思いますけれども、そういった考えも一つあるのではないかという部分も、例えば区のほうから、なかなか言いづらいかとは思うのですが、そういった見方もあるみたいなことをお伝えしたほうがいいのかなとふと思ったのですけれども、この辺についてお考えはいかがでしょうか。","respondent":"川島地域活動課長","answer":"ですので、正解・不正解というところではなくて、当然、町会長たちもその辺はご存じかと思いますので、こういったいろいろなアイデアも取り入れながら、町会・自治会活動の参考にしてくださいというような意味で、報告書のほうは説明させていただきたいと考えています。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"町会・自治会の方々がずっと掲げられている若い方々の参加という部分で、町会の方々がなかなかずっと考え続けて、それでもやはり若い方々の参加が伸び悩んでいるという現状があるので、そこを１つでも多く、行政のほうから、また違う視点で、今の若い人たちはどういうことを求めているのか、若い人たちに向けて、町会・自治会の割と高齢の役員の方々が考える以外の物の見方、目線。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ質問します。具体的に、この先、どういうふうにお考えになっているのか。防災課との連携はすごく重要だと思うのです。それが今、密に取れているかというと、取れているときもあるし、取れていないときもあるのかなと思っているのですけれども、もう少し連携をしていただきたいというのがあるので、今後の展開だけ教えていただきたいと思います。","respondent":"川島地域活動課長","answer":"地域と防災活動というのは切っても切れないところがありますので、これは私どもも積極的に、防災課とは何かあるごとに、その辺の地域への説明ですとか、それから事業があるときの打合せも含めて。","id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今、課長からご答弁があったように、ぜひ積極的に防災課とも連携して、強固にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"横山委員","kind":"確認","question":"８ページのところなのですけれども、地域センターの役割のところで、今、防災課の話が高橋伸明委員からもありましたが、職員の業務量が増加傾向にあるということなのですけれども、こちらは防災のお話だけではなくて具体的にどのようなことがあるのかというところを確認させていただけたらと思います。","respondent":"川島地域活動課長","answer":"地域のイベント、今はコロナ禍でなかなかできないような形にはなっておりますけれども、こちらもいろいろ新たな、地区委員会事業ですとか町会関係のイベント等をやっていく中で、そういったところも業務が増えてきているというような。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問","question":"区全体でいろいろな新しい事業等があると、それに伴って業務量が増えているというところでよろしかったでしょうか。それに対して、やはり新しいことですと、区民の方々、町会・自治会の皆さんも慣れていないので、そういった問合せ業務等で業務が煩雑になってしまっていたりですとか、様々整理しなければならないという状況にあるということでよろしかったでしょうか。","respondent":"川島地域活動課長","answer":"業務が煩雑になるとかという話ではなくて、業務量が増加気味であるというのが職員の認識としてあったというようなことですので、こちらのほうも効率的な業務に努めながらしっかり遂行していると考えているところです。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。すみません、ちょっと勘違いしているところがあるようでした。ぜひ取り組んでいただきたいなと私は思っているところです。１２ページの木密地域のモデル事業、防災課と連携したモデル事業を行うということが考えられるという部分なのですけれども、こちらはどういった内容になってくるのでしょうか。まだ検討中なのかもしれないのですが、イメージが分かれば教えてください。","respondent":"川島地域活動課長","answer":"ただ、先ほども申しましたとおり、防災課と地域とのつながりというのは非常に重要なところがありますので、その辺の連携は密にしていく必要があると私ども思っているところです。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。最後なのですけれども、先ほどマンションへの働きかけのお話があったかなと思います。実際には、区のほうでできること、あとはなかなか現実的に、先方もあるので難しい部分もあると思うのですが、その辺りの実感としてはどのように区として感じていらっしゃるでしょうか。","respondent":"川島地域活動課長","answer":"手法は様々考えられるところですが、その辺を何かお手伝いできないかということを今考えております。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほどの防災課とのモデル事業のイメージの中に関係してくるかなと思うのですけれども、マンションの方々も、やはり防災というところは地域との連携というところで気にしていらしている方も、入居されてから多いのかなと思いますので、そうした防災に絡めての何かであったりですとか、様々、地域活動課を中心に、地域の方々の実際入居されてからのニーズみたいなものも捉えていただきながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"新妻副委員長","kind":"質問","question":"１点だけお伺いします。アンケートの回答数が８５％ということで、アンケート調査としてはかなり高いパーセントだと思います。その３０町会・自治会は、どこが出ていないのかというのは当然把握されているということでよろしいでしょうか。なぜここの３０町会・自治会が出されなかったのか、理由を把握されているのかというところをお伺いしたいのですが。","respondent":"川島地域活動課長","answer":"こちら、回答率８５.１％ということで、地域別に公表しているところですので、八潮地区の回答率が４６.４％ということで、自治会の皆様がなかなか回答できなかったということで、推測ですけれども、例えば毎年、輪番制で自治会長が決まっていったりだとか。","id":"exchange-035"},{"speaker":"新妻副委員長","kind":"意見","question":"自治会の、特に団地の自治会というのは、いわゆる平屋地域の町会とは少し考え方が違うと思いますし、確かに１年ごとに自治会長が変わっています。自治会の運営とかにも課題が、負担があるわけで、アンケートが出されれば別にいいというわけではないのですけれども、そういうところにもまた支援の目をぜひ向けていただいて、独特な地域でありますけれども、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"西村委員","kind":"質問・要望","question":"私からも要望で、やはり地域の方から言われること、この結果にしっかり書かれているなと思っていまして、３、４ページにある町会の手続の簡素化と申請の効率化は何とかなりませんかとよく言われますので、ぜひ要望させていただきたいのと、あと、コロナ禍において区からの助言が欲しいというのは、イベント開催時などに言われますので、その辺り、どのようにフィードバックされたのか、伺わせてください。","respondent":"川島地域活動課長","answer":"防災訓練等の事例です。ぜひお知らせいただいた上で、こちらもほかの地域にお伝えするようなところがございましたら、それも周知のお手伝いをしていきたいと思います。どんな媒体を使ってやるのかというのはありますが、その辺のご意見も参考にしたいと考えています。","id":"exchange-037"}]},{"id":"topic-05","title":"ワクチンパスポートアプリ","agenda":"ワクチンパスポートアプリ","exchanges":[{"speaker":"くにば委員","kind":"意見","question":"いろいろと調べてみたのですが、このワクチンパスポートアプリは、基本的に自治体で問合せを受け付けていないように思うのです。そもそも問合せを区で受け付けようと思った経緯であるとか、あとは、それぞれの地域センターの担当の方がどれだけ対応できるのか、どういう体制を取ったらこのアプリに関する問合せに対応できているのか、その２点をまずお聞かせください。","respondent":"木村戸籍住民課長","answer":"ご案内のとおり、かなり多岐にわたりますので、大変な部分ありますけれども、そこはしっかりお話を聞きながらやるという感じで進めてまいりたいと考えています。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問・要望","question":"これは本当にすばらしい取組だと思います。経費等もかかると思いますので大変な部分もあると思いますけれども、ぜひ頑張っていただきたいと思います。その点、直近で構わないので、推移が、例えば紙証明のほうはアプリが公開されてからぐんと減って、アプリに移っていったという、現在の比率であるとか状況をお伺いしたいです。","respondent":"木村戸籍住民課長","answer":"ざっくりではありますけれども、８割方が今、アプリとなります。委員おっしゃったように、アプリがスタートしてから、紙による発行はがくっと減っています。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問・要望","question":"私も早速アプリをダウンロードして使ってみましたけれども、意外とアンドロイドのアプリ、評判が悪いものが多く、特に行政が発行しているアプリ等は、使い勝手が悪いとかトラブルが多いという評判だったのですけれども、このアプリに関しては非常に評判もいいみたいで、トラブルも少ないようで、ぜひ交付窓口に関して業務が減る部分、やはりデジタル化で寄与できるのかなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-06","title":"デジタル社会の実現に向けた証明書発行等業務の新たな取り組み","agenda":"デジタル社会の実現に向けた証明書発行等業務の新たな取り組み","exchanges":[{"speaker":"新妻副委員長","kind":"質問","question":"説明が終わりました。ご質疑ございませんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"くにば委員","kind":"意見","question":"最終判断はいつぐらいで設定しているのかという部分が１点と、その他の様々なイベントも、昨年、おととしとキャンセルになってしまいましたけれども、今回、このしながわ展がキャンセルされるとなれば、例えば設営の経費であるとかポスター・チラシ作成代といった既に支出てしまっているものとかやむを得ないものもあると思うのですが、キャンセルになった場合、実際どれぐらいの損失が出るか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの実施の判断ですけれども、特に期限をいつまでにというところではございません。","id":"exchange-042"},{"speaker":"くにば委員","kind":"確認","question":"基本的には開催する方向であると。どうしても厳しい判断をせざるを得ないときはやむを得ないがという方向性をおおむね確認できました。この使用料の内訳をお聞きしたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"きゅりあんの使用料につきましては、金曜日から設営をする形になりまして、また、駐車料金なども含めて６５万円ぐらいの予定になっております。","id":"exchange-043"},{"speaker":"くにば委員","kind":"意見","question":"それぞれ承知いたしました。これはもう３１回目のイベントということで、残念ながら昨年中止になってしまいましたが、ぜひ今回、私もこれが実施されるのであれば行きたいなと思っている、非常に内容もすばらしいものだと思いますので、開催できることを祈っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/277018?Template=document&Id=2918#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":47979,"voices":120}},{"id":"r04-20220117-7","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","topics":[{"id":"topic-01","title":"（仮称）小山七丁目障害者グループホームの整備","agenda":"（仮称）小山七丁目障害者グループホームの整備","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"どのような経過でこの土地が取得されることになったのかを伺いたいのですけれども、民有地が売り出されているものを買いますとなったのか、それとも区が探して、見つけ出して取得したのかという、どのような経過で取得したのかということと、あと、どのように探し当てるのか分からないのですが、これからもそのようなところがあれば買っていく、取得していくという方針というか、そのようなものなのか。","respondent":"松山障害者福祉課長","answer":"ただし、土地の条件や様々な近隣の状況、地域の状況なども踏まえまして、その都度検討し、決定していくという方針です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、山口銀行のほうから区のほうにどうでしょうかということでお話があったと。特に福祉施設にとか、そのような条件などはなく、区のほうで取得していただければ使ってくださいということで、それで庁内で話した中で、障害者グループホームへということになったということなのか。そのような条件提示などはなかったのかということを伺います。","respondent":"松山障害者福祉課長","answer":"ただ、庁内では、やはり福祉施設というところで整備をしたいということで、この間検討をしてまいりまして、昨今、やはり障害者グループホームというものが必要であったことから。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。そうすると、このグループホームについては、対象は知的障害とか、精神障害とか、そこはどのように考えられているのか。４１４m2ですので、何人ぐらいの定員になるのか。それで、幾らぐらいで取得をされたのか、金額も分かれば教えていただきたいのですが。","respondent":"松山障害者福祉課長","answer":"と申しますのは、本年度に入りまして、これまで４か所のグループホームを、民間事業者が既存の建物を使いまして整備してきましたが、４か所いずれも精神障害者の方が対象ということで、精神障害者の方のグループホームは。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それと、まだ先の話になると思うのですけれども、運営形態などはもう考えていらっしゃるのか。区立なのか、区立で指定管理なのかというところの検討はもうあるのでしょうか。","respondent":"松山障害者福祉課長","answer":"こちらの資料にも書かせていただいたとおり、４のスケジュールの米印ですが、設計以降は選定事業者にて実施予定ということで、用地を取得しました以降は、その用地を民間事業者に貸付けを行いまして、民間事業者が設計し、運営していくという予定です。","id":"exchange-004"}]},{"id":"topic-02","title":"住民税非課税世帯等に対する臨時特別給付金","agenda":"住民税非課税世帯等に対する臨時特別給付金","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"前回の補正予算の審査ときにも、やはり周知、丁寧な周知が本当に必要だと、各委員からも出されたと思うのです。特に家計急変世帯です。それで、年収だったり、月額の収入だったりが、このような人だと分かるように説明や周知をされるのかということをちょっと確認したいと思います。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"周知方法について、特に自分が対象となるか分かる形で、年収というか、収入の目安のようなものについては、ホームページと、あとチラシを、これからまた検討してまいります。そちらのほうでどのような形で載せられるかということで、ちょっと分かりやすくできればと考えています。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"相談のところなのですけれども、相談ブース開設は第二庁舎の３階ということなのですが、これは今、暮らし・しごと応援センターの相談ブースも確保するのがなかなか大変な状況があると思うのですけれども、あそこの暮らし・しごと応援センターの相談ブースを使うということになるのでしょうか。その相談を誰がやるのかということと、場所は具体的にどこなのかということを教えてください。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"相談の場所ですが、今予定していますのは、暮らし・しごと応援センターの隣に部屋がありますので、そちらの部屋を１つ確保しているのと、あとは今、マイナンバーカードの交付をやっているエリアの隣に、昔、シナモロールの像があったところがあると思います。","id":"exchange-006"},{"speaker":"せお委員","kind":"確認","question":"ちょっと確認なのですけれども、この申請方法のところで、区が口座情報を把握できているとか、できていないとあるのですが、これは区がということでよろしいのですか。例えば生活福祉課が把握しているとか、そういったことではないのか、ちょっと教えてください。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"今のところ国のほうから示されている、活用できる口座情報としましては、特別定額給付金と、あとは昨年１２月に支給された子ども世帯向けの臨時給付金、それと生活保護を受けている方については生活保護費の振込口座というようなことになっておりますので。","id":"exchange-007"},{"speaker":"若林委員","kind":"確認","question":"資料の裏面の周知方法の「暮らし・しごと応援センター、地域センター等」の、この「等」の内容ですけれども、ふれあい掲示板など、そのようなところも想定されている、予定されているかなという、そこの確認というか、お願いします。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"ご指摘いただきましたとおり、ふれあい掲示板のほか、区有施設に、例えば図書館等も含めて、これから調整という形になりますが、できる限り掲示するような方向で考えております。","id":"exchange-008"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"資料の２の発達障害の概要のところで、人数というところです。ですので、もっといるのだろうなという状況が見てとれたと思うのですけれども、そのような中で、今区が把握されている発達障害の方というのは、区民で、どれくらいの人数がいるのか、教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"この発達障害者相談支援センターへいらっしゃる方も、発達障害ということで認定されてからいらっしゃるのではなく、ご自身で悩みごとがあるということでいらっしゃっていますので、障害者として診断が出ている方が全てここにくるわけではないですので、正確な数としては。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"確かに正確な数は、診断が出ても、そうした手帳だったり、支援につながっていなければ分からないと思うので、分かる範囲では、そうした手帳を持っていたり、支援につながっている方というところで区の把握している人数というのは、何人ぐらいなのでしょうか。","respondent":"松山障害者福祉課長","answer":"先ほど申しましたように、特に発達障害者だからということで統計を取っているものではございませんので、正確な人数は把握しかねます。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"ですので、発達障害という、障害福祉計画の中にも発達障害という項があって書かれているわけではない、計画があるわけではないですよね。ですので、この発達障害に特化して把握していないというところも、私は何かもう少し、これだけ多くの方がいる中で把握するべきではないかなと、もうそのような時期なのではないかと思うのですけれども、その辺は区としてはどのように考えていらっしゃいますか。","respondent":"松山障害者福祉課長","answer":"そのため、相談員が訪問をして、本人はお困りではないということですけれども、できるだけご家族として包括的に支援をしていくというものですので、なかなか正確な数というのが非常に難しいところではありますが。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほども説明があったとおり、出方の濃淡では本当に分かりづらいということもハンドブックのほうには書かれていました。子どものときに診断をされて、特別支援教室や特別支援学級、学習支援員がついたりということもあると思うのですけれども、このようなところから把握されている人数は、障害者福祉課としては把握されているのでしょうか。","respondent":"松山障害者福祉課長","answer":"基本的に、恐らく教育委員会の管轄になると思いますけれども、この間難しいのは、お子さんも落ち着いている時期があったり、あるいは不安定な時期があったり、非常に環境に左右されることがありますので、連携は取ってはおりますが。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"令和元年に出された文教委員会の資料で、特別支援教室、それから通級指導学級利用の児童数や、あと学習支援員の数などというものは、小学校・義務教育学校前期課程で学習支援員が、平成２５年では７３人だったものが、令和元年度になると３６６人と５倍の数になっています。ですので、そうした教育委員会との連携、その数の把握にしてもそうなのですけれども、そうしたところはあるのでしょうか。","respondent":"松山障害者福祉課長","answer":"就学相談の説明会が毎年６月上旬に開催されますけれども、就学相談が始まる前に、保護者向けに就学相談の流れ、概要を説明するために開催しているものですが、そちらも教育委員会と連携しまして、児童発達支援を利用している年長年齢のお子さんを持つ保護者と、あと品川児童学園。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで次の質問ですけれども、大人では発達障害者相談支援センターで相談を受けている人数や、発達障害者の成人期支援事業や就労継続支援Ｂ型に登録している人など、これは把握されている人数はあるのでしょうか。","respondent":"松山障害者福祉課長","answer":"発達障害に特化した地域相談支援センターをつくるということで、今回、４月から開設というものにつきましては、先ほど挙げさせていただいた相談支援センターの相談件数が７５１件です。それから就労継続支援Ｂ型のほうです。定員が２０名です。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それで今、発達障害の方というのは、発達障害という手帳はないわけですので、愛の手帳や精神障害者保健福祉手帳になってくると思うのですけれども、その愛の手帳や精神障害者保健福祉手帳を取っている方の中での発達障害の方というものは、区としては把握されていますでしょうか。","respondent":"松山障害者福祉課長","answer":"先ほども申し上げましたように、発達障害としての手帳ということではございませんので、その分、ちょっと統計が取りにくい状況にあります。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません。人数ばかり聞いているのですけれども、やはり把握して、それだけの人たちに対しての対応や支援策をどのようにしていくかということがもっともっと必要ですし、見えていない方に対しての投げかけというか、そのようなものも必要になってくると思ったので、その人数を把握されているというところがどうなのかと何度も伺ったのですけれども、分かりました。","respondent":"松山障害者福祉課長","answer":"そういったものを目にしていただいて、実際は相談に行っていただくということが一番の近道だと考えております。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうした発達障害に関する普及啓発、それは何か、どのような取り組みをされているのでしょうか。先ほど言った目黒区でいうと、クリアファイルにして、区民の目につく形で分かりやすく、そして相談先も書いてあるというような、そうした普及啓発は、区としてはどのようにされているのでしょうか。","respondent":"松山障害者福祉課長","answer":"令和２年度で、コロナ禍で人数がちょっと落ちておりますけれども、延べで３３７人の方が講演会を受講されております。オンラインでも行っておりますので、比較的参加しやすいのではないかと考えています。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"品川区地域自立支援協議会が、品川区子ども発達支援ガイドブックという、今も様々、パルレとか、ら・るーととか、ぷらーすとか、いろいろな、そのような名前が出てくるのですけれども、そういうものがまとまったガイドブックを作られていて、これというのはどのようなところで、ホームページはあったとしても、どこか配られている場所というのはあるのでしょうか。","respondent":"松山障害者福祉課長","answer":"品川区地域自立支援協議会の子ども支援部会で、事業者が集まって皆さんで作成した子ども発達支援ガイドブックなのですけれども、今また正式に印刷会社のほうに依頼をいたしまして、増刷する予定です。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それがまた今回の、平成２８年に改正された発達障害者支援法の中にも書かれているのではないかと思うのですけれども、そのような部分では、例えば広報しながわだったり、ホームページだったり、もっといろいろなところに、発達障害というのはこのようなものですよと多くの区民が理解するような、そのような取り組みというものが、まず、とても大事なことなのではないかなということを改めて思ったのですが。","respondent":"松山障害者福祉課長","answer":"実際に今、４月から相談支援センターという特化したものをつくり、そちらで発達障害ということではっきり冠をつけたというところは、区として大きなところですので、そこを発達障害者相談支援センターを核として、今後どのように分かりやすく区民にＰＲしていくかを協議しながら。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"子どもたちの特別支援教育に対しての計画というものも、ここは文教委員会ではないのでそのことについては求めませんけれども、そのような計画というものもほかの区は持っていて、そこの中には、やはり区民に対してどれだけ理解をしてもらうかという、啓発をする活動の計画というものが立てられているのです。そのような点では、品川区の取り組みはどうされているのかということについても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"区民全体への普及啓発ですが、まずは発達障害者相談支援センターといって、発達障害者を前面に出したというところでは、区民に対してアピールしたということが１つなのですが、これから発達障害者相談支援センターを核として、いかにホームページなり。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ジョブコーチがどれぐらい体制としてあるのか、ジョブコーチがついて、そのような就労をされている方というのがどれくらいいるのかも教えていただきたいと思います。それから、手帳が愛の手帳と精神障害者保健福祉手帳になると思うのですけれども、手帳がないと受けられないサービスと、手帳がなくても受けられるサービスというのは、どのようなものがあるのかも教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"それで、そのジョブコーチがつきながら、企業、あるいはハローワークのほうに付いて行って、就職した後も実際に継続できるように支援をするという形になっております。次に手帳の有無によってのサービスについてです。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけれども、そこの大学とか、そのようなところの支援というものが、たまたまその彼は、そのようなすごく気にしてくれた方がいて、大学側もこれならいいよということで行けたのですが、就労などということは、今いろいろな、このような人でもいいよと、さっき言ったアルバイトでも、ラーメン屋でもそれはできたのですけれども、その大学の就学というのか。","respondent":"松山障害者福祉課長","answer":"相談の中で、そういったようなものがあれば、個別に支援しているという状況ですけれども、体制的にとか、メニュー的にというものは整っていない状況です。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"発達支援ではなくて障害をお持ちだと、大学などだといろいろ支援がありますよね。その障害にもよるのだけれども、難聴の方だとか、いろいろな大学の支援というものがあるではないですか。発達障害というのは難しいのかもしれないのだけれども、ぜひそのようなものはメニュー化されたほうがいいかなと思っているので、ぜひそのようなものも模索していただきたい、これは要望にしておきます。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"せお委員","kind":"意見","question":"１点。今、ぷらーすでされている相談というものが、恐らく発達障害者、大人だけと認識しているのですけれども、これ、今後子どもからというような、子どもの相談も受けて、理想としてはやはり子どもから大人になってまで同じところでということがあると思うので、そういったところの今後の検討などはあるのか、お聞かせください。","respondent":"松山障害者福祉課長","answer":"ぷらーすの運営事業者である社会福祉法人げんきと実際に相談しながら、今後どのように発達障害に関わるものを進めていくかについては協議してまいります。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問","question":"だから、それは今後もあるかもしれないのですけれども、そういった流れというのはすごく重要かなと思っていて、そこの、今発達障害児ですと、相談する場所というのか、品川児童学園がすごく多いことと、あと最近増やしていただいた相談支援事業所のそれぞれのところにという形で、ばらばらとまではいかないですが、そこからのこの連携がなかなかうまくいかないなというところもあるので、ぷらーすと。","respondent":"松山障害者福祉課長","answer":"事業者連絡会を、ちょっと感染状況もありますけれども、２月に開催予定をしておりまして、その連絡会の中で情報共有を図って横のつながりをつくっていくというところが、一番目指しています。そこで相談支援全体の質のレベルアップを図ろうです。","id":"exchange-025"},{"speaker":"せお委員","kind":"質問・要望","question":"今ご答弁にあったように、本当にセンター中心にというか、そういったところで横ともそうですけれども、時系列で子どもの頃から大人のというところも、そういったところもつながっていけばいいなと考えています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、建設された当初は、ほとんど宿泊客がいないという状況だったのです。それが陳情の中にも書かれていますけれども、ですが、お客さんが来ても国内のお客さんがほとんどだったということで、そして午前１０時から午後６時まで、本当に住民の皆さんの強い求めに応じてスタッフが配置をされるということになって、確かに今は大きな混乱は起きていないということです。それで、常駐者も配置することと。","respondent":"鈴木生活衛生課長","answer":"それと、多分国のほうの回答、説明は、一般論としての考え方であって、確かに直ちに法より強度の規制を課すことが違法、もしくは違反になるものではありませんが、それについては前回の審査でもお話ししたように、似たような判例がありまして。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"常駐者を置くこともできるし、それに代わるＩＣＴの対応もできるということですので、常駐者を置くということも判断できると。それは、でも事業者の判断だということでいいのでしょうか。","respondent":"鈴木生活衛生課長","answer":"ただし、どうしても常駐の従業員を配置するとなると、そのための人件費や、それから場所の確保、部屋ですね。ロビーにただ座らせるわけにはいきませんので、そのようないろいろな準備等を考えると、事業者としては避けたいと考える事業者も多いというふうに聞いております。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"意見","question":"常駐者を置くこともできるし、それに代わる手だてでもできるということなのです。今は住宅街です。そして、事が起きてからでは遅いのだということを、今でも皆さんが口にしています。ですので区としても、地域によっては、事業者に対してそうした規制を、区民の、そして宿泊者の安全を守るためにお願いしていくべきではないかなと思いますので、私たちは、この陳情には引き続き賛成の立場です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。先ほどの説明もありましたように、今運営もされているということで、この前もご説明があったということだけれども、法を超える規制はなかなかできないという判断、それはそれで支持をしますし、我々としては、それは結論を出していただきたい。それで、不採択でお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"若林委員","kind":"意見","question":"法を超えるという部分は、厚生労働省の説明も当然道理だと思いますし、ただ、一般的に区民の、よく騒音や振動などという苦情、また、公園の使用についてどうこうという、いわゆるふだんのクレームなり、苦情なりというものは、このホテルも含めていつもあることですので、しっかり区としても、そのようなときの対応に、地域の実情をまた見ていただきながら、何かあったときは迅速に的確に関係機関と連絡。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"せお委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。私も、今は苦情はないということでしたけれども、何かもし、これから苦情がありましたら、早急に対応していただくことはお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"結論を出すで、採択です。この間も無人のホテルは建設をされていますので、次々建っていく中で、こうした多くの区民の不安が解消されているわけではないので、やはり少なくとも常駐者を配置していく、そこで１つの安心が確保されるのであれば、しかも法の規制を超えているものではありませんので、ぜひそうした立場で対応していただきたいなと思います。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。法令と条例の関係はご説明いただいて、理解をいたしました。先ほどお話がありましたけれども、事業者のほうには、区はこのような姿勢で取り組んでいるのだということを示すためにも、今後もぜひ継続的に、指導という言葉が適切かはあれですが、指導をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-04","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"濃厚接触者への対応というところで、濃厚接触者の待機期間はこれまで１４日間、それが１０日間になって、それでエッセンシャルワーカーについては５日間とか６日間、そのように濃厚接触者というところが、それは国の対応のままなのか、区の対応を聞かせていただきたいということと、あと、今第６波へ向けた体制についてということで(6)で説明いただいたのですけれども。","respondent":"鷹箸保健予防課長","answer":"当初、最終接触日をゼロ日として、１４日間は外出自粛、自宅待機をお願いしていたところですが、先週の金曜日、夜１１時４７分の通知で、それが１０日に短くなったということで、今その方針で対応しているところですけれども、次のご質問とかぶるのですが。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かれば伺いたいということと、あと保健師の体制ですけれども、今全庁応援で各部から４人という応援体制でということで、また大変な状況になっていくのかなと思うのですが、やはり長時間の過密な労働を第５波で経験して、それを教訓にというように私たちも保健師の増員等を求めてきたのですけれども、その体制というものは、第５波を教訓にどういった体制を取られているのかということを伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"医師による健康観察なのですけれども、ちょうど先週から始まったところで、我々の理解と先生方の理解がちょっとずれているところがありまして、その辺を具体的に言うと、先生方は体調が悪い人を管理しようという形で考えていらして、軽くて体調がそれほど重くなければ。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで区の施設、高齢者、障害者、保育園や学校での感染が、ちょっと聞くところによると、高齢者の施設で利用者から陽性が出たとか、そのようなものをちらほら聞くようになってきたのですけれども、この施設、高齢者や障害者の施設、保育園や学校などの感染状況というものはどうなっているのか、クラスターは出ていないのか、その辺が分かればお聞きしたいのですが。","respondent":"鷹箸保健予防課長","answer":"その方の発症前２日のときの勤務状況を確認して、施設の中での濃厚接触者がいればその方々は検査をするという、通常どおりの対応をしております。幸い高齢者施設では、今クラスターが発生したというような認識はございません。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ＮＨＫでも、１５日のところで品川区の新規感染者が１７０人というように出ていましたので、本当に第５波の２２２人でしたか、それを超えてしまうのかなというような思いで見ていたのですけれども、「品川区における新型コロナウイルス感染症患者数等について」という、１週間ごとに出していただいているので、これ、自宅療養者が、１２月末までは４人だったものが。","respondent":"鷹箸保健予防課長","answer":"エッセンシャルワーカーですが、うちのほうでエッセンシャルワーカーをここからここまでと決めるのではなく、要は６日目以降で抗原検査をして陰性になったらということは、抗原検査をできるということが前提になるので、多くはご相談のあったときに。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それからあと、ＰＣＲ検査の結果がプラスになった方の自宅療養者となった患者への健康観察が、診断したドクターやかかりつけの医者などが健康観察をしていくということなのですけれども、基本的にそちらがしていくということになって、若い人はＬＩＮＥなどでの健康観察の報告をしてもらうというようなことがあると思うのですが、そこのかかりつけのドクター、また診断したドクターが健康観察をする。","respondent":"鷹箸保健予防課長","answer":"医師による健康観察のすみ分けですけれども、それは発生届の備考欄に、自分が健康観察をしますというように書いていただいて届けていただくと、我々のほうで、この患者は先生のほうで健康観察をやってくれるのだなということが分かって。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今の説明で、そのような仕組みになっているというようなことが分かりました。ＰＣＲ検査は各事業者が、高齢者施設、障害者施設はこれまでも東京都の枠組みで、多分１か月に１回とかずつ、ずっとやってきたのかなと。それからあと事務のほうは、各部から４名ずつということなのですけれども、合わせて１日何人ぐらいという体制になっているのか、その点についても伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"保育園、幼稚園あるいは学校などのスタッフへの定期的な検査ですけれども、学校のほうでスタッフ、先生などということではなくて、例えば校外学習へ行くとき等に、生徒も先生もまずは検査をしましょうという無料の検査の枠組みというものは示されたことがありますけれども。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからもう一つは、自宅療養者がかなり増えてきている中で、パルスオキシメーターや食料の配布というものは今までと同じようにされているのか、その点についての確認もさせていただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"現状都のほうですけれども、第６波を想定して、１月の初めにはパルスオキシメーター１０万台、それから１月の末までに１０万８,０００台のパルスオキシメーターをさらに追加して、都内の多くの自宅療養者に対応する予定だというように聞いておりますので、食料はまだしも。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ありがとうございました。ＰＣＲ検査が、誰でもいつでも無料で受けられるという体制が本当にまだまだという、そのような状況なので、それをぜひ東京都にも求めていただきたいと思いますし、できれば私は、東京都がやらないところを区も積極的にやるような方向もご検討いただけたらと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-05","title":"品川区新型コロナウイルスワクチン追加接種","agenda":"品川区新型コロナウイルスワクチン追加接種","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"今ご説明いただいて、予約開始日が書かれているというのは、それはそれでいいのだけれども、例えば高齢者は６か月、その他は７か月ということですよね。そうすると、（２回目接種が完了したのが）７月の人がすぐ申し込んでいいですよとなったときに、７か月というとまだ先ですよと言われる。一番早いのをといったら。そのようなものというのはどうなるのですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その方の２回目の接種日が予約システムのほうに入っておりまして、予約システムのほうで接種間隔を制御することができますので、６か月間隔の予約枠、７か月間隔の予約枠というものが、皆様に分かる状態で画面に出てきます。","id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問","question":"受け入れられないということですね。それから、先ほど１月中は金・土、金・土で１万枠と言ったのだけれども、２月も同じと考えていいのですか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ですので、一応金曜日と土曜日を固定としまして、あまりにも１万枠がすぐ埋まるような、もしくは、ある程度埋まるようであれば、それに追加して、曜日を増やして設定をしていくということで考えたいと思っています。","id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"確認","question":"確認なのですけれども、この４、接種券の発送日・予約開始日の表の4)から下の予約開始日の数字は全て消していいということが１つと、もう一つは、６の予約方法でＷｅｂの新システムに変わるということですので、これは１回目、２回目のときのこのような課題がこのように変えられたというか、そのようなところが分かる範囲でお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１つ目のご質問の予約開始日は、4)以降は、こちらはもうなくなるものというふうにご理解をいただければと思います。","id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"確認","question":"システムのほうですけれども、キャンセルするときに１回取り消してということで、非常に手間というか、消してしまったら次にまた入れなくなってしまったりなどということがあったりしたので、すみません、そこのところを確認したいのです。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その方の予約を保持したまま、キャンセル枠の空き状況を見ることができます。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/831364?Template=document&Id=3618#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":44562,"voices":143}},{"id":"r04-20220117-8","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"建設委員会","time":"午後 １時００分～午後 ４時４６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","topics":[{"id":"topic-01","title":"令和３年陳情第６０号、再開発するなら障害者支援施設の整備を事業者に要請する陳情","agenda":"令和３年陳情第６０号、再開発するなら障害者支援施設の整備を事業者に要請する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回の陳情については、再開発をする際に障害者施設を整備してほしいということですけれども、これまでの再開発の事業の中で、こうした障害者施設などの公共施設の整備を求めたことはあるのかどうか伺いたいと思います。陳情の中に、中央区等の自治体での取組も書かれておりますけれども、そうした他の自治体での取組をご紹介できたらしていただけたらと思います。","respondent":"多並都市開発課長","answer":"品川区においても、より広い形で各部署と連携しながら市街地再開発事業をする場合は行っているということですので、このような形で今後も進めていきたいと考えているところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の中では、ほかの自治体よりもより広い形で要望しているということなのですが、具体的な要望をして、できた事例というのはあるのか、あると思うのですが、どの程度あるのか伺えればと思います。そうすると、この再開発、今回、再開発等促進区と言われておりますけれども、こうしたときは必ず求めるというような形にされているのかどうか。もし条件があるとすれば、どういうときに求めるのか伺います。","respondent":"多並都市開発課長","answer":"もう一度繰り返しになりますけれども、市街地再開発事業を行う際には、連絡調整事務処理要領に従って、この中で関連する各部署に対して連絡調整をして、伝えながら開発事業者に対して要請していくという仕組みで行っているものですので、幅広く、各事業を行う際には。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"それで、この公共施設の整備をすることによって緩和をする仕組みということでやってきているわけですけれども、なかなか陳情者の思いも、障害者施設が足りないというところで、こうした施設は進んでいないというふうに思うのですけれども、そうした下で容積率の緩和ですとかは、９００％を１０００％に緩和しているという状況になっていますが、どうやって９００％。","respondent":"多並都市開発課長","answer":"容積の緩和につきましては、東京都再開発等促進区を定める地区計画の運用基準を先ほどご説明させていただきました原則的な考え方ということで、東京都と促進区に即した開発計画ということで協議していくと。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"子育て施設だと少し優遇されるということでした。やはりこうした公共施設をつくると、緩和のパーセンテージが大きくなるのかというふうに思うのですけれども、そうした下で、結構道路や歩道状空地などだけで、１０００％というところが結構あるので、それで本当にいくのか。区としては、開発をする際に、障害者施設などの公共施設を増やす機会とは捉えていないということなのか伺います。","respondent":"多並都市開発課長","answer":"２つ目は、公共公益施設ということで、アからケまでということで、また別であります。先ほども説明しましたけれども、その中で、例えば、交通補完施設であったり、供給処理施設であったり、様々ないろいろな施設がありますので、これについて１個１個協議していくと。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"ただ、その成り立ちといいますか、誰が中心になって、どういう形で区民に知らせていくかといったときの、そういう仕組みはあるのだろうか、そこがやっぱり大切なのではないかと思うのです。それをやはり知らない方が多いので、こういう陳情が出てくるのかなという思いがあるのですが、その辺はどういう、中心は、どういう形で告知する形になるのですか。","respondent":"多並都市開発課長","answer":"市街地再開事業を検討される準備組合の皆様は、もちろん民間組織で検討していただいています。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"準備組合ができて、その前にいろいろな組織の中で話合いがなされて、どういうまちづくりをしていくのかということで準備組合ができてという形で、どんどん積み上がっていくと思うのです。でも、行政ではないのです。そこの仕組み的なものを、はっきりと伝えるということがやっぱり必要なのかという、これに限らずです、最近すごく私は感じているのですが、その辺は改善できるものなのでしょうか。","respondent":"多並都市開発課長","answer":"地域主体で検討していただいているまちづくりは、各地域で成り立ちも違いますし、進め方は各地域で違うことがありますので、やはりその地域に合った一番最適な方法を、行政としてもいろいろな経験を踏まえて、周知については。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。理由としましては、再開発、様々な規模であったり、地域のそれぞれの事情がある中で、一律で障害者施設の要請をするというのはするべきではないかなと思って、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"塚本委員","kind":"意見","question":"理由は、前回の委員会でしたか、同じような陳情が出て、それと同じなのですけれども、やはり幾つかある公共公益施設の整備の推進というところで出ているアからケまでのものの中で、特に障害者施設に光を当てて、これをつくっていくべきだというようなことは、その願意に沿うことはできないということであります。総合的に判断していただくということがやはり必要だと思いますので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"大沢副委員長","kind":"質問","question":"２番目の、それから始まって、先ほども課長の答弁、地域に合った、地域主体だということで、そこのところはあくまでも地域の皆さんが、実情、あるいは、この陳情には障害者施設ということはありますけれども、ほかとの、近隣とのいろいろな調整、バランス等々を考えながら運んでいくものだと思いますので、取り分けてここで、地域主体の、地域の皆さん。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択です。大規模な再開発は、住民を追い出したり、生活を壊す計画であることがほとんどなので、進めるべきではないと考えますけれども、障害者施設を増やしてほしいという思いは分かりますので、早く増やしていくべきだと考えますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出す、不採択でお願いします。やっぱり全体で考えるべきものなので、今回の陳情のような形で特別にというのは、建設委員会で決めるようなものではないだろうというふうに思います。庁内のバランスも、それから情報提供もしっかりした中での進め方をしているということで、非常に私も安心しましたし、それをこれからもお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]},{"id":"topic-02","title":"会議の運営上、予定表の順番を入替えまして、(5)環境表彰式・環境講演会","agenda":"会議の運営上、予定表の順番を入替えまして、(5)環境表彰式・環境講演会","exchanges":[{"speaker":"西本委員","kind":"質問","question":"この表彰された方なのですけれども、これは何か冊子等で広報というか、報告書みたいなものは作るのですか。この後、表彰された方々をまとめたものとか。","respondent":"河内環境課長","answer":"ホームページなどでも表彰の状況を報告するとともに、副賞、またトロフィーなども併せまして、その顕彰をたたえまして、地域の活動がまた継続的になりますように工夫をしていくというようなところで行うものです。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"その方々に対してのモチベーションアップはいいのですけれども、それはそれとして、要は、例えば、こういう活動をしている団体ですよとか、町会も、みどりのほうとか、いろいろこういう活動をやっていますよとかというのは、何か冊子とかチラシとか、そういうものは、ご紹介の何かしらは何もないのですか。ホームページで紹介だけなのか、もうちょっと広げてもいいのではないかと思うのですが、いかがですか。","respondent":"河内環境課長","answer":"冊子等は特に作っている状況ではございません。今後、検討事項といたしまして、そういったものをまとめまして、もうすぐ２５周年、エコルとごしも進む状況ですので、そういった地域の総括ということも含めて検討してまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"西本委員","kind":"意見","question":"１つだけ。環境館ができますよね。環境館の中にも何かそういう報告するブースが少しあってもいいのかなと、紹介する場所があったりとかというのも、これ、毎年度、毎年毎年やれると思うし、例えば、副賞も含めて、こういうものをやっているなどというのは、環境館の中に何かそういうチャンスがあったらいいのではないかと思うのですけれども。","respondent":"河内環境課長","answer":"施設の展示といたしましては、特にない、ないというのはおかしいですが、イベントごとの発信で常設展示等はまだないというような状況です。今後の臨時展示といいますか、イベントごとの展示の中で、またそちらのほうを対応していきたいというふうに考えているところです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、今回、環境館ができる部分もあるので、そこでも、こういう表彰もしているよという品川区の気持ちというか、目標というか、そういうものもある程度示していくというのも宣伝になるかと思うので、ぜひ指定管理者の方と相談されて、何か工夫をして告知していただければ、もっと広がるかな、そしてせっかく環境館ができるということも考えると、やっぱり品川区の一本の柱として。","respondent":"河内環境課長","answer":"前向きに検討していきたいと考えています。","id":"exchange-015"}]},{"id":"topic-03","title":"コミュニティバスの試行運行開始","agenda":"コミュニティバスの試行運行開始","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それと、やはり大井町駅に行きたいという要望が多く寄せられています。今回、この実施後、利用者連絡会、仮名ですけれども、これを設置していくということで、この中でどういった検討、話合いなどをやっていこうというお考えなのか、こうした場での話合いによって、ルート変更など、より便利なものにしていくという位置づけなのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"バス停については、先ほどもご説明して、あるいはご指摘いただいたとおり、やはりこの箇所に、図書館の辺りに１か所あるというところが、非常に利用的には、区民にとっては利便性が上がるというのは間違いないかなですが、乗り換えで利便性が上がるというところとともに。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"利用者連絡会のところは、今回の大井ルートを実施して、西大井の循環の区間、ここについてもいろいろ住民の意見を聞いてやっていくということですね。ぜひ聞いていただいて、区も強く認識しているということでしたので、ここはやはり坂なども多いので、ぜひ実施していっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"ルートの変更ということで、予測どおりかなというふうに私は思っているのですけれども、非常に大変だと思うのです。南大井方面、桜新道のほうに行く道は、これは当初の地域の方々の要望とのずれはないのかということ。今回、地域の方々のご意見も町会とかで聞いておられると思うのですけれども、そこら辺のご意見はどうだったのかというふうに思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"西大井循環のほうは、まさに地域の声というところで、先ほどご説明したとおりなのですが、今ご指摘いただいた桜新道のほうについても、こちらの地域センター管内の方々とワークショップを重ねていろいろご意見をいただく中で、１つあったのが、この桜新道よりもさらに東側。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"恐らくこちらのほうが地域の方々の要望は強いのだろうと思いますが、その辺はいかがでしょうか。この地域の人たちの意見も踏まえて、本運行になるのかどうかというふうになるかと思うのですけれども、その目途といいますか、もう通知で決められてしまうということもあるかと思いますが、ほかの要因として決める要素がまだあるのかどうかとか、その辺をお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"西大井本通り、この循環ルートの見込みですが、基本的には、やはり狭いというご指摘をいただいておりまして、いろいろソフト的な、一時通行のときに、まず止まって対向車を行かせるとか、そうしたところは協議の中でしっかり説明をしているのですが。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の質疑のところで、ちょっと私も伺いたいのですけれども、西大井循環ルートで西大井本通りと、それから通学路となっているのか、この４ページの。ある程度、こことこことここをそういう待避所としてできればマルですよというようなところまでいっているのかどうか、その辺の詳細なところをお聞かせいただきたいと思います。","respondent":"鈴木都市計画課長","answer":"ソフト的なところですが、どういったところまでをソフト対策とお呼びするかというところはありますが、やはり先ほどご説明した運行に当たっての基本的な考え方といいますか、そこをしっかり明文化して、警視庁のほうにもお示しするというところが大前提なのですが、ただ。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ、ほかの委員からもありましたけれども、この大井の循環ルートが、ある意味、一番の地域の方の望みであるということは、区としても重々承知していただいているというふうに思いますので、様々な関係機関への働きかけ、また、使えるような知恵なり、いろいろな人脈なり、そういったものを駆使しながら、ぜひこのルートの許可を警察から得られるように、できる限りの努力をしていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"芹澤委員","kind":"質問","question":"２点お伺いしたいのですが、先ほどの西大井循環ルートのところで、車の大きさの問題でなかなか入り込めないというところもたくさんあったかと思うのですが、初歩的な話で、ポンチョというのは、ちょっと小さな小型のバスだと思うのですが、これ以上小さくなると、車椅子等の対応が難しいというような検討があったということでいいのかということと、あと、この収支率５０％以上を何とかキープしないと。","respondent":"鈴木都市計画課長","answer":"ただ、今後４年間の中で、状況によってですけれども、まず４年間の中では、この大井ルートの試行、改善ですとか、そうした検証をしっかりしながら、まず見極めたいというところですので、現段階で途中で２つのルートどちらかを加えて、また、全体で見ていくというようなところは。","id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"区のやることだから、どうしてもこの収支というのは着眼されるところなので、その５０％なのですけれども、３年目ということで、３年間を見ると思うのですけれども、それぞれその３年間が５０％を超えるというのが１つの物差しでいいのか、そこのところをもうちょっと教えていただきたいのと、あと、これ、予備車を入れて３台、いずれは４台になるということで、運行時間は、往路１台。","respondent":"鈴木都市計画課長","answer":"来年の８月以降、バスが整いました後、基本的には、４台、３台で回して２０分間隔で運行を進めるという予定です。それから……。","id":"exchange-023"}]},{"id":"topic-04","title":"品川区まちづくりマスタープラン改定に向けた検討状況","agenda":"品川区まちづくりマスタープラン改定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ご説明ありがとうございました。今回、第１回目の改定委員会が行われたということで、質疑応答など、どういった意見が出されていたのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"２時間、委員会が行われましたが、皆様から様々な積極的なご意見をいただいてあります。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろなご意見があったということで、バリアフリーのお話もありましたけれども、資料４のアンケートのところでも、先ほど、若干ご説明もあったかと思いますが、安全な交通・歩行環境というところがバリアフリーフリーにもつながってくるのかなというふうに思うのですけれども、ここの部分は二分されているということで、私も改定委員会を傍聴させていただきましたけれども、この間。","respondent":"鈴木都市計画課長","answer":"これは、まち歩きもしながらバリアフリーの計画などもつくってきておりますが、先ほど、ウォーカブルなまち、今後は、歩いてみたくなるというところもご紹介しましたが、やはりそのベースには、継続して歩きやすい、誰もが支障なく歩きやすい。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと併せて、今、まちづくりでＣＯ２、環境の問題が重要だということが改定委員会でも発言があったのですけれども、やはりそうしたところが、この再開発の問題もそうですけれども、ほかの点でも、環境、ＣＯ２排出をなくしていくというところで重要だと私も思いますけれども、ここのところも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"アンケート結果での日当たりの話と、それから、商店街のお話ですが、先に商店街のほうについては、７ページの拠点市街地の利用状況の右側のところで、利用にあまり満足していないという方の中身について回答いただいているところでございまして、やはり店舗の種類。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"商店街のところでは、多様な機能の集積が求められているというお話でしたので、開発などを行っていくと、大手チェーンのお店ですとかがよく入ってきてしまうというところで、やはりそうした求められる機能の集積というのが、様々な専門店ですとか、こうした個店が並んでくるというのが、商店街の魅力をさらに増していくのではないかなというふうに思いますので。","respondent":"鈴木都市計画課長、竹田住宅課長","answer":"あるいは、本当に潜在的に、まちづくりには参加したいんだけれどもという方々を、どう呼び起こして実際に入っていただくかというところは、この地域の方々とよく話をして、例えば、区としてもアドバイス。公営住宅の質問についてお答えをします。区としましては、現状の区営住宅を維持しながら、既存の民間賃貸住宅や空き家等を有効に活用して住環境を整備していきたいと考えております。区営住宅を増やすことは、現在、考えてございません。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"区営住宅の増設は考えていないということですが、ぜひ考えていただきたい。それが再開発の方向で進んでいったりすると、私はこういうのは嫌だなと思う方は参加しなかったりということもありますので、そうしたところがないように、参加していけるような運営を進めていくように、区としても支援をしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"この調査、いろいろかけられているのですが、これ多分、委託ですか、それとも区の職員がされたのですか。その委託先と、それからコストを聞きたいと思います。","respondent":"鈴木都市計画課長","answer":"今年度から検討を開始しておりますが、委託の受注者はパシフィックコンサルタンツというところで、受注金額は１,３４０万円余という契約金額になります。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"約１,３００万円ですね。分かりました。恐らく第１回目は現状把握という話合いだったのだろうというふうに思います。やはりこれからどうするのかということだと思うのです。現状把握の中で、社会情勢というところが幾つかありましたけれども、それを踏まえて、品川区の特徴とは何でしょうか。なので、そこら辺をどう考えられていますか。","respondent":"鈴木都市計画課長","answer":"ご指摘いただいたように、第１回目は、まず現状というところで、今後、今年度、３月と、あと来年度、数回検討会を開いて進めていくわけですが、改定ですので、大幅な全面策定ということではなくて、先ほどの社会情勢の変化を踏まえた変更ということになるのですが、次回以降。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"でも、これだけでは不十分ではないのですか。なので、今までと同じような委員たち、いろいろご足労をおかけして関わっていただいているのはありがたいことなのですが、これからのまちづくりをする上では、もうちょっと地域の方々が見えるような、そして地域の特性が見えるようなまちづくりという位置づけでやっていっていただきたいと思いますが、いかがですか。","respondent":"鈴木都市計画課長","answer":"今、ご提案として、さらにそれぞれの地域で個別にお集まりいただいてご意見をいただくというご提案をいただきましたが、２年間という短期間での計画改定ということもあって、実際にお示ししたアンケート、それを地区別に分析したものもありますので。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、このまちづくりマスタープランの改定というのは本当にいいチャンスだと私は思っているので、ぜひいろいろな手法は難しい部分があるかと思いますけれども、やっぱり地域ごとの今の現状を把握をした上で、これからどういうまちにしていったらいいでしょうかみたいなのは、やっぱりアンケートだけではなくて、地域に足を向けて一緒につくっていくという雰囲気でしていくと、非常にいろいろな意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"社会情勢の変化についてという資料の１ページ目で、５つの次世代に求められる社会というものが挙げられておりまして、どれも大事な視点というふうに思いますけれども、特にこの2)スマートシティとデジタルトランスフォーメーション、3)新型コロナ危機を契機に変革する「人間中心」の社会、4)脱炭素社会とカーボンニュートラル、これは、いわゆる住んでいる我々の。","respondent":"鈴木都市計画課長","answer":"ご紹介いただいた次世代に求められる社会というところで、コロナなどは、予見をして起こって示した形で区民の方の生活様式が変わってきたというよりも、必然的に変わってきたというところで、今後こうしたところを受けて。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問・要望","question":"5)の多様化を支えるダイバーシティ社会、大事な考え方、価値観なのですけれども、これは裏を返すと、もう１つ、影の部分というか、孤立化ということを一方ではこれからの社会で見過ごせない１つのことだと思います。そういうことに対する視点も含めた多様化ということをぜひ考えていってもらいたいというふうにも思うのですけれども、この辺の観点については、どのようにお考えでしょうか。","respondent":"鈴木都市計画課長","answer":"なかなか難しい考え方というか課題だと思うのですが、１つは、この資料の中でも、様々な多様性を活かすという考え方とともに、イノベーション等を創発する空間というところを１つのセットで書かせていただきましたが、やはりアンケートのほうでも、本当に地域で仕事。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"質疑を聞いていてちょっと思ったのですけれども、先ほどありましたワークショップを地域でやるというのは、地域の声を吸い上げていくということで、私もすごく重要だというふうに思いますけれども、改定委員会で、分科会で分けて話合いを審議していくということも、さらに深めていくことになるのではないかなというふうに思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"前回の策定時、平成２３年のときは、この検討会に分科会という形で、都市構造の分科会と、それから防災、やはり防災の話が非常に大きかったものですから、防災的なところで分科会を立ち上げて議論してきたところですが、来年度、分科会を立ち上げてということは。","id":"exchange-035"}]},{"id":"topic-05","title":"西五反田七丁目地区に関する都市計画案","agenda":"西五反田七丁目地区に関する都市計画案","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それと、今度行われる２月２５日の説明会、これはぜひ広く周知をしていただきたいというふうに思うのですけれども、事業者説明会のほうでは１５５名参加したということですので、ぜひそういった方々に参加をしていただきたいというふうに思いますので、この事業者のときと同様な形で、計画建物の高さの２倍の範囲のところにチラシをポスティングする、そういった形で。","respondent":"多並都市開発課長","answer":"１２月２０日に行いました都市計画原案の説明会ですが、質疑は当日ありませんでした。次に、２月２５日の説明会の周知ですが、まず、区報に掲載するとともに、ホームページでお知らせします。広く区民の方にお知らせするということで、こうします。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"２月２５日の説明会は、広くということで、区報とホームページなどでやっていくということなのですけれども、そういった従来のお知らせで、大概この都市計画案の説明のときには、参加する方が少なくなるという傾向がありますので、事業者説明会のときには１５５名参加されているわけですから、ぜひそういった方々に参加をしていただけるようにお知らせをしていただきたいというふうに思います。","respondent":"多並都市開発課長","answer":"建蔽率につきましては、まず、１０分の５ということですけれども、右側の備考欄にあります建築基準法の第５３条第６項ということで、いろいろなものがあるのですけれども、このようなものが該当した場合には加えるということになっていまして。","id":"exchange-037"},{"speaker":"芹澤委員","kind":"質問","question":"すみません、説明を聞き逃していたら恐縮なのですが、Ａ３資料の裏面のＡ－１地区等、道路に網かけがかかっている部分が、オレンジのところとピンクがあると思うのですけれども、まず、これのご説明をいただいてもいいでしょうか。","respondent":"多並都市開発課長","answer":"右側の国道１号線側のほうについても同じような考え方でしているということで、道路についても地区に含んで、この地区としての対象範囲としていく、そういう考えであります。","id":"exchange-038"},{"speaker":"芹澤委員","kind":"質問","question":"そうすると、Ａ－１地区の今「２.０ｍ」と書いてあるところは、ここに建物が今あるのかと思っていたのですが、ここも含めて道路ということなのですか。紫色のところが道路の中心線になっているということなのでしょうか。","respondent":"多並都市開発課長","answer":"今回のこの高度利用地区の中で、プラス３００％という緩和を図る、先ほどの基準を満たしているので、してくるということで、基の容積率が違うので、そういう分け方をさせていただいているという考え方であります。","id":"exchange-039"},{"speaker":"芹澤委員","kind":"質問","question":"何となく分かりました。両サイドの横断歩道まで少し遠いものですから、あそこを使っていくのですが、今後の将来性として、この計画に入るか入らないかはあれですけれども、歩道橋と一体として何か開発をするという可能性はないのですか。例えば２階からつながるであったりとか、もしくは建て替えてエレベーターをつけるなりという可能性はあるのでしょうか。","respondent":"多並都市開発課長","answer":"ただ、今後、また国道事務所ともよく連携を図りながら、もしそういうのが出てくるのであれば、この中でいろいろ連携できないかというのは、今後またそれは状況を見ながらお話合いをしていくことになるのではないかということで、今のところはそういう考えであります。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"ちょっと関係しなかったらごめんなさい。ＴＯＣの建て替えが遅れているのは、この都市計画の申請を待っていたということなのでしょうか。それによっては、大分条件が緩和されてくるので、有利と言えば有利ですよね。そういう関係で遅れたのでしょうか。別にそれに対してどうのこうの言うつもりはないのですけれども、その経緯をちょっと知りたいのですが。","respondent":"多並都市開発課長","answer":"あくまでも民間計画が主体となりますので、民間計画、なんと言いますか……に至って、現在に至っているという認識です。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"こういった形で建て替えを考えているビルとかが今後もあると思うのです。そうした場合に、この地区計画との関係はどうなるのですか。ＴＯＣの建て替えは相当時間がかかっています。なので、その辺はどういう絡みがあって、今回この場所が都市計画の中に入ってくるのだろうというふうな、そこの時間的な経過も含めて教えていただきたいのですが。","respondent":"多並都市開発課長","answer":"あくまでも民間の計画の中でのご相談です。地区計画につきましても、今回は、再開発等促進区を定める地区計画ではありませんので、一般的な地区計画です。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"分かりました、少し分かってきました。そうすると、今回のような都市計画とかで地区計画をするときに、これぐらいの大きさとかと決まっているのですか。こういう形になると、建蔽率にしても何にしても優遇策がとれるわけではないですか。そうなってくると、ある一定の条件がないと、こういう手法は使えませんよということなのか、どこまでの範囲で使えるのでしょうか。","respondent":"多並都市開発課長","answer":"今のは高度利用地区の適用要件の話かと思いますけれども、この制度自体は、地区内の土地利用の状況と、将来の動向と、周辺の市街地の土地の動向、全体的な特性に合わせて土地の合理的かつ健全な高度利用を図るために行うものですので、今回のこの地区の特徴といたしましては。","id":"exchange-043"},{"speaker":"西本委員","kind":"確認","question":"ちょっと分かりません、民間なので、どういう状況になっているか分からないのですが、あそこは今、非常に荒廃してしまって、ああいう荒廃した状況をあまり置きたくないなという思いがあって、落書きがあったりとか、そういうものがあって、あまり風紀的にもよくないので、あそこも丸ごと入れてしまえばよかったのではないかと思ったりしていたのですけれども、そういう話はないのですねという確認だけです。","respondent":"多並都市開発課長","answer":"これ以外につきましても、このビジョンの中で、これからのまちづくりの方向性なりが示されていますので、この中で、また、地域の方と一緒に、より具体的な計画については検討していきたいと思うところです。","id":"exchange-044"}]},{"id":"topic-06","title":"の３、所管事務調査","agenda":"の３、所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"公営住宅の現状というところでご説明いただきましたけれども、先ほどの質疑の中でも言わせていただきましたが、やはり公営住宅の増設が必要だと私は思っています。足立区などは１０％を超えているという状況ですけれども、そうした下で、やはり品川区内でも、区営住宅を増設をしていくべきだというふうに思いますが、増設をしないというふうに考えているその理由を伺います。","respondent":"竹田住宅課長","answer":"区は、従来より一貫して、現状の区営住宅を維持し、既存の民間賃貸住宅や空き家等の有効活用を通じて住環境を整備していくというお答えをしています。その考えに変更はございません。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、様々な公営住宅の改善点などを求めていきたいと思うのですけれども、この間も指摘していますけれども、浴室の浴槽や給湯器の交換、それが住人の負担になっているというところを、ぜひ区としても、都営住宅、公社住宅などで、住民に負担させないで交換をしているということが進んでおりますので、区営住宅においても、区の負担で設置を進めていくというふうにしていただきたいと思いますけれども。","respondent":"竹田住宅課長","answer":"ただ、東京都で「東京都性自認及び性的指向に関する基本計画」が出されておりまして、その取扱いについては検討していくという文言もありますので、今後、他区の状況、東京都の状況等を注視してまいりたいと考えております。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"浴槽などのところは、退去の際にはやっているということですけれども、今の入居している方も、希望に沿って、ぜひ区の負担で設置をしていっていただきたいというふうに思いますが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"風呂釜につきましては、先ほど申し上げたとおり、原状回復等の際に区の負担で実施してまいりますので、現在、自費で設置して継続している入居者の方の故障時の修繕、取替え等は、区の負担では行っておりません。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりそうしたところへの、もともと品川区民だった人たちも出ていかざるを得ないということにもなりますので、そういった住み続けられるまちというのを進めていくという上でも、若者や子育て世帯への家賃助成、住宅困窮されている方への家賃助成を実施していくべきだというふうに思うのですけれども、いかがでしょうか。","respondent":"竹田住宅課長","answer":"むしろ品川区の魅力をアップして、住み続けたいというお気持ち、あるいは、他区からも品川区に住んでみたい、そういうふうに思っていただけるようなまちづくりを住宅を通じてしていきたいというふうに考えております。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"１回利用すると、もう使えないという状況だと思うのですけれども、それを一定年数が経過した際には、ほかの場所とか、そうしたところでは、再度利用できるようにしていただきたいというふうに思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"ただ、性格の違うもの、環境と、例えば、高齢化による手すりの設置とか、目的の違うものにご利用いただくというのも、それも１つの利用の仕方だと思いますので、１世帯の方が複数回申し込んでいただくということについては。失礼しました。補助率は、今現在、申込み件数が増加傾向ですので、現状の制度を維持していくというふうに考えてあります。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"教えてほしいのですが、まず、３番の居住支援協議会ということなのですが、この協議会でいろいろ議論して、そして、この居住支援という具体的な策が出てきたという認識でよろしいのでしょうか。そこをお聞きしたいのですが、関係性が知りたい。","respondent":"竹田住宅課長","answer":"委員おっしゃるとおりでございまして、協議会の中から出たご意見を事業化したものがこちらです。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"それで、区営住宅の建設は今は考えていないということなのですが、空き家の状況を考えると、いろいろあっ旋をするということをやっているのですけれども、そこで家賃を下げるとかという交渉もしておられるのでしょうか。なので、オーナーとかも含めて、家賃、例えば、従来よりも少し低くしてくださいとかという交渉はされないのでしょうか。","respondent":"竹田住宅課長","answer":"ただ、今回、協力店５１店舗、今現在、ご登録いただいているのですが、そちらの方々は、住宅確保要配慮者に対する支援をしていきたいというふうなお考えをお持ちの方々ですので、そういった不動産店は、オーナーとも非常に強固な関係にあるというふうにお聞きしていますので。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"あっ旋だけでは入り切れないと思うのです。そういった場合に、空き家がいっぱいあるのだから、空き家対策の１つとして、１軒でも貸したほうが、オーナーにしてみればいいわけではないですか。ただ単に泳がしておくよりは。","respondent":"竹田住宅課長","answer":"ただ、委員おっしゃるとおり、これで全てが解決するというふうには考えてございませんので、居住支援協議会のご意見をお聞きしながら、次は区として何ができるのかということを検討していきたいと考えています。家賃の問題も含めて検討していきたいと考えております。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"その辺のお考えと、それからあと２つお聞きします。多分そこまで条例の中に入っていなかったような気がするのですけれども、ごみ屋敷とかという場合には、条例で片づけるとかというのは、撤去するとかというのはできていると思うのですけど、でも、持ち主が分からない、どうしてもずっとそのままの状況になってしまった場合に、品川区として何か対策をとれる、法的な何か保障されたものはあるのでしょうか。","respondent":"竹田住宅課長","answer":"この制度を機に、オーナーにも、そういう方々にも貸していこう、あるいは不動産店については、そういう方々にも積極的にご紹介していこうというような意識づけを目的としたものですので、そうなるように私どももご説明していきたいと考えております。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"避難の状況、それから備蓄なども、ほとんどやっているのだろうと思いますが、それはかなりきつく言っていかなければいけないのではないかと思うのですが、それの対応策、ちょっと所管が違うと思うのですけれども、そういう形でメッセージとして出しているのかどうかというのが１点と、それから、相続人が分からなかったら裁判所にかけてということなのですが、それは何年ぐらいなのですか。","respondent":"竹田住宅課長","answer":"法的手段を行う場合に、どれぐらいの年月かということなのですが、私どもが裁判所に申立てて、それをすべきかどうかというのは裁判所のご判断ですので、ここで何年ということは申し上げられないのですが、区の考え方としましては、周りに非常に悪影響をもたらす。","id":"exchange-054"},{"speaker":"塚本委員","kind":"質問・要望","question":"どちらのお財布でやるか、住宅改修でやるのか、介護でやるのかという話で、介護で使える人は介護にという流れなのだと思うのですけれども、住宅改修のほうは予算も限られているというか、人気があるので、住宅改修でしかできないような改修をできるようにという方向性でやられているのであろうと思いますけれども。","respondent":"竹田住宅課長","answer":"土地建物所有者の長きにわたるご理解、例えば、所有者の方が途中でご逝去ということになれば協議が終了してしまいますので、そういった条件がクリアできれば利活用が進んでいくと考えておりますので、そういったハードルを１つずつクリアしていきたいと考えております。","id":"exchange-055"},{"speaker":"塚本委員","kind":"確認","question":"分かりました。不動産の登録の条件に関してですけれども、今、２団体のほうが周知がしっかりいく、それはそうだと思うのですけれども、それ以外の、例えば区外の人でも品川区に物件を持っているという事業者はいるかと思うのですけれども、こういうものの申し出みたいなものというのは、制度としては、スキームとしてそれは可なのですか。それを確認させてください。","respondent":"竹田住宅課長","answer":"残念ながら、区民の方々等からご連絡いただく物件については、非常に老朽化しているもので、なかなか利活用するのが難しいという案件が数多くありますけれども、今後も粘り強く取り組んでいきたいと考えています。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/979224?Template=document&Id=4340#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":66019,"voices":159}},{"id":"r04-20220117-9","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"文教委員会","time":"午後 １時００分～午後 ４時３１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","topics":[{"id":"topic-01","title":"令和４年度新入学学校選択の希望申請理由に関する調査結果","agenda":"令和４年度新入学学校選択の希望申請理由に関する調査結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、続いて、選択制であっても、学区内の希望者は全て受け入れる仕組みになっているわけですけれども、今年は４月からは３年生までが３５人学級になるということで、伺いたいのですが、結構例年、御殿山小学校や第二延山小学校もそうですが、教室が足りなくなることを想定して、今年度中に既に準備として、幾つか普通教室を増やしていると思うのです。","respondent":"勝亦学務課長、有馬庶務課長","answer":"私からは、表の表記と指定校変更についてお答えします。備考欄の「兄弟」につきまして、おっしゃるとおり、「兄」「弟」と書きますと、性別的には男性だろうという部分があります。来年の４月以降の教室、各校の対応策ですけれども、大きく工事をしなければいけないもの、それから、備品である程度多目的室を教室に、簡易でやるもの、そういうものを含めまして、来年度に向けては１５校１７教室を整備しています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはどうかと思うのですけれども、３５人学級に現時点でできないと。そうすると、教室が足りなくなってしまうのでということで、例外規定を使って、もう４０人学級で対応するしかないと考えていらっしゃる学校、今の時点でどこか予測しているのか伺いたいと思います。","respondent":"勝亦学務課長","answer":"指定校変更ですけれども、制度としてはそれを妨げるものではないということでございまして、ご希望いただく際には、そういった形での、学校選択で入れなかった方のご希望はできませんということでご説明申し上げて、希望をしていただかないような形で対応しています。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"制度を国が変えたということなので、今年度からある程度４月のことを予測して準備をされているということだと思います。ですから、私は、選択制でそういう状況に学校を追い込んで教育の質を上げるというやり方自体は間違いだと考えています。だから、私は、こういった状況を見ても、形だけの選択制というのはもうやめるべきなのではないかと思いますけれども、区教委のお考えをお伺いしたいと思います。","respondent":"勝亦学務課長","answer":"そういった中で、昨今、諸環境が変わった中で、地域とともにある学校という形で、コミュニティ・スクールなどを進める中で、地域と学校の結びつきがより強まってきた部分の中で。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"そもそも義務教育といいますか、公教育というのを、そういういわゆる市場原理のように、選ばれるような努力をするというか、そういう競争をさせて育てるという方法は、なじまないと思いますし、今実際に、学校が近く通学しやすいという、地域と学校の絆も強まっていると言いますけれども、そう言うのだったら、やはりそれこそ本当に選択させて違うところに行かせるというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"私もこの調査結果について伺いたいと思います。ただ、このアンケートについては、理由が、今後の学校運営に生かしていきたいと存じますのでと書かれていますが、具体的に、例えば、このアンケート結果を受けて、それぞれの学校で何か努力をしたというのでしょうか、このようにこのアンケート結果を活かしたというような実績というか、そういうものがあったら教えていただきたいと思います。","respondent":"勝亦学務課長","answer":"そういった部分、お褒めの言葉と捉えて、学校の教育活動の独自性を出す中でも励みになっているものと考えております。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"例えば、こういうアンケート結果を受けてこのような改善をしたとか、このような工夫をしたということは、校長先生同士の情報交換の中で何か活かされているのでしょうか。やはり何かそういうアンケートというものをやる以上は、アンケートをどのように活かしたかということがないと、どうなのかと。でも、その方たちにはアンケートを取らないわけではないですか。","respondent":"勝亦学務課長、矢部教育総合支援センター長、工藤指導課長","answer":"具体的に、このアンケートの活用について、例えば会議を持って取りまとめを行うですとか、そういった部分はしてございませんけれども。例えば、学校の教育活動に魅力があるということであれば、本校の例えば英語だとか体験だとか交流だとか。おおむね１番から３番まで上位３つを捉えますと、今年度報告している内容と同じですけれども、希望申請するしないのところでも。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"校則に関しても、これはそれこそ切磋琢磨ということであれば、１校が情報公開をすれば、それが切磋琢磨の結果、ほかの学校にも広がっていくという考え方もできるので、頭ごなしに選択制を否定するというのは私は違うと思っているということを言いつつ、より積極的な情報公開をしていただきたいと思っているのですけれども。","respondent":"矢部教育総合支援センター長","answer":"学校によっては、ホームページに出しているところもありますし、今、実際に校則の見直しについての取組を学校だよりで毎月のように出している学校もありますので、好事例は紹介していきたいと考えております。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問・要望","question":"好事例がこういった形で切磋琢磨につながると私も考えておりますので、引き続き各校といろいろ協議していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"学校としては一生懸命頑張っている。でも、何で子どもたちは入ってきてくれないのか。そこが分からない。だから、これはすごく難しい話で、結果、こういう抽選校がある、抽選校がない時点でも、学校の差というのが明確に見えてしまう中で、選択制というものというのはどういう立ち位置でやっていけばいいのかというのを聞かせてください。","respondent":"勝亦学務課長","answer":"そういった意味で、今、学校選択制については、そういった保護者の方のある程度選択の幅を持ちたいという２０％程度のニーズもあるということで、そういった中でご希望を受け入れていく中で。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"そうですね。確かに分かりました。地域の課題で少しありまして、私、豊町１丁目に住んでいまして、すぐ目の前の子が、戸越小学校管轄ですが、違う学校に行っているわけです。何でですかと話を聞くと、やはり学校が違うと友達がいないと。では、芳水のところの居木神社に行くのですかと言うと、行かないのです。何でですかと言うと、こちらはお祭りでにぎわっていないから、向こうには行きづらいと。","respondent":"勝亦学務課長","answer":"ただ、そういった中でも、今説明ありました神社ですとか、そういった地域の伝統的なお祭りですとか行事、または町会・自治会が行っていただいているお祭りですとか行事、また、青少年地区委員会とか、様々なイベント事業等々に参加する中で、一つの学校の人間関係の中で。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"私も学校選択制というものを全く否定しているわけではなくて、選べるということは大切だと思った中で発言させていただいているのですけれども、兄弟枠、こうやってざっくり見ると、結構兄弟、今、待機されている方が多いです。ごめんなさい。議事録を見直しするのを忘れてしまったのですけれども、兄弟枠の方というのは、全然入れないのですか。例年、何人ぐらい大体残ってしまうのかというのが分かれば。","respondent":"勝亦学務課長","answer":"兄弟枠の実績です。今現在、兄弟枠でお待ちいただいている方につきましては、小学校で８７名お待ちいただいております。昨年度の実績ですけれども、今手元に数字はないのですけれども、半分程度の実現率かと記憶しています。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"やはり現状、地域の子どもが住民基本台帳の中で、入りたいけれども、いろいろなところでクラスで人数で入れないみたいなことが起こっていますので、そういった中で、こんなことを言っていいのかよく分からないのですけれども、受入人数に対して無抽選で入ることは、いろいろ課題があるので、新たにそういうところに学校を造るとか、もっともっと厳しい、大変なところの学校改修をより早くするみたいな。","respondent":"有馬庶務課長","answer":"今の段階で、就学人口が伸びてきて、３５人学級になってきているというところで、教室を確保するというところは、ある程度、もちろん状況を見ながら対応しているところですけれども、この地域に１つ学校を造れば、それが解決かという話でもないですし。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"毎年この時期になると、こういう同じような議論や質問が、この文教委員会では展開されているなと思うのですが、その上で私も同じような問いをするかもしれないのですが、各委員の質疑を伺っていて分かったところもあり、今の松澤委員から確認のあった兄弟枠のところ、大体例年、抽選の兄弟枠の方の入れる入れないが半分ぐらいだと。","respondent":"勝亦学務課長","answer":"兄弟枠の取扱いです。学校のほうにお送りしております、先ほどご説明いたしました学校案内で、学校選択をお選びいただく際に、兄弟枠についても触れてあります。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"あえてここではご答弁は求めませんが、そういう兄弟枠の考え方というのを、またいま一重、いろいろ考えていただいて、最適解というのでしょうか、それが今のこの形なのか、前も議論させていただいたかもしれないですけれども、兄弟枠については全入ではないけれども、いろいろなほかの条件も照らし合わせて、優先順位は１位なのだというのが、それは既に見ているのだというのはあるかもしれないですけれども。","respondent":"工藤指導課長","answer":"いわゆる持続する学校づくりというところも、品川コミュニティ・スクールの大事な根幹ですので、いただいた意見を頂戴いたしながら、またそういったことが実現、現状今、取り組んでおりますけれども、さらに実現していくよう進めてまいりたいと考えているところです。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"そうすると、なかなか今、学校公開はやっていただいているのですけれども、保護者も学校をまじまじと見るチャンスというのはない中で、ワンチャンスの中で、そういうモチベーションなのだというお話の仕方と、そうではない、物すごくアグレッシブにやる学校の差というのは、端末の取扱い一つとっても、なかなかうまいこといかなくてやっているという学校と、さくさくいける学校と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"子どもの感染ですけれども、累計でということなのですが、１月からですかね。第６波ということでは何人出ているのか、小学校、中学校、できれば内訳もあれば、お伺いしたいと思います。３つ目としては、学校の第６波への対応方針について確認したいのですが、特にマニュアル自体は１１月のままで更新がされていないようですが、これまでの対応と何か変えたようなところはあるのでしょうか。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"感染の直近の状況です。すみません、正確な数字はないのですけれども、１月で約４０名出てあります。昨年の１１月１２月と感染者がゼロの状況から、半月でこれぐらいの数字が出ているという状況です。コロナ不安でお休みしているお子さんです。１月１１日現在、１１２人です。小学校が１０１、中学校が１１ですが、６年生が大半を占めております。それが現状です。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"学校内で出るというよりは、お父さんお母さんが職場や会食などで感染して、それが家庭内に持ち込まれて、子どもがうつってしまって、子どもは無症状のまま学校や幼稚園などに来て広がってしまうというようなところで、１２日には１０７人の感染、それまでは１２月にはゼロのときもあったのが、１日で１０７人の１０歳未満の新規感染者が出るというようなこともあるそうなのですけれども。","respondent":"勝亦学務課長","answer":"そういった中で、校内での感染の拡大につきましては、現状の対応の中で一定程度抑え込めていると考えていますので、感染していると疑わしいような場合には、当然、保健所にご相談しまして、保健所の判断の中で検査等は行ってまいりますけれども。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺は住民の意見などもしっかり伺いながら、強化していただきたいと重ねてお願い申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。そのときの寒さ対策、先生によって、随分柔軟に対応してくださる先生と、割と厳しく教室内で手袋とかマフラーはしてはいけないとおっしゃる先生が現にいらっしゃるようなので、その辺、教育委員会として、あまり学校の現場に口出しもしにくいかもしれないですけれども、どのように情報共有をされているのか、改めて伺いたいのですけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"換気をはじめ、感染防止対策は、校長会でも生活指導主任会でも毎回お伝えしています。やはりお子さんによっても寒いとか暑いとか、差があると思いますので、お子さんに寄り添って健康第一で進めるように、これからも周知してまいりたいと思います。","id":"exchange-019"},{"speaker":"吉田委員","kind":"意見","question":"ぜひお願いします。同じ教室の中でも、場所によって寒かったり、別にそれほどマフラーもしなくても大丈夫という、席によって、それは私たち子どものときから経験しているのですけれども、そういうこともありますので、ぜひこの辺はやはり今は換気がすごく大事という中で、防寒対策、一方で防寒という視点で、今までだったら許されないようなことも柔軟に対応していただけるよう、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"１つだけ。２つ学級閉鎖というお話がありましたけれども、学級閉鎖内の勉強の仕方というのは、やはり今はタブレットを使ってやるものなのか、そこだけ教えてください。","respondent":"矢部教育総合支援センター長","answer":"ただ、要望は、保護者や本人にとって大分違って、プリントがいい場合もあれば、「結構です」というおうちもあるということは踏まえて、全体的にはタブレット活用を進めております。","id":"exchange-021"},{"speaker":"松本委員","kind":"質問・要望","question":"今の吉田委員からの質問に関連しますが、マフラーとかなのですけれども、文部科学省から、学校教育活動を継続するためのチェックリストが１４日に出ているかと思います。この周知の状況がどうなっているのかというところと、要望としては、これをまさに出していくことで、各教師の皆さんも気づいていただけるのではないかと思いますので、そこのところの対応状況をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"通知文につきまして、先週末ということですので、こちらで確認しまして、必要な周知をしていきたいと思っています。","id":"exchange-022"}]},{"id":"topic-03","title":"を改めて聴取いたします。 (3)西大井広場公園内における認可保育園の運営期間延長","agenda":"を改めて聴取いたします。 (3)西大井広場公園内における認可保育園の運営期間延長","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"質問なのですが、保育需要について書かれていますけれども、区としては大井とか大崎とか、地域ごとに区域を分けて様々報告されていますけれども、この西大井周辺の保育需要について、具体的にどのように算出していらっしゃるのか、少し伺いたいと思っていまして、今回、５年ということなのですけれども、１０年ではない理由なども含めて、どのような作業、どのような要素で算出しているのか。","respondent":"若生保育支援課長","answer":"これについては、また今後、子ども・子育て支援事業計画の中間見直し等もありますので、その見直しの状況を見まして、今後、この１５年という期間をどうしていくのかというところは改めて考えていく必要があると認識しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"見込みに応じて取りあえず５年ということなのですが、環境改善されるまで継続していただきたいと思いますし、その見込みというか、需要を算出するに当たっても、事実上待機なのだけれども待機児から外されてしまっている方々などもしっかり視野に入れて考えていただきたいと。毎回言っているのですけれども、改めてここでも要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"先ほど説明会の話があったのですけれども、これ、国家戦略特区制度を利用して公園内にということで、これを建てた当初は公園の利用者の方たちへの説明もされたように認識しております。だから、そのときは限られた年限でという説明をされたと思うのです。今の説明会には、やはり公園利用者というか、そういう近隣の方たちも説明会の対象として含まれているのか、その辺について伺いたいと思います。","respondent":"若生保育支援課長","answer":"今回、延長に当たりましては、当時の説明では上限が１０年だったということで、その段階では１０年間ということで期限を切っていたところなので、当然、延長する場合は、同様に説明が必要になりますので、同じ範囲の住民の皆様にご案内させていただいて。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"せっかくの保育園ですので、ぜひ近隣の方たちに温かく受け入れてもらえるような保育園運営をしていただきたいと思います。それで、事業者の合意というか、それは既にこれ、経営的には結構厳しいかと思って、だんだん子どもたちが減って、基本的にかかるお金というのは、どうしても人数が多かろうが少なかろうがありますので、その辺の合意というか、その状況について教えていただきたいと思います。","respondent":"若生保育支援課長","answer":"当然、民設民営園ですので、事業者の意向というのは無視できないものです。事業者に対しましては、こちらの公園内の保育所を１０年より先どうするかというところでは協議を進めてきたところでございまして、事業者の意向を聞き取ってあります。","id":"exchange-026"},{"speaker":"吉田委員","kind":"提案","question":"具体的にどうすべきという提案が今思いつくわけではないのですけども、やはりただ数があればいいというものではないということで、保育の質を確保できるような運営が可能なようなやり方を、ぜひ工夫していっていただきたいと思います。今はそれぐらいしか言えるところがないので、ぜひその辺、しっかりやっていただきたいと思います。これは要望です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"保育の今後の需給状況を鑑みてというところで、ぜひ待機児童が出ないように、こうやって延長していくという試みは本当にすばらしいと思って、やっていただきたいと思うのですけれども、その上で、占用期限が１０年ということなのですが、これは都市公園法とか何か、そちらのほうのでということなのかというのが１点と、それからあと、今回、１５年に延長ということなのですけれども。","respondent":"若生保育支援課長","answer":"期限が１０年ですが、こちらについては、当初は国家戦略特区の特区法で、１０年間が上限として決まっていたと。現在は都市公園法が改正されて、そちらのほうの適用になっておりまして、一般法である都市公園法の中でも、占用期間は保育園の場合、１０年と決められております。","id":"exchange-028"},{"speaker":"湯澤副委員長","kind":"意見","question":"その状況状況に合わせて継続もできるしというところで、ぜひそうなったときにはお願いしたいと思いますし、また、逆に人数が減ってきたときも、質というのも先ほどありましたけれども、お部屋の有効利用というか、そういったところも課題になってくると思いますので、そちらのほうもぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"つる委員","kind":"確認","question":"今、保育園事業者の採算の部分ですよね。借りているテナントの様態にもよると思うのですけれども、大体５年とか１０年たつと採算が取れる。当然、保育需要がすぱんとなくなってしまったら、それもまた違うのでしょうけれども、まずそこのところについては、事業者としての運営状況というのは、これは今後の見立ても含めて問題なくやっていけるというところでいいかどうかの確認をお願いします。","respondent":"若生保育支援課長","answer":"少なくても５年を延ばすということについて、事業者と今後のお話をすることにはなるのですけれども、民間事業者としては、やはりどうしても採算というところを当然考えないといけないので、区としては、どこまで引き延ばせるのかということと、あとは。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問・要望","question":"２０１７年当時、２人の課長が、２５年と５年１０年という、これはあくまでの民間のどういう人件費だとか、土地や建物をどう持っているかとかによって、当然そんなのは変わるわけです。そこの活用とかというのは何か事業者のほうでは考えていらっしゃるのか。そのような活用とかをしていいのかどうか、もしくは、既にそういうお考えがあっての前提かというのが、その辺が分かれば教えてください。","respondent":"若生保育支援課長","answer":"今後、事業者に、この事項を示させていただいて、事業者としてどのような活用をしていきたいか、区としても、空き室を活用した児童の受入れという意味では、一つは定期利用のような形も考えられると思うのですけれども、そういったことは可能かどうかは。","id":"exchange-031"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"具体的にそれぞれの項目で検討されていることとか、試行錯誤されたこととか何かあれば、先ほど離乳食講座については、具体的にこういうことを試してみましたというものがありましたけれども、ほかにも何かあったら教えていただきたいのと、全体的な中で、今は取りあえず現状を聞き取ったというような感じで、今後についてはまだこれからだと思うのですけれども、やはり既に何か。","respondent":"廣田子ども育成課長","answer":"地域との連携事業はなかなか今できない状況ではあるのですけれども、状況がよくなってからは、広いところではやっているところです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。なるほどと思ったのですけれども、そのようなことが全体的に行われたのか、それとも、どこかの児童センターの職員の方が、あそこにいつも子どもたちがいるよねということで、個別の工夫として実行されたことなのか、何か一つのよい事例として今後広めていくようなお考えがあるのか伺いたいのですが、いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"保護者の方には、授乳とかしか来ては駄目だと言っているのですけれども、そこで気になる人がいたら奥に連れていくという趣旨で、広くは広報していないけれども、そのような趣旨もありまして、環境的に近くにそういうスペースがある児童センターで行いました。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"それぞれ条件が違うので、一律でこのような制度にしてくださいというのは難しいかと思うのですが、同じようにやはり児童センターの工夫で、密にならないような形で、でも、子どもたちがそういう、今までの児童センターでの関係性を保てるような工夫をそれぞれ今後もやっていっていただきたいと思います。これは最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこを確認させていただきたいのと、あと、直営館が１３館でしたか。全館は２５館あると思うのですけれども、このアンケートに答えたのは区の職員の方だと思うのですが、直営館以外のところというのは、ある程度同じような状況だったのか。そこら辺、どういう感じで把握されているのかというのも伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"１３館直営館があるのですけれども、１３館で、それぞれ直営ではない委託館を各館長が分担で持っておりまして、そこの意見もまとめて提出してもらったというところがあります。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"大変努力していただいてありがたいと思います。これは要望です。コロナ禍で、やはりますます孤立を深めているのが子どもと若者だと思うのです。実際に利用者や相談件数も増えているということで、これは要望と質問なのですけれども、子ども若者応援フリースペースも含めて、やはり人的配置も含め、予算もさらに増やしていくべきなのではないかと思いますけれども、それはいかがでしょうか。","respondent":"廣田子ども育成課長、山下子ども家庭支援センター長","answer":"子ども・若者の支援に関しましては、あり方の見直しのためのアンケートの予算を、令和３年度の予算で持っておりまして、今、乳幼児親子であるとか、小学生、中学生、高校生に、児童センターを利用している方。１２月末時点での令和２年の受理の状況が４７８件、被虐待相談の欄に記載の数字です。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。これは本当に子どもにとって大変つらいと思います。ともすれば、自分の所有物だみたいに思ってしまうようなゆがみもあるのではないかと私は懸念しているのです。今の所管の子どもの権利条約についての認識というのを改めて伺いたいというのが１つ。それと、これ、こういった点からも広げる必要があるのではないかと思うのですけれども、それはいかがでしょうか。","respondent":"山下子ども家庭支援センター長","answer":"委員からございました子どもの権利条約につきましては、やはり国際的な取決めといいますか、皆さんこれを世界的に進めていこうということの動きの中で、やはり大事な一つの視点だろうと認識しております。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、先ほど言い忘れましたけれども、児童センターのあり方のアンケートの話もありましたが、児童センターにしても、子ども若者応援フリースペースにしても、やはり保育する、子育て、あるいは子どもの居場所がないというところで非常に重要な役割を果たしておりますので、ぜひ利用していない方、利用している方の意見を聞くということですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"虐待のほうなのですけれども、先ほど特徴的ということで、令和３年度は児童本人から通報があったという話がございました。これ、分かればでいいのですけれども、どうやって通報したのかというところを教えていただければと思います。","respondent":"山下子ども家庭支援センター長","answer":"児童本人からの通報、ご相談というところにつきましては、あまり事細かなことを申し上げてしまいますと、その経路が分かってしまうというところがあろうかと思うのですけれども、一定、来所か電話かといったような手段というところにおきましては。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問・要望","question":"その前段階で、自分が虐待を受けているということが認識できない子どももいると思っています。これはあくまで要望でとどめておきます。","respondent":"山下子ども家庭支援センター長","answer":"今の委員からのご指摘は、電話という手段自体が難しいというところである場合には、電話もなかなか通じないというところが課題としては残るところではありますが、私どもといたしましては、こういった相談窓口があるのだというところは周知啓発に努めているところです。","id":"exchange-040"},{"speaker":"松澤委員","kind":"質問","question":"児童センターの職員アンケートの結果の中で、４０代が２名というのは、若手がいて、年齢の高い方がいて、中間層が少ないというご説明がありましたが、前も聞いたような気がしたのですけれども、中間層の職員、要は４０代の方が少ない理由を教えてほしいのが１点と、コロナ禍だからこそできたことの中で、やはり事業に追われずに日常的な関わりの大切さを感じたという、この言葉に要約されるように。","respondent":"廣田子ども育成課長","answer":"ベテランは全然こなすのはできたのですけれども、若手が事業に追われてしまったと。ここ２年はコロナがあったので、事業も経験できない職員がいたので、そこも育っていないという状況で、このような言葉が出てきたという。","id":"exchange-041"},{"speaker":"松澤委員","kind":"質問","question":"まさにそうです。１個気になったのが、このアンケート、児童センターの職員向けだと思うのですけれども、私の一般質問でも言わせていただいたのですが、子どもたちの主体性が大きく発揮されるという、これがまさに児童センターだと思っているのです。言わば子どもの遊びというのは絶対密になるではないですか。密になるのが子どもの遊びですから。","respondent":"廣田子ども育成課長","answer":"皆さん、タブレットが配られているので、２年生に１月に配っていただいたのですが、ＱＲコードをタブレットで読んで、保護者と一緒に回答してくださいという形でお願いしています。","id":"exchange-042"},{"speaker":"松澤委員","kind":"質問・要望","question":"そういうのができているのは知りませんでした。そういった結果を踏まえて、しっかりこれから先、見えた課題であるとか、どういう方向性に行くとか、学校とも連携しながら、引き続き頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問・要望","question":"新たなこういう状況下にあっての認識。それはコロナ禍だけではない中で、実はずっと今まで潜在化していた部分だったのかというところだと思うのです。そうすると、それだけの数の、延べですから、分母の人数が何人かというのはまた別かと思うのですけれども、本来、それぐらいの方が何らかのことを求めて児童センターに来て、何らかのことをキャッチして、また心を満たして帰っていっていたのだろう。","respondent":"廣田子ども育成課長","answer":"具体的なお示しができなくて申し訳ないのですけれども、今、アンケートも、児童センターに来ていない人に来る気が起こることはとか、児童センターを知らない人が、どういうところだったら来ますとか、何が必要ですというのもアンケートで取っていますので。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問・要望","question":"本当にいい試行かと思うのです。まさにそのように考えるということを一緒にやるということだけでも、それも事業化ですかね。いろいろ世代関係なく、この２年間というのは、本当にちょっとすると、気をつけていないと暗い方向に走ってしまうのです。入っていないということだけ、もし分かれば教えていただきたいのですが、可能であればお答えいただければと思います。","respondent":"山下子ども家庭支援センター長","answer":"もしそういった案件に関わるものがありますと、教育総合支援センターから子ども家庭支援センターへの連絡というのは連携が取れるものと認識をしております。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問","question":"ただ、どこが主体でそういったことを取り入れていくことを考えて受け止めてくれるのかというのは区民委員会なのかと思ったりするので、別の機会にここはいろいろと考えながら相談をしたいと思うのですけれども、ただ、今、ご答弁あったように、そういうＨＥＡＲＴＳに来て、内容が教育総合支援センター長からのお話として、そういう子ども家庭支援センターのほうへの連携というのが既にあるので。","respondent":"山下子ども家庭支援センター長","answer":"これまでも、少し気にかかることがあったということでご連絡をいただきまして、私ども児童相談の部門と連携して対応に当たったことはあります。","id":"exchange-046"},{"speaker":"つる委員","kind":"確認","question":"まもるっちの部分、お答えいただいてありがとうあります。やってもらいたいと思います。それから、ヘルパーについての取り交わしをしていただいているというところで、これは当然、利用者もそういう前提というのは、そこは利用者のほうの文言にはそういうのが書いていなかったのですよね。逆に言うと、それが利用促進を阻害してしまったらいけないのですけれども、そこ、すみません、確認させてください。","respondent":"山下子ども家庭支援センター長","answer":"産後の家事・育児支援のヘルパーの利用助成におきまして、チラシでございましたり、ホームページの案内の中で、今、委員ご指摘のような、子ども家庭支援センター内の連携のようなところについて特に記載をしているところではございませんけれども、やはり実際には。","id":"exchange-047"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"児童センターのほうなのですけれども、職員アンケートの結果というところで、コロナ禍に取り組んだことで、様々こういうことをしていただいていたのだというので、本当にありがたいと思っているのですけれども、これに対してどういった反応があったのかというのが分かれば、少し具体的に教えていただければと思うのと、あとは、コロナ禍における利用状況というところでも、主な相談というのが。","respondent":"廣田子ども育成課長","answer":"利用者の皆さんの関連といたしましては、乳幼児親子に関しましては、まだ受入れをこちらが決断する前から玄関の前まで来たりとかしていただいた方もたくさんいらっしゃるので、開いたときに本当に、言葉どおり取ると少し怖い話なのですけれども。","id":"exchange-048"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"そうすると、先ほど来ご質問の中にもあったかもしれないのですけれども、コロナが明けてからも、やはり虐待というのは本来あってはいけないのですけれども、コロナ前に戻るということがもしかしたら難しいかもしれない。そういったところについては、どういったお考えで、今後どういった取組をされようと思っているのかというのがあれば、教えていただきたいと思います。","respondent":"山下子ども家庭支援センター長","answer":"一定、心理的な虐待のところにつきまして、ご夫婦でのけんかというのが、副委員長ご指摘のあった、ご在宅ゆえに、家にいる時間が長くなるゆえに、そういうもめ事というか、けんかに発展してしまったという事例は中にはあるのかと受け止めておりますけれども。","id":"exchange-049"},{"speaker":"湯澤副委員長","kind":"質問・要望","question":"本当にいざというときに頼れる人がいるということを認識してもらうことと、あと、いざとなれば助けてくれる人がいるということを認識する。そういうのを全ての児童・生徒、また、保護者もそうかもしれませんが、そういった体制づくりに努めていただきながら、引き続きたゆみのない支援をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"私からよろしいですか。は御礼申し上げます。私からは３つお伺いします。もしくは所管課につないでいらっしゃるのかというところを伺いたいというのが１つです。例えば、施設がよくなったからとか、使いやすくなったからとか、何かそのようなものがあるのか、教えていただきたいというのが２つ目。１７８件。食事を与えないとか、身体の汚れを放置すると。その３つをお伺いしたいと思います。","respondent":"廣田子ども育成課長、山下子ども家庭支援センター長","answer":"関係部署に、教育総合支援センター、ＨＥＡＲＴＳとも連携しながら、エールしながわにつなげたりとかはしたのですけれども、なかなか物事は改善せずに、食べ物もアルファ化米とかも置いていたりするので、食べてもらったりとか。実際には、海外に渡航されていて戻られていないですとか、一部、コロナによる影響と言えなくもない部分もあるのですけれども、委員長ご指摘の経済的な部分でネグレクトが増えているというところにダイレクトに反映するようには。","id":"exchange-051"},{"speaker":"安藤委員","kind":"確認","question":"確認したいのですが、すまいるスクールのところで、スタッフが感染して、それが子どもにうつったということなのか、そこら辺を確認したいのと、それとあと、すまいるスクールのほうは、第６波に入ってから、特にこれまでの対応と、コロナ感染対策というのは何か変えたところがあるのか、伺います。","respondent":"廣田子ども育成課長","answer":"食事についても距離を空けて、同じ向きでという、学校と同じように黙食という形で実施をしておりますので、コロナの第５波のときと感染が安定になったときも対応は全く変えておりません。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"やはりオミクロン株ですが、２０代から４０代の方の感染がかなり占めるわけです。高齢者施設はやっているわけですから、そういったのを改めて検討していく必要があると思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"どういう言い方をしたらいいのでしょうか。どういう状況からこの事態が分かったのかをお聞きします。","respondent":"若生保育支援課長","answer":"こちらの判明した経緯ですけれども、退職した職員から区への通報がございまして、それを基に東京都に情報提供を行いまして、令和２年７月に東京都が特別立入検査を行い、状況を確認した結果、こういったことが判明したという経緯です。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"本当に深刻な問題だと思うのです。本当にもうという感じなのですが、その後、適正配置されているということで、再発防止の取組をするということですが、どうやって再発防止をするのかということを具体的に聞かせていただきたいと思います。","respondent":"若生保育支援課長","answer":"そういう状況です。区としましても、この事態は重く受け止めてございまして、今後、認証保育所だけではなく、認可保育園も含めまして、きちんと適正な運営が行えるように、継続して指導等を行っていく必要があると考えております。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"これ、利用しているお子さんとか家庭については、配置がなされていなかったわけなのですが、どういった不利益があったのか、実害があったのかというのと、あと、そういった利用者の方への説明というのですか、謝罪などはどのように行われるのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"ただ、当然、足りない人数でやっていたからには、少なからずの影響はあったということで、これは当然、法人側としても説明を行う必要があると考えています。現在のところ、東京都が検査に入った結果が、東京都のホームページには既に昨年１月の時点で公表されております。","id":"exchange-056"},{"speaker":"松本委員","kind":"質問","question":"今のお話なのですが、特別の立入りのほうで、通報によって行われたということなのですけれども、一応、もともとは年１回、定期的に立ち入らないといけないというのは、これは認可外でもあると思うのですが、過去のここの、本当はこの所管は東京都なのですけれども、それ自体が私はおかしいと思っていますが、ここに関して、過去の立入りの調査状況というのはどのようになっていますでしょうか。","respondent":"立木保育課長","answer":"指導検査ですので、保育課からお答えいたします。こちらの法人、認証保育所ですけれども、東京都のほうが指導検査に入る際に、区も、同行してやっているところです。","id":"exchange-057"},{"speaker":"松本委員","kind":"質問・要望","question":"そこは結構なかなか重要なところで、これは所管が東京都というのは本当によく分かっているところなのです。その点については、東京都に対して、立入りについて条文がきちんとあるわけですから、きちんとした調査の上、必要に応じて制裁というか、罰金含めて対応するようにということを都と協議していただきたいと思うのですが、いかがでしょうか。","respondent":"立木保育課長","answer":"今回の件に関しましては、広域的なところで突き合わせをしないと分からなかったという部分があります。そうした部分に関しましては、東京都とも連携を取っておりまして、そちらのほうをきちんと対処するように、区のほうからも東京都のほうには話をしています。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"そういう外部に向けた通報の仕組みというのが、これ、全体、少し足りないかというのが、私たち今までいろいろ保育園の質のところで質問する中で感じるところなのですけれども、どういう通報の仕組みなのでしょうか。だから、その辺の通報の仕組みというのはすごく大事だと思うのですが、この事業者に限らず、全体としてどのように捉えているのか、伺いたいと思います。","respondent":"若生保育支援課長","answer":"このような公表を行うことで社会的な一定程度の制裁というところは行われているものと区としては認識しております。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"今日、取りあえずそういう仕組みがきちんとできることを要望いたします。これは今日は要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/449994?Template=document&Id=5056#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":63270,"voices":160}},{"id":"r04-20220117-5","meetingId":"r04-cm01","date":"2022年1月17日","dateIso":"2022-01-17","committee":"総務委員会","time":"午後 １時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"マイナポイント第２弾（国事業）の実施","agenda":"マイナポイント第２弾（国事業）の実施","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"コロナへの支援というならば、個人情報と引き換えに支援を出すのではなく、素直にコロナで困っていらっしゃる方に給付金を出すべきだと私は思うのですけれども、こういう国のコロナへの支援のやり方について、区としてどういうご見解を持っているのかということを１点目に伺いたいと思います。そこのところをご説明いただければと思います。","respondent":"宮澤情報推進課長","answer":"このマイナポイント事業自体の実施にあたりまして、先ほどの健康保険証としての登録であったり、公金受取口座であったり、いわゆるひもづけという形で個人番号とそれぞれの情報をひもづけますが、個人情報につきましては適切な管理をして行っていくです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"質問の１点目についてはちょっと曖昧な感じですけれども、とにかく私としては給付金、コロナ対応の経済対策ということであれば、困っている方に素直に給付金を出す対策を取ってほしかった。個人情報と引き換えに給付金を出すというやり方は取ってほしくなかったという意見を申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"渡部委員","kind":"確認","question":"１件だけ確認です。最後、地域センターの職員の方がこの方々が職員ですと言ったら、その人たちが相談に来たら対応しているということなので、今までプラスそれをやっているということなのか、それとも地域センターに委託でそれ専用の職員を配置しているということなのか、ちょっと地域センターのその部分だけ、明確に教えてください。","respondent":"宮澤情報推進課長","answer":"地域センターにおきましては、地域センターの職員が窓口にお見えになった方の対応をしているという形です。","id":"exchange-003"},{"speaker":"田中委員","kind":"確認","question":"第二庁舎にマイナンバーカードの交付特設会場を設置しているということで確認したのですけれども、たしかそこに生活困窮者支援の特設ブースも一緒にあったと思うのです。その特設ブースが２つ並んでいる状況で、生活困窮に陥った方たちの相談窓口がそこにあって、その当事者の方がなかなか行きづらいのではないかということを私はとても危惧したのです。","respondent":"宮澤情報推進課長","answer":"現在、第二庁舎３階の広いロビーの部分で、マイナンバーカードの交付特設会場という形で、令和２年より実施しています。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問","question":"基本的なことをお聞きしたいのですが、まず現在のマイナンバーカードの申請状況について、この二、三年、給付金もありましたし、このマイナポイント第１弾もありますけれど、どのぐらいのパーセンテージが出ているのか教えていただけますでしょうか。","respondent":"宮澤情報推進課長","answer":"マイナンバーカードの交付状況のお問い合わせです。令和３年１１月末現在の交付枚数は約１７万５,０００枚で、交付率は４３.１％になっております。令和元年度末の交付率が１９.３８％でございましたので、ここ１年強で２倍以上になったです。","id":"exchange-005"},{"speaker":"小芝委員","kind":"質問","question":"そういったところで、マイナンバーカードは、今は健康保険証として全体の８％しか使えていないということですが、ある意味このマイナンバーカードというのは、セーフティネットの最後の砦の一つにもなり得る可能性を秘めていると思いますので、やはり高齢者の方のマイナンバーカード保有率というのは多分かなり少ないのではないかと思うのですけれども、そういったことで。","respondent":"宮澤情報推進課長","answer":"広報紙でございましたり、区のデジタルサイネージとかでも周知等を図っております。高齢者向けのアプローチにつきましては、交付を所管します戸籍住民課と連携しながら、イベント等の出張であったり、出前的なところで来年度以降も検討していこうと考えております。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"今の質問と同じところがあるのですが、結局マイナンバーカードを取得するにもできない高齢者というのがマイナンバーカード取得弱者になると思うのですけれども、今もうここまで交付率が上がったというのは、私はある意味でマイナポイントの成果が出ていると思います。そして、今回のマイナポイントは、ここにも第１弾の未申込み者を含むと書いてあります。その辺についてちょっとご見解をお聞かせください。","respondent":"宮澤情報推進課長","answer":"マイナンバーカードの交付率を上げるための地域センターとの連携です。これにつきましては、戸籍住民課、地域活動課を含めて連携をとりながら行いたいと考えています。マイナポイント支援です。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"結局国の事業として、マイナンバーカードを取得すればこうやってマイナポイントを取得できて、お金として使えますよということが本来の趣旨だったわけですね。その説明に対してもやはり国に支援費というのを頂いてしっかりやらないと、これはいつまでたっても増えないのではないかというような気がしますので、その辺は区としてもしっかり国に言っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"たけうち副委員長","kind":"質問","question":"昨年、このマイナポイントの２万円というのが報道でいろいろ出だして、大分区のほうにも、まだ始まっていないけれどもお問合せがあったやに聞いているのですが、その辺の状況とか、あとどのようなお問合せが多かっただとか、もしあれば教えてください。","respondent":"宮澤情報推進課長","answer":"昨年１２月に事業が決定しまして、１月からマイナポイントの申込みが新規取得者の部分について始まったというところで、１月１１日号の広報紙に、記事量は少ないのですが載せました。その翌日に、電話のお問合せが３０件程度ございました。","id":"exchange-009"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"やはり２万円は大きいですから、そういうことも聞いていますけれども、先ほどご説明いただいて、今取得率が上がってきている中で、そういった中でこのマイナポイントを、言葉は悪いですけれども、これがもらえるならと、今までマイナンバーカードはセキュリティが不安だという方だけではなくて、不安ではないけれども、あえてマイナンバーカードを作らなくてもいいかなという方が結構いらっしゃっただろうと。","respondent":"宮澤情報推進課長","answer":"マイナンバーカードの交付体制、支援体制を含めて、所管します戸籍住民課と連携しながら進めているです。体制につきましては区職員、また会計年度任用職員、委託職員を活用しまして、体制を組んで積極的に対応していくです。","id":"exchange-010"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"意見だけ。ぜひ積極的に前向きにこれをうまく活用して、普及を広めていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ですから、主権者教育というか投票率の向上に向けての教育でも、架空の話ではなくて、もっと現実のことを教育すればいいのにと思ったりもしたのですけれども、そのように現実の政治で魅力ある政策を私たち政治の側が提起できているかどうかというところにもっと着目して、そういう角度からの投票率の向上ということを考えていくべきだと私は従来から思っているのですけれども。","respondent":"齋藤選挙管理委員会事務局長","answer":"学校の現場でもう少し具体的なリアルの政策をというお話がありましたが、やはり日本の国の立て付けでは、政治的中立性というものが学校の現場では求められておりますで、具体的にどこかの会派の主張を比べて評価するというのは。","id":"exchange-012"},{"speaker":"おくの委員","kind":"確認","question":"今の内容については、だからそこら辺から、私は考えを学校教育の現場でも改めていったほうがいいのではないかと思います。そういうことで中立とかということにこだわっていると、結局は投票率が低いまま推移していくのではないかと思います。次にいきます。その点は、確認みたいになりますけれども、そういう理解でよろしいのでしょうか、伺います。","respondent":"齋藤選挙管理委員会事務局長","answer":"選挙制度に義務制を入れるということの議論は、品川区のレベルでできることではありませんし、私どももそのような権利制限ということを正しいとは考えておりませんので、あくまで投票率が高いという国の例をということでお示ししただけです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"品川区の多分６年生だと思います。それはつまり投票に行くこともそうなのだなと実感することができる機会があるので、そういった取組みとかも充実していってほしいと思います。何かあったら伺えればと思います。今、その若年層の方たちにどういった働きかけ、啓発活動がされているのかというところをお知らせいただければと思います。","respondent":"齋藤選挙管理委員会事務局長","answer":"先ほど教育の現場で政治的中立性というのをちょっと抜かしてしまったのですけれども、やはり小学校６年生ですとまだ発達段階にありまして、何がよくて何が悪いのかというのを自分の意思で決める、考えるというのがなかなか難しいので。","id":"exchange-014"},{"speaker":"田中委員","kind":"意見","question":"国分寺市で、「国分寺の投票率を１位にプロジェクト」というのが、この前衆議院議員選挙の時に発足されて、若者たちが一生懸命例えば選挙割だったり、そういった活動をされていたというのがあったのですが、品川区でも最初に若者たちが投票率を上げようと行動する時に、よく選挙割の話はセットで挙がってくるのですけれども、その選挙割を実施した時には。","respondent":"齋藤選挙管理委員会事務局長","answer":"ただ、選挙割というのがクローズアップされた後、総務省のほうから通知のようなものがありまして、あくまで投票は本人の自発的意思に基づいて実施すべきもので、利益誘導型の選挙投票行動を行うようなことを選管事務局が。","id":"exchange-015"},{"speaker":"田中委員","kind":"意見","question":"やはり若年層の投票率の向上という部分で、若者たちの視点と、その投票率を上げたい選管だったりほかの方たちの視点が大分異なる部分があると思うので、どうしたら投票率を上げられるのかという、上げていくための活動、意見交換というのはとても重要だと思うので、このコロナ後にもっと活発に若年層の方たちとの議論の場を設けていくということですけれども。","respondent":"齋藤選挙管理委員会事務局長","answer":"日本はどちらかというと同調する力が強いのに、こと選挙に限ってはなぜか必ずしも選挙に行かなくても特段のものはないというところがありますので、そういった形でちょっと時間はかかるかもしれませんけれど、長い時間をかけて意識啓発に努めていきたいと考えています。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"そしてそれが投票ですからその方向に、やはり民主主義で多いほうの希望が通ると。そこにそれぞれの人の顔写真が載っているというのを気楽に気軽に割と頻繁に目にするような、大きさは別に小さくなってもいいと思うのですけれども、そういう仕組みもあっていいのかなと思ったのですが、それもやはり掲示する場所というのは公的に決められているのですか。そういうふうに決められているのですか。","respondent":"齋藤選挙管理委員会事務局長","answer":"場所につきましては、やはり公共機関ですとか公園ですとか学校ですとか、同意が得られやすい場所にどうしても置かざるを得なくて、一番いい場所というとなかなか難しいのが現実でありますが、これからも努めて見やすい場所ということは考えていこうと考えています。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"そこに少し予算、お金もかかってきますけれど、何かそういうこともやれたら、ひょっとしたらそちらのほうに、では自分も１８歳になったら選挙に行って、ひょっとしたら自分たちの希望がかなうのかな、自分たちの気持ちが少しでも反映されるのかなと思ってもらえたらいいということで質問させていただきました。その真意だけ伝えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"中学校時代を思い出すと、やはり選挙をやっているのですね。質問するとすれば、いわゆる明るい選挙推進協議会の方々が行っての出前模擬選挙という形ではなくて、例えば実際の中学校なり義務教育学校の生徒会長を決めるのに、区の選挙の道具とか用品を持っていってやってみたりというような経験はあるのでしょうか。","respondent":"齋藤選挙管理委員会事務局長","answer":"今、委員のご指摘があった投票箱や記載台をお貸しするという例はございません。","id":"exchange-019"},{"speaker":"渡部委員","kind":"提案","question":"それが何かのルールで駄目だというならともかく、品川区の持ち物で、公立学校で生徒会長を決めるという時に、もしどこかの学校からそういう提案でもあったら、ぜひ一度何にも法に触れるところがないのであれば、やってみてもらいたいというのはちょっと思いましたという感想で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"小芝委員","kind":"質問・要望","question":"豊富な資料からのご説明、ありがとうございました。そういう中でＧＩＧＡスクール構想があって、ＩＣＴ化、タブレットを児童・生徒に１個渡されるようになったわけですから、教室の中で政治の関わり、公民の授業、その中でもっと教室の空間を超えたところでの議論というのができてくる選択肢は多分いろいろとあると思うのです。","respondent":"齋藤選挙管理委員会事務局長","answer":"具体的にＩＣＴを活用した主権者教育がどのように動いているかというのは承知しておりませんし、具体的な動きがあるとは聞いていないですけれど、例えば学校をまたがって、小学校や中学校を要は交流しながらいろいろな考え方を交換するだとか。","id":"exchange-021"},{"speaker":"小芝委員","kind":"質問・要望","question":"今はＳＮＳを使ってアンケートも普通にできてしまうぐらいなので、それはもちろん謝礼があるから偏ったりすることがあるかもしれませんけれども、本当にただで使えるツールがたくさんこのインターネットの空間には転がっていますので、そういったものをぜひ活用していただきたいと思いました。意見です。","respondent":"齋藤選挙管理委員会事務局長","answer":"受け手はパソコン、タブレット、あるいはスマホといったものを活用して、それを交換したりまたはリツイートするといった形で選挙運動が幅広く展開されますので、若年層にはそういったツールというのは大事だと思いますし、元々と言うとちょっと口幅ったいのですけれども。","id":"exchange-022"},{"speaker":"たけうち副委員長","kind":"質問","question":"資料３の啓発チラシで、「１９歳の有権者の皆様へ」ということで、ピンポイントに一番下げ幅の大きいというか、投票率の下げ幅が大きい１８歳から１９歳のところに絞って、こういう形でチラシを入れるということを続けていらっしゃるみたいですけれども、これの成果が出ているのかというところと、それから資料１のグラフで１８歳のところから２１歳から２４歳のところまでを赤く囲っていただいて。","respondent":"齋藤選挙管理委員会事務局長","answer":"２３区ではやはり都知事選が一番投票率が高いという傾向があり、次が衆議院議員選挙で、やはりマスコミや新聞などで顔を見られる人というのは身近に感じられて選ぶという動機づけになるようですが、やはり区長、区議選については、粘り強い形でもって啓発をする以外。","id":"exchange-023"},{"speaker":"たけうち副委員長","kind":"質問","question":"なかなか評価が難しいところだとは思うのですけれど、ただ、この１９歳の啓発チラシはまた続けてやっていかれるのかなと思います。先ほどもちょっと大学のお話が出ましたけれど、この２１歳から２４歳、また２０歳、この辺の世代というのは大学、専門学校に行っていらっしゃる方もいると思うのですけれど、区内のそういったところに向けて選管が啓発していくということはやっていらっしゃるのですか。","respondent":"齋藤選挙管理委員会事務局長","answer":"先ほどお話ししましたが、立正大学とはあるゼミとの関わりを持ちまして、意見交換の場を年に二、三度持ったところですが、他の大学とはありません。今後、そういった方々も含めて広くフィールドワークのような形でもって、若い人の層のご意見を聞きたいと思っているところです。","id":"exchange-024"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"分かりました。品川区の大学に通っているから、必ずしも住民票が品川区にあるかどうかというのは、そうでない方も結構多いかもしれないですけれど、ただ、大学とか学生たちにもそういった連携をしていくことで、地道かもしれないですけれど、着実に上向いていければいいなという期待を込めて要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"渡辺委員長","kind":"質問・要望","question":"ほかはいかがでしょうか。では、私のほうから伺いたいことが何点かあります。もう一つの区分はやはり教育現場。議会のことは、これから議会に持ち帰って、あるいはこの総務委員会で今日の所管事務調査を踏まえて何か提言ですとか要望が議会全体に対してもあるだろうし、行政側にもあるだろうしという、そのような感覚を持っていますので、皆さんとぜひ相談したいと考えています。この２点をまず伺います。","respondent":"齋藤選挙管理委員会事務局長","answer":"危機感という意味で言うと、品川区は２３区では大体６番目か７番目に投票率が高い認識があるのと、もう一つは目標値として何％まで上げることで、明推協としての活動の成果があるのかという設定ができていないし、なかなか作りにくいのですけれど。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"ですから、今こういう議論があって、委員長がおっしゃっているとおりで、そのまま、一生懸命選管とかがやってきてはいるのだけれども、全体として見た時に底上げというのは、やはり国全体でどのように考えていくかというのをやらない限り、やはりその２１歳、２２歳というのがよそから流入された方たちだと、残念ながらそこは厳しいのかなという思いだけが自分の中でずっとくすぶっているものがありまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"これは質問していいのか、駄目だったら意見だけ言わせていただきますけれども、接種履歴確認のお知らせというのは、品川区に在住していても、港区の老健に入所しているとこのような案内が来て、ということは、品川区では品川区の住民のどの方が接種したか、していないか、全く分からない状況に今もあるのか。それに返信用の封筒も切手も貼っていないのですけれど、どうしてこういうことが起きるのですか。","respondent":"古巻総務課長","answer":"聞いた範囲でしかお答えできないですが、いわゆる２回目までの接種履歴というのは、国のシステムのほうには入っているのですけれど、区のほうのシステムとの連携が難しくてできないということで、区では、他の自治体で２回接種してから転入してきた方とか。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"品川区在住で、ただ港区の老健に入って２回接種をそこでしましたと。けれども、品川区のほうから２度接種しましたかとまず案内が来て、もし接種したなら、接種したとご回答くださいと。それもなおかつ返信用の封筒もなければ切手も貼っていなかったので、どういうことだということで、いや、だから区と国の連携がなければもうしようがないのですけれども、ちょっとこれは不思議だと思ったのです。","respondent":"渡辺委員長、古巻総務課長","answer":"今は総務課の範疇の答弁で、後でそこは個別にやってください。先ほどの続きの説明だけ。須貝委員がおっしゃっているのは住所地特例で、いわゆる住民票はあるけれど区外の施設に行かれている方ということだと思うのですが、ちょっとそのあたり、どのように連絡しているかは私どもで把握していないので、すみません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982063?Template=document&Id=2222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":28364,"voices":69}},{"id":"r04-20220118-14","meetingId":"r04-cm01","date":"2022年1月18日","dateIso":"2022-01-18","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"企業などが提供するサービスを利用する際に、個人データを提供することについて、８割が不安を感じる。私たちも、デジタル化の最大の大前提としては、政治の透明性と、要は、デジタル化を進める国や地方自治体が、政治の透明性と説明責任を果たせる、そして、個人情報を適切に管理し、安心・安全を求める国民に信頼されているということがすごく大事だと思うのです。","respondent":"宮澤情報推進課長","answer":"区では、セキュリティ対策として、まず、ネットワークのあり方につきましては、平成２８年から、インターネットに関するネットワーク、職員がパソコン等で業務をするネットワーク、また、個人番号を取り扱う業務で使うネットワークということで、３つのネットワークに分けて。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"安全性のところは、最大限やっていただいているというところです。そうすると、ガバメントクラウドに移して、もしも本人の個人情報、プライバシーが侵害されたり、漏えいしたときに、責任を取るのは地方自治体になるのでしょうか。もし地方自治体が責任を取るとしたら、どのように取ることになるのか、そのようなところは、今、考えられているのかを伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"今後、システムの標準化につきましては、国が指定するガバメントクラウドのほうにデータを移行するという形になってありますが、ガバメントクラウドの仕様等を含めた内容は、これから国から示されてくるですので、今の段階では、計画的・具体的なところは。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"去年の２月にもデータセンターで事故が起きたりと、ＡｍａｚｏｎやＧｏｏｇｌｅのこうした管理運営で、様々な事故が起きている下で、ここにガバメントクラウドとして託していってしまうということは、やめるべきではないかと私は思うのです。ですので、ガバメントクラウドの利用はやめるべきだと思うのですけれども、区の考えはいかがでしょうか。","respondent":"宮澤情報推進課長","answer":"システムの標準化後に、ガバメントクラウドのほうにデータを移行するという部分につきまして、まだ詳細な仕様等が出てきていない段階で、なかなかお答えはできないと思うところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"こうしたデジタル化を進めていく中で、区民、国民の安全・安心が本当に最大限に図られるべきなのに、ガバメントクラウドと聞いただけでも分からないようなものです。しかし、やはり必要な人材というのは、しっかりととどめておいてほしいと思います。窓口業務はすごく大事だと私は思うのですが、まず、区の窓口業務の役割について、区はどのように考えられているのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり、窓口業務は、住民を最善の行政サービスにつなぐ役割を担っていると思いますので、残すべきところは残すというところで、デジタル化を進めるに当たって、窓口業務、そして住民に接する業務の職員たちをどのように考えられているのかを伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"一方で、業務の効率化を進める部分になりますが、業務の効率化を進めて、生産性が向上することによって得られる時間を、例えば窓口の相談業務に、人でなければできないというところの業務に時間を振り向けることで、窓口では丁寧な対応ができるのではないかと考えるところです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、そのようなデジタル化に伴って、住民と直接対面する場を減らすことのないようにしていただきたいと私は思います。ですので、ただ急ピッチに進めていくだけではなくて、こうした区民がきちんと守られるということを進めていくことも同時に必要だと思います。そのようなところを、どう強化していこうというところがあれば、ご説明いただきたいのですが。","respondent":"宮澤情報推進課長","answer":"１つ目として、窓口のサービスの向上につきましては、繰り返しになりますが、業務の効率化により得られる時間を、丁寧な窓口対応等に振り向けることができるというところで、デジタル化のメリットを活かせるのではないかと思うところです。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"意見","question":"区として、セキュリティ、そのような外部からのサイバー攻撃などというものから守っていくということはあると思うのですけれども、区民が情報を取り扱われることで守られるものを、しっかりと構築していくべきだと思うのです。それなくして、急ピッチにデジタル化といっても、信頼を得られないと私は思いますので、そのような下で進めるデジタル化は、すべきではないと考えています。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"芹澤委員","kind":"質問・要望","question":"２点、お伺いします。以前、行財政改革特別委員会か予算特別委員会かでお話ししたのですけれども、デジタル化を進めていくに当たっての品川区としての計画はまだできていないのですかということが、一つ、確認です。新たな課長になると思うのですけれども、そこの横串を刺す力の強さの２点、お伺いいたします。","respondent":"宮澤情報推進課長","answer":"推進体制は、先ほど説明させていただきました、全庁横断的に課題に取り組んでいく必要がありますので、会議体をつくりまして、その中でＤＸの推進の状況を確認しながら、軌道修正しながら、進めていきたいと考えているところです。","id":"exchange-008"},{"speaker":"芹澤委員","kind":"提案","question":"けれども、やはり専門的なものは知らないものもたくさんあると思っていて、そこは、ぜひ新しい会議体の中で新たな提案をして、区全体でこのようなことを取り入れようという、例えば、デスク周りのＩＴ化もどんどん進んできていると思うので、このようなやり方をやってみようということをぜひ決めていただいて、原則、みんながそれを守って、どんどん、最新のデジタル化ができればいいと思っていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"西村委員","kind":"質問・要望","question":"２点、お伺いさせてください。１点、聞き漏れておりましたら、すみません。オアシスルームのキャッシュレス決済の推進、６２％ということで、大変高いと思うのですが、全体的な導入の検討をされているとおっしゃったかどうかを聞き漏らしておりまして、検討されておられたら、お聞かせください。ここは、ぜひともさらに推進をしていただきたいと考えています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"西村委員","kind":"質問・要望","question":"具体的な質問で申し訳ありませんでした。一例として出させていただいたのですが、ご答弁いただいてありがとうございました。本当に区民の方たちがあったらいいなというものが、デジタルで解決できるという世の中に、ますますなってきていると思いましたので、そのような意味も込めまして、要望も含めて、質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"例えば、行政手続のオンライン化で、戸籍証明、住民票の写しは、オンライン申請をして、今、取れるようにということで、品川区で始めています。このシステムは、品川区が、どこかの企業が開発したソフトを購入して、場合によっては、機器、コンピュータ、サーバー、１つぐらいを購入して、この事業をやっているのかどうか。いや、そうではない。どのような形になっているのかを教えてください。","respondent":"宮澤情報推進課長","answer":"その根拠といいますか、流れという部分になりますが、今までシステムの調達につきましては、自治体が独自で調達し、法改正等が生じるたびに、職員が、その法体制に対応できるように、カスタマイズを重ねていました。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"例えば、中にいろいろな事業者があったとして、同じようなシステムをつくっているということで、そのときに、どこのサービスを使うのですかということが、一つの検討になってくるのだと思うのです。今、情報推進課長のお立場で、そのようなお考えを、個人としてどう思うかということと、実際、そのような検討なり、議論なりは、どこかで始まっているということがあるのかどうかをお聞かせください。","respondent":"宮澤情報推進課長","answer":"これらを２３区で共同で調達するという場合になると、先ほどの基幹系業務システムの共通化・標準化と同じように、まず、どのようなシステムを活かしていくかというところの検討から入っていかなければいけないというところがあります。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。そのような意味では、まだ手のつけられていなかった、オンライン化、デジタル化されていなかったところを、これからやろうというときには、もしかしたらチャンスがあったりするのかなと思いますので、そこは、できることは進めていただきたいと要望したいと思います。このことについて、お伺いしたいと思います。","respondent":"宮澤情報推進課長","answer":"システムの利用に関しては、当然、区の負担が発生するところですが、ガバメントクラウドに移行した後のいわゆる基盤の部分の保守等につきましては、ここがまだ国から示されていないので、どのような形になるかということが、現状ではまだお答えができかねるです。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。ここをどこが負担するのかという、国が負担してくれるのかというところは、私としてはそうなのだろうなどと勝手に思っています。少なくとも、共通化することによって、品川区が自前でやっていたときよりは、負担は減るのだろうということは言えるというところでよろしいでしょうか。","respondent":"宮澤情報推進課長","answer":"ガバメントクラウドを利用した場合につきまして、まだ詳細は出てきてはおりませんが、一定程度の負担は出ると考えているところです。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"これは、令和７年度末には、しっかりと各自治体が標準化されていく。そのようなルールの中で、今、動いているということの確認と、例えば、そのようになれば、納税にしても、国保等にしても、いわゆる日本の中で、例えば、品川区と、どこどこの区でも、申請書類が少し違っていたものも、ある程度共通仕様化されていくのかどうかということを、まず１点、教えてほしいです。それが２点目。","respondent":"宮澤情報推進課長","answer":"テレワークの活用ということで、今、１２０台と申し上げましたが、クラウドサービスを活用した、セキュリティを確保した形で、テレワークを実施していますが、セキュリティ上、確保するという部分につきまして。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"そのようなものも、マイナンバーカードを使うことによって、キャッシュレス決済化をどんどん進めることもできるのかなと思いますので、幅広く進めてほしいと思います。そのようなことを進めることによって、その口座からしっかりと引き落とせるような仕組みづくりが、すぐにというわけではないと思うのですけれども、それこそ、３年後、４年後を見据えて、進めていただきたいというところは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"せお委員","kind":"質問・要望","question":"２点ほどお聞かせいただきます。そのようなところとの関連は、システムの標準化・共通化のところは、どうなっていくのかということをお聞かせいただきたいです。それから、やはり、私たち小さい子がいる親からすると、品川区全体で情報を共有してほしいというところが大きくありまして、例えばですけれども、私立幼稚園・保育園、オアシスルームなどといったところの情報共有もされていくのか。","respondent":"宮澤情報推進課長","answer":"２点目のところです。情報の共有化という部分になりますが、個人情報になりますので、ご本人の同意なく共有化ということはできない、システムによる共有化は難しいと認識しているところです。","id":"exchange-018"},{"speaker":"せお委員","kind":"質問・要望","question":"すごく理解できました。行く場所、行く場所で、同じことを話すのです。例えば、オアシスルームでも、行くたびに面接をして、その後から利用できるというところがあるので、このようなシステムを整えていただいた後に、そのようなところで情報共有がされていけば、利便性は図れるのかなというところがありましたので、そこはお話だけさせていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、区のデジタル化の取組みについて、今、民間で言えば、ネットバンキングのように、民間の金融機関でも、２４時間、それぞれお客様のサービス、要望に対応・処理しています。きちんとしたものが出ていない、決まっていない以上、２０２５年を目標にするということは、国のやり方がいささか横暴過ぎるのではないかと私は思いますが、その辺について、ご見解をお聞かせください。","respondent":"宮澤情報推進課長","answer":"そのような状況ではありますが、今、国が示している、義務化している令和７年度末までというところを目標として進めていくに当たりまして、区としても、関係各所１２課にまたがりますが、集まりまして、まず、状況認識、情報共有を図って。","id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"今までも、きっと各自治体がデジタル化を進めていたはずです。改正したら、またそこで変更しなければいけない。だから、もちろん、予算は全部出してもらうにしろ、ここまで、２０２５年までにやれと言うなら、やはり国のほうで、このようなシステムをつくったから、各自治体はそれを参考にして、運用できるようにつくってくださいということが筋なのではないかと私は思うので、意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"少しだけお伺いしますが、まさにデジタル化は手段であると言ってやっていこうという、あくまでも手段であって、区民の利便性向上や行政業務の生産性を向上していこうということは、非常にいいことだと思っています。このようなことをやっていったほうがいいのではないですかということは、誰が主導権を握ってやっていくのか。それ以外はもう押さなくていいと、９割ぐらいは押さなくなるではないですか。","respondent":"宮澤情報推進課長","answer":"それらの内容に基づいて進めていくということが、まさしく全庁的な連携を進めていく上での横断的な会議体の中で議論して、決定していくという形になろうかと思います。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"だから、どうしてかというと、これで、情報推進課の情報戦略担当課長が中心なのだろうけれども、例えば、国もデジタル化をやる、何をこうやっていこうといったときに、民間の人をたくさん入れたではないですか。そこは止まるような気がしてならない。もっと言うと、今、これも調べているから、代表質問で出てくるかもしれないけれども、例えば、給食のアレルギー食があります。それだけ言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"データ化については、職員の削減などではなく、住民の利便性向上や職員の仕事の質を高めるために進めていくと、まず、求めておきたいと思います。可能な手続きということなので、すべてではないのかと思うのですが、そこのところの確認をさせていただきたい。やはり、そうした場合には、窓口で手続きができるようにすべきだと考えていますけれども、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"オンライン申請によって効率化が図れる一方、やはり、その効率化によって生み出される時間というのは、人でのきめ細かな対応のほうに回すというか、振り向けていくという形になりますので、併せて取り組んでいくです。","id":"exchange-024"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"併せて、標準化については、区が独自に行っている施策などもあると思うのですけれども、そうしたところでは、カスタマイズができるようにすべきだと思うのですが、いかがでしょうか。カスタマイズするために、費用が必要になってくると思いますので、そのようなところは、国にしっかり費用負担をしていただくように、支援を求めていただきたいと思うのですけれども、いかがでしょうか。伺います。","respondent":"宮澤情報推進課長","answer":"国から示される標準仕様書については、多くの自治体が取り組んでいる業務の内容という部分になりますので、区が独自に行っている事業の部分があった場合、それがまさに内容を精査する部分になっておりますが、内容を精査した結果、そのような部分があった場合。","id":"exchange-025"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"標準化することによって、区が進めてきた政策が弱められないように、制限されないようにということで、区としても取り組んでいっていただきたいと思います。トラブルが発生したときには、ベンダーと連携をしていくということですので、それがベンダー任せになって、対応が遅れたりといったことがないように、区としてもしっかり危機に対応できるようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/893508?Template=document&Id=6122#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":28941,"voices":63}},{"id":"r04-20220119-19","meetingId":"r04-cm01","date":"2022年1月19日","dateIso":"2022-01-19","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"私からは、前の流れもありますので、防災ラジオについてご質問したいと思います。今の説明の中にあったアナログ波が若干残されるということですけれども、そうしますと、どうなのでしょう、古い防災ラジオは回収されずにそのままにしておくということなのでしょうか。そこら辺、ご説明いただきたいと思います。","respondent":"平原防災体制整備担当課長","answer":"今後ですけれども、アナログ波とデジタル波双方に対応した自動起動タイプが、まだ期間は総務省のほうから明確には出てきていないのですが、しばらくの間、併存するということになりますので、そういったところでは、例えば使い分けていただく。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"でも、いずれにしろ、新防災ラジオがないと、防災ラジオとしての機能は十分に果たすことができないということであって、新防災ラジオは必要になるということではあるのですか。","respondent":"平原防災体制整備担当課長","answer":"今ご指摘のとおりでございまして、アナログ波の運用につきましても、あくまで暫定のものですので、今後、必ず終了する時期が参ります。その際には新たな防災ラジオが必要になるものと考えています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"新防災ラジオですが、７月のこの委員会でお願いしたことですけれども、できるだけ安くお願いしたいということなのですが、要するに防災ラジオは防災行政無線の補完という位置づけですから、やはり安くだけではなく、無償でやっていいのではないかというか、無償でやるべきではないかと、私、その後さらに考え始めたのですけれども、と申しますのは、防災行政無線自体。","respondent":"平原防災体制整備担当課長","answer":"あっ旋価格についてのお尋ねです。こちらにつきましては、令和４年度予算に計上されるということもございまして、現状、まだどのぐらいというところは固まってございませんけれども、現時点では有償配布ということで考えてあります。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"数もそんなに多い数ではないと思います。前回の実績というところでも、前の資料からすれば４,６９５台ということでした。前回のご答弁の範囲では、どうしても有償でやるということが当然の前提になっていたのですけれども、無償で配布するということを選択肢の１つとして考えていいのではないかと私は思うのですが、有償を絶対的な前提とするということで今もお考えなのでしょうか。どうでしょう。","respondent":"平原防災体制整備担当課長","answer":"今ご指摘のございました他区の事例につきましては、私どもも様々なところを研究させていただいたところですが、品川区におきましては、平成２４年度の防災ラジオの更新というような観点もございまして、有償での配布ということを考えさせていただいているところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"同じことの繰り返しになりますけれど、無償のサービスである防災行政無線の補完、しかもその補完の中でも非常に有力な手段なのが防災行政無線ですから、それを有償での配布ということにしますと、いま一つ筋が通らないと私は思います。有償の配布を絶対的な前提とするのではなく、無償の配布を有力な選択肢として考慮願いたいと思います。そういうふうにお願いしまして、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"小芝委員","kind":"質問","question":"2)の町会・自治会長にタブレットが配付されているというのは存じているのですけれども、地域の町会長と話をしていますと、まだ開いたことがないという方もいますし、なかなかどういうふうに使っていいのか分からないといった声も伺っているところなのですが、配付されてからどのくらいたったのか分かりませんけれども、地域の声ですね、防災課にどういった声が上がってきているのか、また。","respondent":"平原防災体制整備担当課長","answer":"さらには、使い勝手のところでいきますと、これは直ちにできることではございませんけれども、より詳しく説明する機会を各地域ごとに設けさせていただきまして、防災タブレットの今後の活用。","id":"exchange-006","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問","question":"でも、やはりなかなか使い方が分からないという町会長だと、何だかよく分からないのだよねという話も聞いておりまして、これからいろいろとフォローアップをしていただくという話は伺ったのですけれども、こちらは、防災訓練だとか、そういった訓練の行事の前に一定期間集中してそういった取組みをされるのか、１年間を通じて、例えば１シーズンに１回ぐらいとか。","respondent":"平原防災体制整備担当課長","answer":"これは何も防災に限ったことではなくて、例えば地域の集まりなんかでも使えるような形で全庁的にもご紹介させていただいているところですので、そういったところも捉えながら、広げていきたいなと考えています。","id":"exchange-007","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問・要望","question":"そういったしっかりした充実した情報というのが、せっかく広がりが見えているのに、なかなかそういう人に伝わらないなと正直感じているところがあるので、そういったいい情報をうまく波及できるようにするといいのかなと個人的には思っていますので、そういった部分に関して、これからどういった充実を求めていく考えがあるか、お聞かせください。","respondent":"平原防災体制整備担当課長","answer":"こういったインターフェースの充実にとどまらずに、情報をきちんと出す、今、チャットボットなどの実装も行っているところですが、そういったところできちんと連携できるように、今後も充実させていただければと思ってあります。","id":"exchange-008","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"意見","question":"おっしゃるとおり、８０％、９０％、ＬＩＮＥを活用しているという部分で、しっかりとＬＩＮＥの波及、そしてまた、情報弱者と言われる方には防災ラジオの充実、品川区は確かに情報伝達にかけてはすごく一生懸命取り組んでいると思っていますので、今後とも引き続きよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"質問","question":"Ａ３資料の３の7)のところで、避難情報緊急通知コールというのがありますけれども、目黒川の氾濫とか津波ですとか土砂災害等の警戒地域というのですか、対象区域の方が登録されることになっていると思うのですが、今、大体どれくらいの方が登録されていて、実際にこれまで緊急通知コールを行ったというのは、どういったとき、何回ぐらいあったのかというのが分かれば教えてください。","respondent":"平原防災体制整備担当課長","answer":"実際のコールですけれども、台風１９号など、実際にそういったところで発災したときにお送りさせていただいているものですので、こちらの通知実績というものは、行っているところです。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"台風１９号のときということなので、そうすると、自動的に機械音みたいなので、電話を登録されている方のところにいって、その方が電話に出ると、機械音みたいな音で今こういう状況なので避難してくださいとか気をつけてくださいとか、イメージとしてはそういう感じなのですか。","respondent":"平原防災体制整備担当課長","answer":"今ご指摘ございましたとおり、例えば電話が鳴りまして、機械音声でこういう情報が出ていますので避難してくださいというふうに流れるものでありますとか、あるいは、選択によってはメール方式のみにするということもできますので、電話ではなくてメールで鳴る。","id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問","question":"防災行政無線とか防災ラジオもそうですけれども、緊急情報が一番必要な状況というのは、もちろん地震も、起きたとき、その後の様々な情報が必要ですが、例えばこれから間もなく川が氾濫するよとか、津波というのはなかなか考えづらいけれども、ないとは言えないわけなので、津波が来ているよとか、そういった緊急情報が一番必要になってくると思うのですが、その中で、やはり家の中にいると。","respondent":"平原防災体制整備担当課長","answer":"防災ラジオの今後についてですけれども、委員ご指摘のとおり、まずは平成２４年度の前回購入者に対します案内を中心とさせていただいているところですが、引合いの状況などを見ながら、今後の取組みを検討させていただきたいと考えているところです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"実際に高齢だったり障害があったりということで、逃げなければと思うのだけれども、なかなか行動に移せないというようなこともあって、そういう方たちへの、きちんとそれを受け止めたらどういうふうな行動につながるかというところは、もしかすると体験・講座という9)に当たるのかしらと思いながら伺っていたのですが、その辺について何かお考えがあったら。","respondent":"山本防災課長、平原防災体制整備担当課長","answer":"私から、１点目の高齢者、障害者等、避難行動要支援者に対する周知というところをご説明します。私からは、被災情報管理システムの充実の具体的な内容についてご説明します。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。やはり支援する人は、何とか避難させようと思って、一緒に逃げようというふうにするのだけれども、なかなか逃げるという行動につながらなかったというようなことを伺います。障害者福祉課との連携も必要だと思うのですけれども、その辺については、情報提供とそれから福祉的な視点と両方、あったら教えていただきたいのですが、いかがでしょうか。","respondent":"山本防災課長、平原防災体制整備担当課長","answer":"こちらにつきましては、ちょうど３月の、すみません、日付は手元にないのですが、しながわ防災学校で、熊本地震で実際に被災された方の体験を２名の方にお話しいただくという講座を予定しているところでございまして。聴覚障害者への配慮ですが、こちら、確かに音で聞く情報というものが多くなっているのですけれども、例えばテキスト配信ですとか、そういったところもありますが、いずれにしましても。","id":"exchange-014","title":"町会・自治会支援"},{"speaker":"吉田委員","kind":"質問・要望","question":"体験とかはしながわ防災体験館とかしながわ防災学校でというのが妥当だと思うのですけれども、それを、コロナ禍でもありますし、今はオンラインでいろいろな体験を聞けるというようなこともありますので、ぜひそのようなことも検討していただきたいと思います。もちろん学校教育の中でもそれは必要ですので、教育委員会とも連携していただきたいと思います。もし何かあったら、お答えいただきたいと思います。","respondent":"山本防災課長","answer":"こちらにつきましては、ページ数も比較的コンパクトにまとまって、かなりいい情報が載っているものだと考えていますので、そういった部分で、活用というところは、今後機会を見ながら、いろいろ考えていきたいと思ってあります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それは区の責任において周知していただきたいし、診療所にも周知用のポスターなどを提供していただきたいというご要望を頂いているのですけれども、こういう要望は多分区にも届いているのではないかと思うのですが、この対応はどうされているのか教えていただきたいと思います。","respondent":"山本防災課長","answer":"以前になりますが、区の広報紙でもそういったご案内を差し上げたところです。現在、ポスター等の作成等は行っていないところではありますが、引き続き医師会等ともお話ししながら、今後の対応というところは考えていきたいと思ってあります。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、そういうところを医師会の先生方がすごく心配されているのではないかなと思いますので、医師会の先生方は、ポスターを各診療所に貼って、常日頃からそういう情報を区民の皆さんに、様々な防災情報というところの１つだと思うのですけれども、特にこれは命に関わる部分なので、そういうふうにしていただきたいという要望が出されているのだと思いますので。","respondent":"山本防災課長","answer":"１点目の医療救護体制の区民への周知というところですが、委員ご案内のとおり、発災後の混乱防止というところもありますので、引き続き医師会とも連携して検討していきたいと思ってあります。それから、２点目の障害者等への対応です。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"合わせると３万人くらいいらっしゃると思うのですけれども、その中で個別計画を組んでいくというのはたしか１万２,５００人ぐらいという報告を前に頂いたと思うのですが、介護認定を受けている人、手帳を持っている人全てに個別計画が立てられていくというわけではないですので、そういうところでは、個別計画が立てられない方々も含めた形で、要支援者、要援護者、それから情報弱者と言われるような方々が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"災害時の情報について、参考までに現状というか、教えていただきたいのですけれども、ドローンの導入が平成３０年で、昨年、強化をされたというところで、導入時から強化をされた、どういう強化を、操作できる人が増えたとか、また、その操作によってどういったところまで情報収集をできるようになったのかとか、そこら辺を教えていただきたいのが１点と、あと。","respondent":"平原防災体制整備担当課長","answer":"そういったところを並行させていただきながら、ドローンのパイロットの養成を併せて進めまして、現在、５名体制での運用ということになっております。災害時に区内を網羅する飛行計画なども立てさせていただいておりまして、俯瞰的な情報を取るという体制にしております。","id":"exchange-019"},{"speaker":"こんの委員","kind":"確認","question":"現状、分かりました。ドローンですけれども、本格運用がされて、悪天候でも大丈夫だという体制が取られているということがよく分かりました。次の質問ですけれども、平常時の情報収集ですが、その中の9)に書かれておりますしながわ防災学校のオンライン講座の開始について伺いたいのですが、これは、講座を受けられる、応募できる方の対象要件はあるのでしょうか。はその点を確認させてください。","respondent":"平原防災体制整備担当課長、山本防災課長","answer":"高層カメラについてですが、必要なところには増設するという考えの下で増設してまいりましたが、今後、費用対効果なども見ながら、必要なところがどういったところなのかという検討を進めさせていただきたいと思ってあります。一般コースにつきましては、区内の方で、基本的に興味のある方でしたら、どなたでも受講することができます。","id":"exchange-020","title":"町会・自治会支援"},{"speaker":"こんの委員","kind":"質問・要望","question":"より多くの方に受講していただきたい、ましてやオンラインですから、システムによって人数制限があるのかもしれないですけれど、対面式でやる講座の人数も、通常でやるのも少ないなといつも感じているところですが、オンラインで２０名というのはちょっと少ないので、これはどうしてそういう人数の設定になったのか、より多くの方に受講していただくという考え方の下。","respondent":"山本防災課長","answer":"こちら、２０名の定員というところですけれども、オンラインという特性を考えれば、幅広く、かなり多くの方に受講いただけるというところもあるのですが、内容によっては、一方的に講師が話すだけではなくて、双方向で意見等をやり取りするというところもありますので。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"対面式だったら場所が偏ってしまって１か所でというのも、それも区内で何か所かやっていただいて、品川区のより多くの方が講座を受けられたらいいのかなと、この講座に限らず思うところですけれども、オンラインでしたら、何回かに分けてやるという形、講師の方を確保するのが難しいというのも一方であるかもしれないですが、せっかくの講座なので。","respondent":"山本防災課長","answer":"やり方というところで、委員にご案内いただいたように、例えばオンライン、複数でやるというようなところも我々検討はしています。物によっては著作権等々ありますけれども、アーカイブで放送ができたり、そういったところも今検討しています。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"たけうち委員","kind":"確認","question":"すみません、今の件で、私の認識だと、ホームページ等に出ている土砂災害とか目黒川の氾濫とか、指定されている地域がありますよね。そこの地域の方は、一定のあれはあるでしょうけれども、全員対象だということでいいのですか。それとも、さっき、全区民に広がったというふうに私は受け止めてしまったのですけれども、そこをもう１回確認します。","respondent":"平原防災体制整備担当課長","answer":"ただ一方で、今、品川区のホームページからも登録が可能となっていますので、このエリアでない方もこれらの情報を受け取ることができるというふうになったというものです。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"意見","question":"分かりました。ホームページを見ていると、登録対象エリアとして、今、課長がおっしゃったような地域がホームページに出ているので。でも、できてしまうということなのですね。それを知っている方と知らない人とね。できるのだったら全部やってもいいのかななんて思ってしまったのですけれども、ホームページの表現の仕方を考えていただいたほうがいいかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025","title":"町会・自治会支援"}]},{"id":"topic-02","title":"令和３年度区内一斉防災訓練等の実施結果","agenda":"令和３年度区内一斉防災訓練等の実施結果","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"アンケートの集計結果ですけれども、集計結果は分かりましたという感じですよね。これが今後どのように現場というかそういうところにフィードバックされて、次の訓練に活かされるようになっているのか、その仕組みといいますか、その方法について伺いたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"各町会へのフィードバックについてのお尋ねです。こちらにつきましては、まず各地区総合防災訓練、区内一斉防災訓練共に、１月２８日に実施予定の地区防災協議会会長連絡会でお話をお伝えしていきたいと考えています。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"いろいろなところで報告されるということですので、やはり次に活かすとしたらよくなかったという方のご意見を主に活かされるのかなと思うのですけれども、そういうような協議というか、主催というかこういう訓練をされる方たちとのお互いの情報共有とか工夫の共有とか、そういうことはされていると思うのですが、そのように考えていいか伺いたいのですが、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"今回も、報告の中ではいいところを言うことが主ですけれども、今回はよくなかったという点に着目してご報告させていただいて、速報ではありますけれども、今の段階で何となく見えてきたものについて今日はご報告させていただきましたので、改善についてはまた今後検討した上で。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"訓練を主催された方だけの責任ではないと思うので、ぜひいろいろな場で協議しながら、ブラッシュアップというか、そういうものにアンケートが活かされるといいかなと思って伺いました。ぜひ今後も協議して、何かありましたらご報告いただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"訓練不参加者への対応の中で、オンライン形式の訓練とか促進を図るという記載がありましたけれども、これを実際にやったのか教えてほしいのと、あと、アンケートの中で、「人数制限なく、一般の人も参加すべき」が３１％で、密を回避してという部分で高い回答がある。そういった訓練のやり方とかを決めるのは、行政側なのか、避難所連絡協議会の中で委託している方が決めるのか、そこら辺を教えてください。","respondent":"五十嵐災害対策担当課長","answer":"訓練不参加者に対するオンライン、何かやったのかというところですけれども、実は先ほどの資料別紙１の「２ 区内一斉防災訓練以外の避難所訓練」の５つの区民避難所で訓練をやるという予定の中で。","id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"分かりました。オンラインに関しては、浅間台小学校、東海中学校、これからやる２校でお願いされているということですね。今後、全体のこういう防災訓練が引き続きあるときは、やはりオンラインを促すという形になるのか、それを確認したいのが１点と、訓練のあれは分かりました。正直、大変ではないですか。でも、逆にいうと、避難所は密になるということが明確に分かるわけではないですか。","respondent":"五十嵐災害対策担当課長","answer":"最後の簡易トイレの件についてですけれども、避難所運営訓練の中で簡易トイレの設置は付き物ですので、どういうふうに進めていくかというのは、コロナ対応マニュアルに基づく訓練を進めながら検討していきたいなと思います。","id":"exchange-030"},{"speaker":"松澤委員","kind":"意見","question":"コロナ対応マニュアル、確かにつくっていただいて、すごくしっかりしたものがありますけれども、やはり今後、こういった体験訓練とかつくる訓練というのは非常に大事だと思いますので、そういうものも含めて、また検討していただけるとありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問・要望","question":"別紙１の参加者数の参集職員のところですけれども、この参集職員の方は、実際に地震とかが起きたときにこの学校に参集する職員の方が来られたかどうかというのを分かれば教えていただきたいのと、あと、今、オンラインの話が出ましたけれど、浜川中学校ではＺＯＯＭにてと書いてあるので、オンラインでやられたのかと思うのですが、この内容は、生徒も随分参加されてのことで、町会が中学生に期待すること。","respondent":"五十嵐災害対策担当課長","answer":"参集職員についてのお尋ねです。参集職員については、大型の地震が発生した際に参集する職員に初めから１０名対応していただいております。実際に現場で町会の方々を避難者と見立てた対応訓練を一緒にやっていただいております。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"題名というか、考え方、テーマとして、中学生に期待すること、何ができるかということで、これについて、生徒とか町会の方とかが、ＺＯＯＭなのかリアルなのかは分からないですけれども、話合いをされて意見交換をしたということではないということですか。","respondent":"五十嵐災害対策担当課長","answer":"ＤＶＤの視聴が先ほど私がお話しした内容でございまして、今回、このＺＯＯＭによる、大地震に町会が中学生に期待すること、自分たち中学生に何ができるか検討するという部分につきましては、すみません、把握し切れていなかったものですから、再確認した上で。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問","question":"もともと昔から中学生が消火訓練をやった学校もありますし、そういう面で我々も、あまり過度な期待をしてはいけないですが、昼間なんかに災害が起きたときは、男手がなかったりするので、中学生、高校生とかというところにある程度お世話になる部分があるのかなという中で、どういうのが来たのかなと非常に興味深かったので、また何かありましたら、個別でも結構なので、教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-03","title":"令和３年度品川区地域防災計画の修正","agenda":"令和３年度品川区地域防災計画の修正","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"今まで二次避難所というと、例えばシルバーセンターだとか、地域センターもそうでしたか、そういうところだったような気がして、ご病気があるとか障害があるとかではなくて、ご高齢でちょっと普通の区民避難所では大変な方というイメージがあって、それで福祉避難所は、胃ろうが必要だとかかなり重い障害がおありになるとかというので、かなり幅が狭まっていたような気がしたのですけれども。","respondent":"山本防災課長","answer":"実際に発災したときは、その指定された避難所に避難していただくという変更にする予定です。","id":"exchange-035"},{"speaker":"たけうち委員","kind":"質問","question":"恐らく、そうなると、さっき、もともとの区の振り分けというか、イメージで、重い身体障害の方とか、高齢者でもちょっと胃ろうがある方というご病気がちの方は、同じ福祉避難所の中でも、特養だとか老健とか、どっちかというとそういうところ、それで、高齢者でご病気も特にそれほどなくてという方はシルバーセンターみたいな、必然的にそのようになっていくという理解でいいのかということと、あと。","respondent":"山本防災課長","answer":"支援する方、避難誘導される方をどうするかというところが一つ課題というふうに考えてございまして、一義的にはご家族にやっていただくというところが基本になるとは思いますけれども、その辺り、それ以外の地域の方をどう結びつけていくかというところを、今。","id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問・要望","question":"お願いとしてあるとすれば、例えば直接避難でも、福祉避難所と決めた場合でも、災害の状況によっては、一番近い学校に一旦行っていただいて、そこでちょっと落ち着いてから福祉避難所という、今までのケースもできるよということも、柔軟にやっていただいたほうが、あなたは最初から直接避難で、どこどこシルバーセンターになっているのだから、こっちに行っては駄目よみたいな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、こういう形で直接福祉避難所に行っていいのですよということになった場合、まだ計画を立てられていない方が福祉避難所に行ってもいいことになるのか、そこら辺の個別計画と今回の計画の変更というところの整合性というのですか、過渡期のそういう状況というのはどういうふうに対応するのか、その点をお聞かせください。","respondent":"山本防災課長","answer":"過渡期の対応ですが、基本的に福祉避難所はあらかじめ指定された方しか避難できないという形に今後なってまいりますが、当然、計画の作成が間に合わない方もいらっしゃるかもしれないところがありますので、そういったところは柔軟に対応していきたいと思ってあります。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、今年度、計画を組まれる方というのは３０人しかいないので、本当に僅かだと思うのですけれども、障害者の方からは、直接福祉避難所に避難したいというご要望を随分お聞きしているのですが、その方が、特にどこかに断るとかということもなく、自分がそういうときにはここに行きたいなと思っているところに取りあえず避難するという形で行ってしまっていいのか、その点が、現実問題。","respondent":"山本防災課長","answer":"課題ですが、やはり避難を支援される方の確保というところをどうしていくかというところで、福祉関係者だけではなかなか対応できない、ご家族だけでも対応できない場合があるというところになった場合、共助の力でどう対応していくかというところは一つ課題だと思ってあります。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"様々そういう課題が出てくると思いますし、また、では福祉避難所でその体制をどう取っていくのかというところも本当に課題が様々出てくると思うのですけれども、でも、実際に災害が起こったときは、それが実際の災害として様々出てくるので、そこの課題がある、その課題をどう克服していくのかというのがすごく自治体にも問われると思いますので、個別計画は５年間と言いながらも。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/170605?Template=document&Id=6608#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":36965,"voices":101}},{"id":"r04-20220120-10","meetingId":"r04-cm01","date":"2022年1月20日","dateIso":"2022-01-20","committee":"議会運営委員会","time":"午後 １時００分～午後 １時１６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5442#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":5438,"voices":23}},{"id":"r04-20220204-10","meetingId":"r04-cm02","date":"2022年2月4日","dateIso":"2022-02-04","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","topics":[{"id":"topic-01","title":"品川区新庁舎整備基本計画における議会機能に関する意見","agenda":"品川区新庁舎整備基本計画における議会機能に関する意見","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"今、ご説明がありましたとおり、議会の意見として取りまとめましたというご発言でした。「上層階への配置とする意見が多数を占めた」という表現であれば、事実の問題ですので、まとめに賛同できますけれども、「上層階の配置とする」という表現のまとめについては、改めて反対を申し上げたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"伺いたいのは、今年１０月から始まる窓口負担を１割から２割に引き上げるという件について、今回、報告や質疑はあったのかということを伺いたい。それと、保険料率の値上げですけれども、そうはいっても３,７８９円値上がりするということです。これは意見なのですけれども、先ほどの前段の質問についてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"窓口負担の増額で５０億円の削減を見込むということなのですけれども、医療にかかる人が逆に抑制されるということだと思うのです。品川区議会を代表して参加されているということですので、保険料の値下げ、あるいは窓口負担の軽減などについてもぜひ意見を述べていただきたいと、重ねて意見を申し上げします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"私の理解が足りなくて、少し説明していただきたいのですけれども、まず、このタイミングで、今の中身のことを議会運営委員会に報告をする理由がよく分からなくて、そこを伺いたい。この議案を審査しない、議会運営委員会で報告する位置づけがよく分からなかったので、ご説明いただきたい。議長名により意見の照会を行うというのはどのようなことなのかよく分からないので、ご説明いただけたらと思います。","respondent":"工藤区議会事務局長","answer":"なぜこちらのほうでというところは、次回の議会運営委員会で意見聴取した旨をお知らせするということがありますので、今日、事前にこの手続について説明したほうが分かりやすいということで、事前に頭出しをさせていただいたです。","id":"exchange-004"},{"speaker":"須貝委員","kind":"提案","question":"最近、不幸にも、区議会議員の皆様の中からコロナの陽性者の方が何件か出ております。何しろ議員同士、やはり我々は話すということが基本ですから、議会に安心して出席でき、いろいろな方と安心してお話しできるような環境を設定していただけないかと。どなたが感染したのかというのは必要ではないかなと思いましたので、今、提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"預けする前に一言。今、議長がおっしゃったことはまさにそのとおりで、厳格な基準に基づいて局長も判断され、我々に周知をしているということですので、議員だけといっても、名前云々は、やはり混乱の種になるような気がしてならないのです。なので、私はできれば現状の取扱いにしていただきたいなという希望だけ先に言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"提案","question":"参考までに、これからもいろいろな場面で状況が変わっていくとき、常に議論が必要だと思うのですが、須貝委員のご提案の中で、いい面は分かったのですが、デメリットは何か考えられますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"デメリットは、議員同士共有するとなると、例えば、私はメールに載せなくても、電話でも何でもいいと思うのですが、それが外へ情報が流れてしまうということを、やはり私はすごく危惧しています。漏れたら、その連絡経路で分かるような対応をして、その個人のお名前云々が外に出ないように工夫しなければいけないと私は考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの須貝委員のご要望というのは、名前を公表するということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"意見","question":"いわゆる名前を公表ですよね。どのような形であれ、秘密を守る工夫をする。これは公人だからという理由なのでしょう。ただ、公式見解では、先ほどあったとおり、濃厚接触者という判定がされれば、それは当然、連絡が行くようになっています。いい、悪いと、今、私は言うつもりはありませんけれども、いわゆるプライバシーの最たるものであるということは申し上げておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の意見と同じだなと思いました。それだけに、今、濃厚接触者の把握については、事務局が決められたルールに則って、本人に聞き取りをしているわけでありますので、それは本人から十分な聞き取りをして、必要な対応を行っていくという、その徹底が必要なわけで、名前の公表は行うべきではないと意見だけ述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"別に議論するつもりはないのですが、氏名を出すと言っても、先ほどから何度も申し上げていますけれども、議員間の中でという話ということと、それから、もう一点、前回、事務局から来た注意書きの中で、歯磨きをしないでくれと書いてあったのですが、どういう状況でマスクを外していたのか、どういう環境、状況で感染したと思われますということも私はもし教えていただけると、よりありがたい。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"せお委員","kind":"提案","question":"すみません。この場をお借りしまして、自民・無所属・子ども未来から１つ提案をさせていただきたいのです。皆様ご存じのとおり、コロナが爆発的に感染拡大していて、１月中も議員が、五、六名感染していたと思うのです。このオンライン開催に向けた議論をしていきたいと考えていますので、提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"芹澤委員","kind":"確認","question":"お話は分かりました。ＩＣＴ推進会議は、多分、議会日程とは別で、リーダーが会議を開く、開かない、議題とする、しないというのも含めて、一定の権限を持っていると思うのです。特にＩＣＴ推進会議は自・無の議員がリーダーをやっていらっしゃると思うのですけれども、会派内で、今回、ＩＣＴ推進会議ではやらずに、ある意味、議会運営委員会に差戻しみたいな議論があったということなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"せお委員","kind":"意見","question":"やらずにというか、一度、議論があって、多分、止まっていたと思います。その再開といったところを、結局、ＩＣＴ推進会議で議論したことが、最終的に議会運営委員会に来ると思うのです。早急に進めていくためにも、まず、議会運営委員会で承認ではないですけれども、検討していくかどうかということを最終的にまとめてもいいのかなと思ったのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"大沢委員","kind":"提案","question":"少し言葉足らずでいろいろ申し訳ありません。とりあえず、せお委員から、今、このような提案をさせていただきました。なので、ここでは、議論をするというよりも、少し場違いかもしれないのですけれども、このようなことでいかがでしょうかという提案です。議論していただくための提案ではないことを、ご承知おきいただきたい。そういう提案と捉えていただければ結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問・要望","question":"多分、皆様の思いはこの危機の中で一緒だと思うのです。ぜひＩＣＴ推進会議のリーダーに進めてくださいとお願いしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"確認","question":"コロナの不安はよく分かりますし、また、コロナ以外でも、議員にも様々な生活があって、その上で議会というものに参加するため、参加できるよう十分な保障をすることはとても大事なことだと思います。この間のＩＣＴ推進会議の話が先ほどありましたけれども、そこでもんでいただいて、何か結論が出たら議会運営委員会の場で報告していただいて確認をとるという、従来の進め方で良いかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"大沢委員","kind":"提案","question":"そのお言葉を頂ければ、もうここら辺でこのお話はやめたいと思います。それをご理解いただきたいと思います。こちらのほうで提案というか、投げかけておいて、議論を切るという形になるのですけれども、一応、提案ということで、今日、皆様のお話を頂けたということで、せお委員も十分満足していると思います。その辺のところでご理解賜りたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5444#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":11519,"voices":55}},{"id":"r04-20220216-10","meetingId":"r04-cm02","date":"2022年2月16日","dateIso":"2022-02-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5446#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":9218,"voices":26}},{"id":"r04-20220221-3","meetingId":"r04-c-budget","date":"2022年2月21日","dateIso":"2022-02-21","committee":"予算特別委員会","time":"午前１１時４７分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/396769?Template=document&Id=1142#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1860,"voices":18}},{"id":"r04-20220221-10","meetingId":"r04-cm02","date":"2022年2月21日","dateIso":"2022-02-21","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時０６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5448#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1672,"voices":13}},{"id":"r04-20220222-6","meetingId":"r04-cm02","date":"2022年2月22日","dateIso":"2022-02-22","committee":"区民委員会","time":"午前１０時００分～午前１１時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","topics":[{"id":"topic-01","title":"を行います。 令和３年特殊詐欺被害認知状況およびＡＩ型特殊詐欺対策アダプタの運用状況等","agenda":"を行います。 令和３年特殊詐欺被害認知状況およびＡＩ型特殊詐欺対策アダプタの運用状況等","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"主に２番の項目について伺っていきます。１番、特殊詐欺被害認知状況です。被害認知の推移についてお伺いします。ただ、令和２年から令和３年にかけて、また元の水準に戻った。この増減に関して、要因分析をお聞かせいただきたいのと、それは今私が申し上げたコロナの感染拡大状況で、在宅している機会が増えたということとは相関関係がなかったのでしょうか。その１点を伺います。","respondent":"森田生活安全担当課長","answer":"令和元年から令和２年にかけての被害の減少です。","id":"exchange-001"},{"speaker":"くにば委員","kind":"意見","question":"大変勉強になりました。それでもやはり状況が増加の一途をたどっているということに関して、これはもう都内だけではなく、全国的に還付金詐欺をとめる手だてがどうしても効かずにこれだけ増えてしまっている状況だと思いますが、令和４年に向けてどのような対策をしていく予定なのか、その１点をお聞かせください。","respondent":"森田生活安全担当課長","answer":"それにつきましても、私どもで広めていくというところと、あと今後対策につきましても、効果検証とかも図りながら、どんな対策が一番いいのかを考えながら、随時進めていきたいと考えています。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"続きまして２番、ＡＩ型特殊詐欺対策アダプタ運用状況等についてお伺いいたします。こちらに関しても、今年度の補助は本年１月１７日が期限で、１月２０日時点での記事だったのですけれども、この時点で、全国でほかに実施されている自治体を含めて、ＮＴＴ東日本・西日本を合わせて約２００人がこちらに加入しているとお聞きしました。もう１点が、課題という部分で、利用者の月額負担です。","respondent":"森田生活安全担当課長","answer":"当初５０台を予定しまして、先ほど説明したものは無料の貸出しを随時進めているところです。これも実際有効でございまして、電話がかかってこなくなったと、いろいろお話もいただいております。","id":"exchange-003"},{"speaker":"くにば委員","kind":"質問・要望","question":"ご丁寧なご説明、ありがとうございました。以前５０台をどういった方に配付を検討されるのかと伺ったところ、犯罪のリスクが高いと既にリストアップをしている方にお勧めしますということで、そういった方々でも適合する機種と適合しない機種があるということで、そこにハードルが１つある。もう一点質問します。警察へ直接連絡するという方式ができないのかどうか。その２点をお伺いします。","respondent":"森田生活安全担当課長","answer":"夜間等につきましては、現在品川区での対応につきましては、祝・日曜を除く午前８時から午後８時までを対象としています。","id":"exchange-004"},{"speaker":"くにば委員","kind":"質問・要望","question":"担当の方々がいらっしゃらない時間帯はどうするかという部分に関して、これはＮＴＴ東日本と交渉というか、課題の共通の認識にしていただきたい部分ですが、例えば、時間外はコールセンターなど、全国的にほかに導入されている自治体も含めて、１名、２名が夜間対応で電話が取れれば、品川区だけでは人件費の部分で厳しいと思いますけれども、ＮＴＴ東日本とうまく連動して、全国で１人。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２点質問させてもらいます。１番目の特殊詐欺被害認知状況で、都内は被害額６６億２,０００万円、区内の被害額が１億８,０００万円ということでした。２点目が、自動通話録音機ですか、無料貸出しをしており、青パトの方たちが常にサポートし、例えば、設置サポートもやっておられると思うのです。そういう設置サポートの実績というのは今までどのぐらいあるのですか。以上です。","respondent":"森田生活安全担当課長","answer":"そのほか青パトが設置をサポートしたのがどれぐらいなのかというお話ですが、青パトでの設置はまだ進めてはおりませんが、そういった質問も多くありますので、設置の方法とか、どこを窓口にしたらいいのかというのは、その都度説明させていただいたり、昨年ですと。","id":"exchange-006"},{"speaker":"横山委員","kind":"確認","question":"私に機器がちょうど回ってきた中でお話を聞き逃してしまっているのがあったのですけれども、注意喚起アラームの総数は１８件ということでよろしかったでしょうか。確認だけお願いします。今回こちらは品川区方式ということなのですが、他の自治体はどういう形でやっているのか、品川区と違う方式はどのようなものがあるのかが、もしお分かりになりましたら、教えていただけたらと思います。","respondent":"森田生活安全担当課長","answer":"これが逮捕につながったということの評価ですけれども、これにつきましては、設置の当初から警察署とのやり取りを進めておりまして、こういうことをやっていくよということと、もし、そういった通知が来た際には、必ず対応というか、うまくできるようにということで。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/277018?Template=document&Id=2920#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12951,"voices":25}},{"id":"r04-20220222-7","meetingId":"r04-cm02","date":"2022年2月22日","dateIso":"2022-02-22","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"石田秀男委員の代表質問の予算案・施政方針についての質問の中の福祉の質問で、八潮地域や小山台住宅跡地、あと元芝都営住宅跡地の施設について、特別養護老人ホームやグループホームなどを１００床ぐらい整備していくという、ちょっとよく聞き取れていなかったのですけれども、そういう答弁があったと思うのですが、今分かっているところでどんな計画になっているのかを聞かせていただけたらなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"第２１号議案、品川区立シルバーセンター条例の一部を改正する条例","agenda":"第２１号議案、品川区立シルバーセンター条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"北品川シルバーセンターを高齢者多世代交流支援施設、ゆうゆうプラザに建て替えていくということですが、このシルバーセンターは４８年経過しているということで、老朽化が進んでいることから建て替えるということですけれど、今、どれぐらいの平米数で、広くなるのかどうかというのと、あと階数なども今現在、何階で、それが何階建てになるのかというところを教えていただきたいです。","respondent":"菅野高齢者地域支援課長","answer":"現状の北品川シルバーセンターは２階建てで、延床面積が３７１.９平米です。それに対して、改築予定の北品川ゆうゆうプラザに関しましては、今のところ３階建てで、６３１.９平米を予定しておりますので、１.６倍の広さになる予定になっております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"高齢者クラブの会長の方にもお話を伺ったところ、高齢者クラブは１６０人ぐらい会員の方がいて、それで今はコロナ禍ですけれども、集えるようになったら、１つでも広い部屋があると、新年会や高齢者クラブ全体として集まるときというのに使えるのだけどということもおっしゃっていて、そういう設計になっていないということが口々に語られたのです。ですので、そこの設計というのは今現在どうなっているのか。","respondent":"菅野高齢者地域支援課長","answer":"ただ、こちらとしましては、現在の施設の利用状況や、他のゆうゆうプラザの部屋の大きさ等から検討して、ある程度の施設案をお示しさせていただいているところで、現状の使っている広間よりも狭くなるという設計には少なくともしておりませんので。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。少なくとも聞き取った状況の中ではそういう感じではなかったので、ぜひ、できてよかったなと思える施設をと思いますので、ここは、今までも丁寧に進めていただいていたと思うのですけれども、今後も丁寧に説明、そしてご理解と、あと要望も受け止めていただいて、反映させていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"消防団の小屋が壊れたときに、「あれ、もう解体が始まったのか」というような声があったのも事実で、これから７月というのはこういうふうに言えるのですけれども、それまでの、先ほどの利用の話から解体がどういうふうに進んでいくかという話は、そこの間の部分をもう一度教えていただきたいのと、ここは建て替えだということで、こういうふうに書いてあるのだけれども。","respondent":"菅野高齢者地域支援課長","answer":"今後の説明会等の予定については、令和４年の７月から工事は始まるというところですので、その前に、工事説明会を近隣の方および利用者の方にご説明をしていきたいと考えています。","id":"exchange-005"},{"speaker":"若林委員","kind":"質問・要望","question":"７月から解体ということで、今のシルバーセンターの、特に地下、ここはいわゆる埋立地かどうかというのはまたいろいろ歴史をさかのぼると、いや、御殿山までだとか、いろいろありますけれども、それも含めて、海に近いということで、地盤が決して、いわゆる盤石ということでもないのかなというところからして、地下はどうなっているのか。しっかりやっていただきたいという思いで、確認だけさせてください。","respondent":"菅野高齢者地域支援課長","answer":"そこの中で説明会をしてという形になっていくと思いますので、その際に、やはりいろいろと工事車両のことだとか、具体的に騒音のこととか、いろいろと近隣の方からご不安の声等が出てくると思いますので、そういった声を踏まえて、業者としっかりと連携を取って。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問・要望","question":"最初のボタンのかけ違いが、後々ずっと尾を引いていくというのが、こういう解体・改築のパターンです。私の思いとしては、最初、本当に丁寧に、丁寧に、分かりやすく尽くして、尽くしていただいて、決して、いや、最初に説明は聞いていないよとか、最初の説明から途中で、工事ですから、地下に何があるか分からない、どういう状況になっているか分からない、致し方なく工事内容を変更する。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"先ほどの、現状より狭くなることはないということなのですけれども、現状の一番広い部屋が何平米ぐらいあって、今回、新たにできるところでは何平米ぐらいになるのか、最大で入れる場所が何人くらいの定数になるのか、伺いたいと思います。ほかの施設だと、ゆうゆうプラザでも大きいところは八十何人とかが入れる状況であると思うのですけれども、そういうところと比べてどうなのか、伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"お部屋のことなのですけれども、現状、一番広いお部屋が約７８.５平米ということで、８０平米弱のお部屋が広間としてありまして、皆さんに一番ご利用いただいているのかなというところで、私も何回かそこに説明会でお邪魔させていただきました。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで、地域の方がたくさん集えるように、特にここは１６０人も組織化されているというところでは、高齢者クラブも活発にされているのかなと思うのですけれども、そういうところは本当に大事にしていただいて、地域の高齢者クラブの方々のご要望に沿えるような形で、たくさんの方が集えるような方向でぜひご検討いただきたいと要望させていただきたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"コロナが終息した後の定数等につきましては、現在、実施設計がまだ仕上がっていない段階ですので、はっきりしたお約束はできないところなのですけれども、大体、他の施設を見ると、１人当たり１.４平米とか１.５平米で確保していますので。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"６０人弱というのは少し少ないのではないかという気がするのですよね。６０人というのは少ないのではないかという思いがします。これからもまだ検討する余地というのはあるのでしょうか。もし検討する余地があるのであれば、新しく造るのに、これは小さいのではないかなという思いがするので、ぜひご検討いただきたいと思うのですけれども、最後に、その点をお願いします。","respondent":"菅野高齢者地域支援課長","answer":"ただ、パーテーションで仕切ることによって、ふだんの活動の中で、やはり音漏れがするだとか、いろいろとデメリットもある部分もありますので、限られた建物の中で、いろいろな方のニーズを酌み取って、工夫して設計しておりますので、その辺りのところは。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう意味でいうと、そういう施設ができて、そういうクレームがない地域は、大変感謝をしていますというような形で、その事業者の方々が地域に逆に溶け込んでくださっている、そういう地域なので、ここは区が行うところですので、近隣の方々もそういう方が多いし、利用者の方も溶け込んでいる方が多いので、そういうクレームが来るのは非常に少ないとは思うけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-03","title":"令和４年陳情第７号、補聴器助成金制度に求める陳情","agenda":"令和４年陳情第７号、補聴器助成金制度に求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この補聴器購入費助成制度をという陳情、今回で６回目ぐらいになってくると思うのです。本当に何度も出されて、強い要望だなと私たちも思っていますので、ぜひ検討していただきたいなと私も思うのですけれども、昨年の３月に、自治体における難聴高齢者の社会参加等に向けた適切な補聴器利用とその効果に関する研究というのが厚生労働省でされたのです。この厚生労働省の調査に、品川区は答えられたのか。","respondent":"寺嶋福祉計画課長","answer":"アンケート調査につきましては、日々、多方面からたくさんのアンケート調査が来ておりますので、申し訳ございません、一件一件全て記憶しているというわけではなく、調べれば分かるのですけれども、回答する必要があるものについては。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"１つ目が、難聴を早期発見する仕組みを自治体が構築すること。ですので、そういったところから見ても、こうした提言、本当によく出てくれたなと私も思っているのですけれども、これらについてどのように区としては考えられているでしょうか。要は、自治体としてこれが必要だというふうに提言がされているのですけれども、これに関して、区としてはどのように捉えられているでしょうか。","respondent":"寺嶋福祉計画課長","answer":"それで、医療の専門的な分野でもありますので、実際としてどこまでできるかというところはありますけれども、例えば先ほど申し上げた普及啓発につきましても、専門機関からそういった啓発用のパンフレットを積極的に配布してほしいとか、こういう声があれば。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、どのように捉えられているのかと伺ったのですけれども、やはりこの一つひとつの提言を実行していこうとすると、確かに医師会の協力だったり、補聴器相談医、また認定補聴器技能者、こうした方の力も借りなければいけなくなると思うので、そうした提言として、どう捉えられているのかというのをもう一度伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"そうではなくて、先ほど申し上げたとおり、品川区は品川区のスタイルとして、あらゆる相談を身近なところで受けられるようにということで、そういった声をしっかり受け止めて、それを医療連携等でしっかりつないでいくというのが、これまで品川区がやってきた取り組みです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"でも、その方はやはりそこまで認知症が進むまで相談できなかったということですね。令和２年度の実績は７４９件あったのです。他自治体では助成制度を実施することで、普及啓発、補聴器の使用へとつなげていって、要は介護予防、そしてＱＯＬの低下を防ぐという、こうした状況をつくっているので、これを見ても補聴器購入への助成制度は今こそ進めるべきではないかなと思うのですけれども、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"実施している自治体の有無につきましては、これは自治体ごとの判断、優先順位等、諸々の事情があろうかと思いますので、現在の品川区としては、今は情報収集、研究というところでこの問題をしっかり捉えていくという認識です。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"情報収集等も必要ですけれども、情報収集と、ずっと答弁で言われているのですけれども、もう必要な情報は結構そろっているのではないかと思うのです。は品川区内でどれだけの難聴高齢者がいるのかを把握していく、そして補聴器の早期利用をどう進めていくのか、介護予防やＱＯＬの向上に向けてどう進めていくのかというのが問われていると思いますので、ぜひ積極的に、早急に進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それなので、ここのところに対してきちんと把握することが必要だと言われているわけなので、これは区の認識も変えていただかないといけないのかなと思うのですけれども、本人が気づかないうちに進行し、周囲も難聴であることが分からず、適切な受診や支援につながらない、このことに関しての認識について、改めて伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"前回の請願・陳情審査等でこの件を説明させていただいたときと今回で何が大きく違っていたかといいますと、まさに今、副委員長からご説明があった、こういった提言がなされたこと。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、今回こういう形で厚生労働省から明確な提言というのが出されたことによって、区としても、難聴者を早期発見する仕組みを構築するですとか、それから、補聴器を利用するための相談や認定補聴器技能者の周知、こういうところも区として取り組んでいくというところで検討していくということで捉えてよろしいでしょうか。","respondent":"寺嶋福祉計画課長","answer":"先ほどと同じ答弁になるのですけれども、まさにこの情報が入ってきた直近ですので、これを踏まえて、行政として今後どういうことをやっていく必要があるかということは、まさにこれからの検討課題ということになってくるかと思います。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは初めて請願が出されたときは２０１９年でしたけれども、このときは８区でした。そういう形で、ぜひ補助制度をつくることによってこのルートに乗せて、そして補聴器が有効に活用できるというふうなところにつながるという点でも、私はぜひ補助制度をつくっていただきたいと思うのですけれども、そのルートに乗せるという点での補助制度という点ではいかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"当然一定程度の財源を投入することになりますので、しっかりとした使い方がなされて、それで何よりも、いい生活をしていただきたいというのが一番の思いですので、根底は全く変わっていないのですけれども、順番としては。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ほかのどの区でもそういう縛りにしています。そういうふうなところになるわけですから、その先生のところに必ずかかって、自分が補聴器の購入のところに行って購入して、専門ではないところで購入して、結局使い勝手が悪いので使われなかったというルートが問題になるのではないかと思うのです。そこのところはもう一回お願いしたいと思うのですが。","respondent":"寺嶋福祉計画課長","answer":"そういった中で、今、副委員長がおっしゃっていたように、恐らくこの補聴器を有効に使うのであれば、きちんとした専門医の診察・診断等があった上で、その方に合った補聴器を選んで、しかも正しい使い方をしっかり継続してサポートしてもらうということ、これがまず重要な。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで、ぜひそのルートに乗るというところでも、私は補助制度というのはとても有効な仕組みだと思いますので、そういう点からも、ぜひ補助制度をつくっていただきたいと思います。私は、品川区が踏み出せば、そういう仕組みというのは、この品川区では環境として十分つくっていくことができるのではないかと思うのですけれども、いかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"ただ、そういう場では、もちろんそういうお話があれば、当然そういう機会はありますので、意見交換できることは当然あり得ることだとは思っております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"補聴器の請願・陳情の中でも私は何回かご紹介したと思うのですけれども、連続で３回ぐらい医師会の先生方から要望を受けまして、その要望というのは品川区にも同様に上がっている要望だと思うのです。区には当然そのことは届いていると思うので、そういうところで医師会の先生方も求めているということを、改めて申し上げておきたいと思います。","respondent":"寺嶋福祉計画課長","answer":"品川区は品川区ならではの、今までの取組の積み上げもありますので、こういった中で、また１ついい形が何かできればということで、引き続きしっかり研究してまいりたいと思います。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この包括補助制度は、半分を東京都が出すということになっているわけですから、私はぜひこの補助制度も使いながら、品川区としても助成制度を検討していただきたいと思います。そういう中で、品川区はいつまでも助成制度はつくらないということで、検討もしないというふうなことでいくのか。東京都もこういう形で包括補助も出すと言っている中で、検討もしないのか、改めて再度、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"当然、選択事業につきましては、全ての自治体が全部の事業を選択しているわけではなくて、まさに選択をして、その自治体として取り組んでいるもので、先ほど申し上げたとおり、補助制度があるからやっていくとかいうことではなくて。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"補助制度がこれだけ広がってきている中で、国も東京都もこのことに対して対策を取ることが高齢者のＱＯＬを本当に大きく改善させ、また、認知症予防の最大の効果にもなるということで様々研究をされて、そしてこういうデータも出されて、ここまでの提言がなされているわけですから、ぜひ補助制度を創設していただくようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我が会派は、補聴器の助成ということは、以前、補聴器を利用している会派のメンバーがいたということもありまして、１０年以上前から会派の政策要望に出させていただいていたという経緯があります。その中で、今お話があったように、我々も調査をする中で、利用実態が非常に低いというような状況の中で、本当にそれでいいのかというような議論も当時あって、会派の政策要望からは外したという経緯があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"若林委員","kind":"提案","question":"結論を出すでお願いいたします。そういった中で、この陳情は助成制度をというところで、助成制度ありきの陳情なのですけれども、２３区の中でも広がっているという議論もありました。それに対しても私たちの提案等があれば、積極的にさせていただきたいなというのが今の会派としての立場だと申し上げて、したがって不採択で結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"せお委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。要は質のよくないものを購入したり、医療機関を必ず受診していただくというところを、注意喚起だったり普及啓発、そういったところは今後、区のほうでもできるのかなとは思っていますので、私としては、やっと国が動いてくれたかと思っているので、そういったできるところはしっかり取り組んでいただきたいなとは、そこは要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"使わない理由のところでは、やはり相談医だったり調整する機関がないというところがあるので、まずは普及というのであれば、購入できるように、そして先ほども議論に出ていたように、助成制度を進めることで、医療機関にかかり、専門家の診断を経て、そして認定補聴器技能者のアフターフォローというふうにつながっていくと思いますので、やはり助成制度を進めることが普及啓発につながると思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"木村委員","kind":"意見","question":"結論を出すということで、採択でお願いします。我々もどんどん年を取っていくわけでありますけれども、高齢者が本当にそういう意味で健康を保っていくために、やはり耳や目というものは大変大事になってくるものと私は思っています。よって、これには賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すということです。今、これまでのご説明を担当の方に伺いました。納得はいたしました。それで、不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"令和４年陳情第１２号、高齢者が健康づくりと生きがいづくりに集える入浴設備のあるシルバーセンターを八潮に整備するよう求める陳情","agenda":"令和４年陳情第１２号、高齢者が健康づくりと生きがいづくりに集える入浴設備のあるシルバーセンターを八潮に整備するよう求める陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もう令和３年度の予算においてということですので、出ているものだと思うのですけれども、この増改築の基本計画必要経費等の中に、このシルバーセンター入浴設備について、それがあるのかどうかというのと、こういう大規模な改修に合わせて必要な機能・設備について検討していくとあるので、ぜひこういう機会にやはり検討していくべきではないかと、この間も言わせていただいているのですけれども。","respondent":"寺嶋福祉計画課長","answer":"したがいまして、本年度、基本計画の中で決められるところは、グラウンド部分に一体どれぐらいの規模のものが建てられるのかとか、定員が実際に想定の１.５倍程度と申し上げたこともあると思うのですけれども、そのぐらいで収まるのか、そこまでいくのかどうかといった。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今のお話を伺うと、ここにつくっていただきたいなという、ここに機能を入れていただきたいなという思いでいっぱいになりましたけれども、やはり特別養護老人ホームというニーズのところもありますけれども、この八潮の地域では高齢化率が３５％を超えているというところでも、求められている施設だと思います。過去から。","respondent":"菅野高齢者地域支援課長","answer":"しかしながら、入浴施設をつくることの費用対効果とか、あとは八潮南特別養護老人ホームの、今お話が出た改修計画、あとは今後、八潮のまちづくり検討なども始まるという話もありますので、そういった様々な要素がある中で、そのタイミングを考えていくべきであるため。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"大体のシルバーセンターに入浴施設はついていると思うのですけれども、どうしてシルバーセンターに入浴施設というのはついているのか、その大本の根拠を伺いたいのですが。","respondent":"菅野高齢者地域支援課長","answer":"八潮については、ほかの地域とまた違う地域の特筆するところがあるというところなので、その辺りも踏まえて、今後については検討していくべきだと捉えております。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで今、八潮のまちづくりという中でも大きく考えていきたいとありましたけれども、その話もずっと答弁の中では出されているのですけれども、具体的にそうした検討が始まるというのはいつになるのか、伺いたいと思います。","respondent":"菅野高齢者地域支援課長","answer":"やはり入居から４０年が経つ八潮において、高齢化の進行とか施設の老朽化など、様々な課題が出ておりますので、八潮の特徴を生かした魅力あるまちづくりを進めるために、令和４年度に新しく組織を設置するという話が出ておりますので、その中でまた。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そのところでいえば、ここに計画をするということであれば、可能かどうかということで、区が地域のニーズを踏まえた上でつくるということで決定すれば、施設の規模だったりとか、そういうところからすると可能かどうかという点では、可能だと考えていいでしょうか。","respondent":"寺嶋福祉計画課長","answer":"丸かバツかということになると、この段階でお答えするのは非常に難しいところがありまして、というのは、まずいわゆる行政需要といったところの視点からいえば、そうはいっても限られたスペースなので。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点では、内陸部のほうにはきちんと銭湯もあり、行こうと思えばシルバセンター、ゆうゆうプラザもあるという、そういうふうなところが八潮にはないわけですから、しかも高齢化率が急速に高まっているという状況の中で、単なる八潮の高齢者の人口だけで見るのではなくて、地理的なことも踏まえて、ぜひ入浴施設のあるゆうゆうプラザということにこれからはなっていくと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出すでお願いしたいと思います。先ほど３か所の話も出てきたけれども、やはりそういう意味では、行政需要をしっかりとらまえて考えていっていただきたいと思っているし、先ほど来の説明であったように、全体を捉えた中で、大規模改修の中でこうやっていこうと今お考えになっているということには私も大変理解できますので、そこら辺のところもしっかり踏まえていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"若林委員","kind":"質問・要望","question":"これまでどおり、来年度も八潮のまちづくり、将来像についてのまた具体的な前進もあるとお聞きしておりますし、高齢者、子育て世代も含めた総合的なまちづくりを進める中で、地元の方が中心になって議論して、どのような施設、まちづくりを進めていくか、しっかりやっていただきたいということで、一貫して私どもは変わりませんので、この陳情に関しては、引き続き不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。先ほどからも、以前にもお話があると思うのですけれども、八潮全体のまちづくりとして、入浴設備のあるシルバーセンターという、そういうピンポイントではなく、八潮全体を総合的に考えたところで、今後検討していっていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。ですので、そういった面から見ても、高齢者の皆さん、この陳情を出されている会の皆さんも自らアンケート調査もしながら、お風呂のそういった施設の要望は多いというふうに把握もされているわけですので、そういった観点からも求められていると。そしてこういう増改築の機会があって、可能性もあると思いますので、ぜひそこの検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ご説明をいただいたところで、理由については理解いたしましたので、先ほど来あるように、今後様々な検討をしていくというお話ですが、別の委員の方もおっしゃっていましたけれども、入浴設備のあるシルバーセンターという１つの項目ではなく、高齢者の健康づくりとか、シルバーセンターの本来のあり方、それから入浴設備のあり方、そして八潮のまちのあり方、様々な項のある方程式といいますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-05","title":"第３２号議案、東京都後期高齢者医療広域連合規約の変更","agenda":"第３２号議案、東京都後期高齢者医療広域連合規約の変更","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この第３２号議案の資料の１の変更内容のところの、関係区市町村の一般財源から保険料の軽減のために負担を求める経費のこの５項目、これは５項目トータルで幾らなのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"トータルですけれども、保険料の最終案では、市区町村の負担額２年分といたしまして、合計でおよそ２２４億円を想定しています。品川区の想定ですけれども、５億１,１００万円ほどを見込んでいるところです。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、品川区が出す分というか、経費としては５億１,１００万円、これは２年間で半分ずつ入れていくという感じの経費になるのですか。そこを伺いたいのと、後期高齢者保険料は２年分ですよね。ですので、この経費も２年ごとに半分ずつ、区が出していくという形になるのかというのをお願いします。","respondent":"池田国保医療年金課長","answer":"今申し上げました５億１,１００万円につきましては、２年間分ということで、これを半分ずつにしたものが毎年の支払いということで考えているところです。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。それで、広域連合のほうの資料にはあったので、それは入手したのですけれども、広域連合から取った資料では、平成２８・２９年度の保険料、平成３０・令和元年度の保険料ということで経年的に見れるので比較ができるのですけれども、この資料はぜひ出していただきたいなという。毎回出していただいていたのですけれども、それが今回出ない理由というのは何かあるのでしょうか。","respondent":"池田国保医療年金課長","answer":"今、ご指摘のございました保険料の最終案と過去の保険料の比較表ですけれども、今回も比較表というのを、実際のところは広域連合のホームページに出ているところなのですけれども、こちらの公表の時期と私どもの議会の日程が、広域連合議会が１１月３０日に開かれまして。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"確認","question":"前回は１１.４１％だったと思うのですけれども、それが上がっただけで、この２,８５６円の値上げになるという、そういう見方でいいのですか。２の横に長いグラフで出ているこの赤い部分、２,８５６円という部分は、後期高齢者負担率の、前回１１.４１％だったものが１１.７２％に上がった０.３１ポイント分ということでいいのですかということの確認をお願いします。","respondent":"池田国保医療年金課長","answer":"後期高齢者負担率というものは、後期高齢者の医療費については、ご本人が負担する３割分、１割分というのを除いたものを、そのうちの９割を公費、それと現役世代の後期高齢者支援金というような形でやっていまして。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、その負担率なのですけれども、「厚生労働省通知により」と（３）に書いてあります。ですので、もともと１割というふうにしていたのに、上がり続けていくというのは、厚生労働省がどういう根拠、計算の下に負担割合を増やすのか、どこまで負担率を上げていくのかという、そういう上限というのはあるのか。毎回上がり続けていっていいものなのかと思うのですけれども、そこを伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"逆に現役世代のほうが人数が減っているということで、後期高齢者支援金ということで、国民健康保険の中にもありますけれども、そういった形で、現役世代の方が減っているところで、現役世代の負担が毎年多くなってまいりますので、現役世代の方の負担を減らすために。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは上限がないと、本当に際限なく上がっていくということになってしまうのかなということで、心配だなと思って伺ったのですけれども、分からないということです。それで、次に行きますけれども、（５）のところで、所得の伸び率でマイナス１.２０％となっているのですけれども、これはどういう。マイナス１.２０％と推計というふうにあるのですけれども、ここの説明をお願いします。","respondent":"池田国保医療年金課長","answer":"３の設定条件の（５）の所得の伸び率ということでのご質問だと思いますけれども、こちらのほうは、実際にコロナウイルス感染症の影響がありまして、後期高齢者の方で働いている方がお辞めになったりとか、もしくは高齢のために控えたりということで。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、７５歳以上の後期高齢者の方が、収入がないので働かざるを得ない状況もあるのではないかと思うのですけれども、７５歳以上の方の働いている割合がどれくらいあるのか、分かれば教えていただきたいのと、それと、続いて（９）のところの賦課限度額を６６万円に値上げするという、この対象は何人ぐらいになるのかというのを伺いたいのですが。","respondent":"池田国保医療年金課長","answer":"この方が６６万円になったときにどのぐらいかということになりますと、それほどの影響はないかと考えています。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"７５歳以上で働かれている方は把握されていないということですけれども、やはり年金も減らされて、働かざるを得ないという方も少なくないと思います。しかも年収２００万円の方で２割負担になるというところでは、本当に追い詰められる状況が出てくるのではないかと思いますので、ぜひ一般財源を投入して、保険料の引下げこそしていただきたいと思うのですけれども、最後にいかがでしょうか。","respondent":"池田国保医療年金課長","answer":"私どものほうも、財源の投入につきましては、こちらの保険につきましては、品川区独自ではなく東京都全部でやってありますので、その中で負担がかからないようなことでは、当然特別区長会を通じて広域連合に要望を出しますけれども、こういった施策につきましては。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"特例軽減は令和３年度で全面的になくなったと思うのですけれども、もともと一番初めに始まったときにはかなりの特例軽減がされていたわけです。その特例軽減をされていた分というのは、どこが負担をしていて、その特例軽減がなくなったことによって、全部保険料で入ることになったわけなので、そこはどこがどれくらい増えることになったのか、その点について伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"副委員長のお話があったように、被扶養者の軽減額につきましては、令和元年からおよそ１,４００万円ぐらい減っているところではあります。これが品川区の分では１,４００万円ほど減っているというふうな現状です。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、品川区分が１,４００万円で、東京都はその３倍と考えていいということでしょうか。それは一般財源ということでいいのでしょうか。もしそういう形で、一般財源ということで保険料が入ってくるということになったのであれば、それはただ一般財源が増やされたという形で終わってしまっているのか、それがどこかにどういう形で使われるとかという考え方は全くないのか、その点についても伺います。","respondent":"池田国保医療年金課長","answer":"こちらのほうの保険料軽減の部分につきましては、ここの部分は７割７分５厘から、今、本則の７割になったというところでございまして、実際にまだ７割というものはありますので、ここが７割になって、なおかつこの方といいますか、後期高齢者医療制度に加入されている方で７割。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それが本当に少し制度が経過する中で、全面的に特例軽減をなくすという措置を取ったわけですから、私はそれは本当にもともと大問題になった冷たい制度そのものになったのかなと思っているわけなのですけれども、そこで浮いたお金というのは、やはり保険料軽減に使うべきだし、これだけ後期高齢者の医療保険料が毎年値上げという状況の中で、先ほど石田ちひろ委員も言ったように。","respondent":"池田国保医療年金課長","answer":"後期高齢者医療制度の保険料につきましては、全都的に決めていくところでございまして、私どもが決めるわけではなく、東京都の広域連合のほうで決めるところでございまして、ただ、それだけではなく、私ども２３区、もしくはほかの市町村からは。","id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"意見","question":"令和４・５年度の保険料率のところでは値上げすべきでないと主張させていただきましたけれども、この第３２号議案は軽減対策に必要な経費のための議案ですので、この議案には賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]},{"id":"topic-06","title":"第３４号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第３４号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"広域化になったわけですが、東京都が各区や市に額を、要は納付金を示されるわけだと思うのですけれども、この特別区の納付金総額は、３ページのところに２,１２０億円とありますけれども、品川区が納める納付金総額は幾らになるのかというのを伺いたいのと、それでそこにやはり国や都も広域化になることで支援金といいますか、交付金といいますか、出しますよということにしていたと思うのですけれども。","respondent":"池田国保医療年金課長","answer":"確定金額に基づく納付金額ですけれども、品川区の納付金につきましては、医療分が、およそで申し訳ございません、約８７億円、後期高齢者支援金分が約２４億８,０００万円、介護納付金が約１１億５,０００万円で。","id":"exchange-054"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"だから品川区に１.９億円ではないと思うので、要するに入れるよと言っていた支援金が、前回は入らなかったし、今回は本当に無理な状況だということで、本当に保険料引き下げのために都にも力を尽くしていただきたいなというのは要望していただきたい。そして国にも言ってもらいたいということで額を伺ったのです。だけれども、今回もコロナは続いているのに、令和４年度は９７.３％として算定していると。","respondent":"池田国保医療年金課長","answer":"ただ、これは今年限りのものでございまして、来年の保険料については、また検討するという形になりまして、最終的に令和６年に１００％になるのか、それとも令和７年に持ち越すのかということは、今後の景気状態によって変わってくるかと思っているところでございました。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"だからこそ均等割はなくすべきだと私たちは求めてきましたので、これが軽減されるというのは本当に大きないいことだと思うのですけれども、国民健康保険事業の運営に関する協議会のときにはこれが大きな表になって、それで均等割が５割減額される前の均等割と、減額されたときの均等割、そしてそれがそれぞれ７割軽減されている方、５割軽減されている方、２割軽減されている方、減額なしの方が。","respondent":"池田国保医療年金課長","answer":"未就学児の均等割についての説明が不足だです。Ａ３の資料の一番上の部分の(３)のところに、令和４年度の案というところで、７割減額になっている、この６,３１５円、５割減額と、こちらのほうで表示させていただいたところです。","id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"減額なしの方も人数を教えていただきたいのと、あと先に進めたいのですけれども、今回、均等割は、９ページのところで見ると、上から４行目ぐらいですか、品川区保険料率等のところの均等割額が上げられたのですね。前回、令和３年度からは３,３００円ですか。前回ようやく少しだけ均等割額が下がったなと思ったのですけれども、今回、均等割額が上がった理由というのは何なのか、教えてください。","respondent":"池田国保医療年金課長","answer":"申し訳ございません。減額のない方のお子さんの数は７７９人になります。次に、保険料の部分で、均等割がなぜ３,３００円上がったかですけれども、こちらは、先ほど保険料のご説明をしたときに、賦課額が出たかと思います。","id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この国民健康保険料の数字を伺っているのは、やはり下げられるべきものなので、下げていただきたいということでいろいろ伺っているのですけれども、やはりそこには一般財源の繰入れをさらに増やしていただきたいと思いますが、この間、法定外繰入をずっと減らすという、そしてそれを解消するというのが国民健康保険の広域化の目的ですけれども、令和４年度の予算を見ると、法定外繰入が１２億円で。","respondent":"池田国保医療年金課長","answer":"実際には基礎分、後期高齢者支援金分、それから介護保険分を合わせた形ではおよそ９４％の激変緩和率という形になっていますので、その分、多めに見ての額ということもありますし、また、ただいまの未就学児の保険料の減額分、これも含めて、法定外の部分というのが。","id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりこの間というか、広域化が始まる前は３０億円程度、法定外繰入れで入れていっていたわけです。それがどんどん減らされていっているわけですので、それが保険料に行っているわけですので、今までどおりの税金投入をしていけば、保険料というのは上げずに済むものだと思います。あらゆる努力をして、保険料の大幅値上げを抑えていただきたいなと。ぜひ引下げをお願いしたいと思います。","respondent":"池田国保医療年金課長","answer":"先ほどの都からの交付金というような形で頂いているのが、交付金という形では、医療費とかを全部含めてですけれども、令和３年度の予算では２１６億７,５００万円ということで、令和４年度につきましては、これからご審議いただくところではありますけれども。","id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは品川区に来るのが２１０億円ではないということですよね。全体でですか。お願いします。","respondent":"池田国保医療年金課長","answer":"これは医療費とかを全部含めた形の額でございまして、恐らくおっしゃっているのが、都の繰入れ、繰上げ、２号分とかの純粋たる成績分の額ということではないですよね。そこだけ確認させてください。","id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"確認","question":"広域化になったときに、国も都も支援金という形で、財政支援ですよね。それで入れると言っていた分というのが、東京都は全体で１.９億円ですよね。国は２１０億円で、いろいろ含めてという言い方をされたのですけれども、国民健康保険への支援金として入ってくるのは２３区全体で２１０億円ということですか。最後、確認だけお願いします。","respondent":"池田国保医療年金課長","answer":"納付金額の算定につきまして、国・都からの交付金ですけれども、都全体に入ってくるお金は３,５２３億円が入ってくる予定になっていまして、あと前期高齢者の交付金として２,３４６億円が入ってまいります。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それで未就学児の均等割額の軽減についても、一覧表になって、トータルで幾ら払うのかということも出ていますし、こちらの均等割のほうのもともとの分も幾ら減額された結果、幾ら払いますよというのも出ていたりするので、この数字は資料として、国民健康保険事業の運営に関する協議会の資料そのものを厚生委員会にも示していただけないかなと思うのですけれども、その点、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"もう一つ、資料につきましても、今回は１ページの部分でかなり細かく書いてありますので、国民健康保険事業の運営に関する協議会の資料とほぼ同じような資料をつけさせていただいて、除いている部分というのは、明後日にご説明するための資料の部分が抜かれているのと。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１ページの表のことですけれども、条例上はそういうふうになるということで、こういう記載でしかないということは分かりました。今回、初めて子どもの軽減制度というのはできたわけです。そういうときに、７割減額の場合は、それで、半分の７割減額ということになるので、ああ、これぐらいになるのだなというところを一々計算しないと見えにくいではないですか。","respondent":"池田国保医療年金課長","answer":"こちらの６,７２４円、保険料が上がるですけれども、こちらは、実は品川区の、今加入されている方の所得を出しまして、その中で計算をしたところでございまして、今現在で加入している方の所得から所得割率９.４４％を掛けて、均等割率の新しいものを掛けた場合に。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、所得割率は下がっていますよね。だけれども値上げになるということは、それを超えて収入が増えているということで考えていいということなのでしょうか。国民健康保険加入世帯の１人当たりの収入が、所得割率は下がっているにもかかわらず、それを超えて収入が増えているという、そういうことで、均等割額は３,３００円の値上げなのに、平均で６,７２４円になるという、その考え方ですが。","respondent":"池田国保医療年金課長","answer":"（国民健康保険に）入っている方の今年の収入が、昨年よりも入っている方が上がっているとご理解いただければと思います。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしましたら、例えば１人当たりの収入ですとか所得とか、その平均が幾らみたいなことというのは出ている部分があるのでしょうか。それは去年と比べて今年が幾らになるのかというのが分かる数字があったら、教えていただけますでしょうか。","respondent":"池田国保医療年金課長","answer":"特にこちらのほうは、算定した時点でいつの時点かというのが、大変申し訳ないのですけれども、私個人としてはまだ判明していませんけれども、こちらについては調べまして、次回、報告します。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どちらにしても、国民健康保険は減免制度を受けている人が半分ぐらいいるという、そういうところで、所得の少ない人が、そうはいっても入っているのが多くを占めるわけですから、そういう点では、先ほども石田ちひろ委員も言いましたように、高過ぎる国民健康保険料の引下げというところでは、いろいろなところで、特別区長会などでも要望を出したりとかもしているということですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"石田（秀）委員","kind":"意見","question":"けれども、今回、これは産業経済費の審査のところでやるかどうかは別として、社会保険が会社の負担金を留保した、それで２年間留保した、それで中堅企業の人たちに、これは国に相当、中堅企業から言っているけれども、今のところ４月から両方返してくれと言っている。４月からは普通に支払う部分と、２年間留保した部分を上乗せして返してくれとやっている。こういう機会だから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"反対です。意見を述べさせていただきたいのですが、社会保障は改悪の一途です。年金にしろ、医療にしろ、介護にしても。そのことで消費税も増税されている下で、今、格差と貧困がさらに拡大している状況です。だからこそ、今こそ住民に一番身近な自治体、品川区があらゆる努力をして、一般財源投入を含めて、軽減に踏み出すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/831364?Template=document&Id=3620#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":53812,"voices":191}}]);
